INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699301644', 'Kit Desodorante Aerosol Nivea Dry Impact For Men 200ml - 2 unidades', 'O Desodorante Aerosol Nivea Dry Impact For Men Possui em sua composição dobro de agentes minerais causando assim um efeito eficaz contra maus odores e transpiração. Modo de uso: Usar somente nas axilas. Aplique nas axilas á uma distancia de 15cm. Caso ocorra irritação e/ou prurido no local da aplicação, suspender o uso e procurar orientação médica. Sobre a marca: Ao longo dos anos a Nívea veio desenvolvendo produtos específicos para limpeza, hidratação, proteção e preservação dos nutrientes essenciais para uma pele sempre saudável e bem cuidada. O objetivo da Nívea sempre foi o mesmo: ajudar pessoas de todas as idades a aproveitarem o sol, onde e quando quisessem.', 51.27, 40.3, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-820oa-mnybyddta1ol03', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F18699301644', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
