INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20254184577', 'Limpador Desengoedurantes de Grill Fornos e Coifas 500ml Bellinzoni Limpeza Leve E Pesada', 'Áreas de Aplicação Fornos Fogões Fritadeiras Grelhadores Grelhas Pratos de Cozinha Finalidade Limpador alcalino altamente eficaz para limpeza de fornos, fogões, fritadeiras, grelhadores, grelhas e pratos de cozinha. Dissolve rapidamente as incrustações de óleo e graxa carbonizados. Contém agentes de limpeza penetrantes e desengordurantes que remove facilmente qualquer acúmulo de gordura. Instruções de Uso Aqueça a superfície a ser limpa (50 / 60º C ), usando o borrifador, espalhe o produto por toda área a ser limpa. Deixe agir alguns minutos. Esfregue bem o material e em seguida enxague bastante com água até que se remova toda sujeira acumulada. Em caso de sujeiras mais resistentes, repita a operação.', 63.15, 44.21, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgf1kh8lsyrr1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800925303%2F20254184577', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
