INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20239911173', 'Kit Wella Pro Inv Brilliance Sh 250 + Cd 200 + Masc 150', 'O Kit Wella Professionals Invigo Color Brilliance de tratamento para cabelos coloridos. Cuida da cor e proporciona brilho por mais tempo, além de garantir maciez. Wella Professionals Invigo Color Brilliance conta com fórmulas especiais, enriquecidas com ativos antioxidantes que ajudam a manter a cor nos fios e vibrante por até 7 semanas. Também possui perfume encantador, é amadeirado cítrico , o que se traduz em um aroma sofisticado. Preserve a cor de seu cabelo com a linha Wella Professionals Invigo Color Brilliance! * RESULTADO: Hidratação, Brilho * SUGESTÃO DE USO: Shampoo 1. Aplique no cabelo molhado e massageie desde a raiz do cabelo até fazer espuma; 2. Enxague bem. Condicionador 1. Aplique no comprimento do cabelo molhado; 2. Distribua o produto igualmente e então enxague bem. Máscara 1. Aplique no comprimento do cabelo molhado; 2. Deixe agindo por 5 minutos e então enxague bem. * OBSÇÕES: Imagem Meramente Ilustrativa. * ITENS INCLUSOS: 1 Shampoo Wella Professionals Invigo Color Brilliance 250 ml 1 Condicionador Wella Professionals Invigo Color Brilliance 200 ml 1 Máscara para Cuidado da Cor Wella Professionals Invigo Color Brilliance 150 ml', 553.9, 553.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/a5e64571d0db05fa9ec75b8739aaefdb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F20239911173', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23603777286', 'Kit 2 Mascaras Nutri Enrich 150ml - Wella Profissionals', 'Este kit Contém: 2 - Máscaras Invigo Nutri-Enrich Wella Professionals - 150ml Sobre o Produto: Máscara de Nutrição Profunda para cabelos secos ou ressecados. Deixa os cabelos nutridos e cheios de vitalidade. Contém ácido Oleico, Pantenol e Vitamina E, que protege os cabelos dos desgastes do dia-a-dia. Modo de usar Com cabelo limpo e úmido, aplique uma quantidade pequena da máscara nos cabelos, massageando mecha a mecha, do comprimento até as pontas. Deixe agir de 3 a 5 minutos. Emulsione. Enxague abundantemente. Finalize como desejar. Resultado: Cabelo hidratado, sedoso e com um brilho intenso. Cuidados/Restrições Evite o contato com os olhos. Caso isso aconteça, enxágue com água em abundância. Havendo irritação, suspender o uso e procurar orientação médica. Não ingerir. Manter fora do alcance de crianças. Uso externo. Tratamento Intenso para cabelos danificados. Protege instantaneamente contra a quebra causada pelos danos da escovagem e movimentos mecânicos. Contém aminoacidos da seda. Modo de usar: Aplicar os cabelos úmidos. Deixar agir durante 5 minutos. Enxaguar abundantemente.', 518.98, 251.75, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lksfd1lackns72', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F23603777286', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10414777496', 'Invigo Nutri-Enrich Shampoo de 1L - Wella Professionals', 'Sobre o Produto: Kit de Nutrição Intensiva. Indicado para cabelos secos e/ou ressecados. Fórmula profissional enriquecida com Oxidantes que protege a fibra, devolvendo a vitalidade e brilho dos cabelos. Modo de usar: Aplicar com os cabelos molhados. Massagear suavemente até fazer espuma. Em seguida Enxague. Repita se necessário. Após a lavagem dos cabelos, aplique uma pequena quantidade do Leave-in, espalhe mecha a mecha. Não é necessário enxaguar. Ingredientes: AQUA / WATER • SODIUM LAURETH SULFATE • SODIUM CHLORIDE, COCAMIDE MEA, SODIUM XYLENESULFONATE, SODIUM BENZOATE, PANTHENOL, PARFUM / FRAGRANCE, GLYCERIN, GUAR HYDROXYPROPYLTRIMONIUM CHLORIDE, SALICYLIC ACID, TETRASODIUM EDTA, TRISODIUM ETHYLENEDIAMINE DISUCCINATE. Cuidados/Restrições: Evite o contato com os olhos. Caso isso aconteça, enxágue com água em abundância. Havendo irritação, suspender o uso e procurar orientação médica. Não ingerir. Manter fora do alcance de crianças. Uso externo.', 359.63, 192.96, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lksffi3eu25va8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F361729924%2F10414777496', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
