INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206665801', 'Kit Gotíssima Gotas de Alfazema Gota Dourada Shampoo + Condicionador 300ml', 'O Kit Gotissima Gotas de Alfazema Gota Dourada Shampoo 300ml + Condicionador 300ml foi desenvolvido para revitalizar e restaurar cabelos danificados. Composto por óleos de coco e cenoura, além de vinagre de maçã, este kit age profundamente na estrutura capilar, proporcionando força, hidratação e controle do frizz. Benefícios do Kit Gotissima Gotas de Alfazema Hidratação intensa graças aos óleos naturais em sua composição. Redução do frizz e alinhamento dos fios. Reestruturação capilar para cabelos mais fortes e saudáveis. Perfume suave de alfazema, proporcionando frescor duradouro.', 35.9, 16.0, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-820lz-mlnucumuearp76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1382606196%2F58206665801', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
