INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898975599', 'Chicote Canbus My Link 2: Tracker Prisma Spin (2017 A 2019)', '**OBS ESSE CHICOTE NÃO SERVE EM PIONEER, RADIO E CENTRAL MULTIMIDIA ORIGINAL* **ASSIM QUE REALIZAR A COMPRA, INFORMAR A MARCA DA MULTIMIDIA EM QUE O CHICOTE SERÁ USADO** Chicote Canbus My Link 2: Cruze LT 2017 ACIMA / TRACKER (2017 A 2019) / ONIX / PRISMA / SPIN (2017 A 2019) / EQUINOX (2017 ACIMA) / S10 MIDNIGHT / TRAILBLAZER / HIGH COUNTRY (TODOS 2017 ACIMA) Descrição: Essencial na instalação dos aparelhos android, esse chicote só serve em multimidia CHINESA ou PADRÃO AIKON. Os chicotes fazem a correta ligação entre o rádio e o veículo de maneira segura, evitando danos por ligações incorretas ou corte de fios. Modelos compatíveis - multimidia CHINESA ou PADRÃO AIKON - Mantém a qualidade do Som do seu carro; - Integra todo o Sistema de áudio e comandos; - Mantém a originalidade e garantia do seu veículo. O QUE ACOMPANHA: 01x Chicote 01x CANBUS 01x Adaptador de antena 01x Adaptador de USB', 343.2, 302.02, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-824gq-mfjo62ipfmdr08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1613233738%2F23898975599', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294521591', 'Desengripante 300ml Spray Antiferrugem e Anticorrosivo', 'Anti Corrosivo 300Ml Spray Anti Ferrugem Desengripante **** PEÇA NOVA ********* GARANTIA E NOTA FISCAL ***** ANTI CORROSIVO 300ML SPRAY (ANTI FERRUGEM) Desengripante Bril Lub Fit TecBril ideal para desemperrar porcas, parafusos e peças oxidadas, enferrujadas e sujas. Com aroma suave é possui múltiplas aplicações, nas indústrias, nos automóveis, em motos, bicicletas, no uso doméstico e em equipamentos esportivos. Lubrifica e protege contra ferrugem e umidade. MRA', 13.2, 13.2, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-8257s-mfs6exzoi70re1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1223398266%2F23294521591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997672119', 'Kit 3 Armários Multiuso de Escritório Marrom/Nogal Nogal', 'O Armário para Escritório Tecno Mobili é feito em MDP, que é um material muito forte e de alta durabilidade, garantindo ao produto excelente estabilidade e resistência. O acabamento do Armário para Escritório Tecno Mobili é feito em baixa pressão (BP) com pintura fosca na cor branca, que protege o móvel contra ação do calor e da umidade, trazendo ainda mais qualidade para a peça. Sua estrutura prática e versátil apresenta duas portas com puxadores externos e quatro prateleiras, sendo que 3 delas são móveis, oferecendo mais opções de organização interna Garantia: 03 Meses Altura (cm): 172 Acabamento: BP Melamínico Largura (cm): 188 Tipo de Porta: Bater Porta em Vidro: Sim Possui Gavetas: Não Possui Rodízio: Não Porta com chave: Não Profundidade (cm): 32 Armário Suspenso: Não Ambiente Principal: Escritório Formato do Armário: Retangular Material Principal: MDP Necessita Montagem: Sim Tamanho do Armário: Alto (Acima de 150cm) Possui Mesa Retrátil: Não Número de Prateleiras: 4 Orientação do Armário: Vertical Quantidade de Armários: 3 Tipo de Armário de Escritório: Semi-Fechado Marca: Espresso Móveis Cor: Nogal Cor do Produto: Nogal Cor Predominante: Marrom', 1618.69, 1618.69, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-8259k-mr3jalbzbgn81f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22997672119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197634912', 'SHAMPOO + CREME MILAGROSO 3 EM 1 ÓLEO EXTRAORDINÁRIO ELSEVE', 'ESSE KIT CONTÉM: 1 CREME MILAGROSO ELSEVE 3 EM 1 ÓLEO EXTRAORDINÁRIO NUTRIÇÃO 500ML 1 SHAMPOO NUTRIÇÃO ÓLEO EXTRAORDINÁRIO ELSEVE 200ML Um cabelo seco parece estar sem vida, pois ele está opaco, sem brilho e tem um toque áspero. O segredo dos óleos de flores preciosas para uma nutrição perfeita & uma leveza infinita estão na linha Elseve Óleo Extraordinário Nutrição. O Elseve Óleo Extraordinário Nutrição com sua textura ultrafina e leve, é enriquecido em Micro-Óleos de Flores Preciosas que agem para combater o cabelo seco e sem brilho. Reconstrói a fibra, fazendo com que seu cabelo tenha uma nutrição perfeita, leveza infinita e um brilho excepcional. Nosso Creme Milagroso 3 em 1 é o seu aliado diário para você utilizar da maneira que deseja: para uma definição dos sonhos como creme de pentear, transformação dos sonhos como um tratamento intensivo e desembaraço dos sonhos como um super-condicionador. Desenvolvido com 6 óleos preciosos, o 3 em 1 de Óleo Extraordinário proporciona 6x mais brilho e preenche a fibra capilar para maior nutrição. Cabelos macios, suaves e extraordinários. Modo de uso: Aplique o shampoo nos cabelos molhados e massageie suavemente. Enxágue. Repita a operação se necessário. Como Usar o 3 em 1 - Condicionador: Aplique em todo o comprimento, até as pontas. Deixe o produto agir por 3 minutos e enxague abundantemente. - Tratamento Intensivo: Aplique em todo o comprimento, até as pontas. Deixe o produto agir por 5 ou mais minutos e enxague abundantemente. - Creme de Pentear: Aplique sobre o cabelo úmido ou seco. Não enxague. Penteie como de costume', 64.8, 64.8, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rdy9-lxcwz2l33xl69e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F22197634912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
