INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22999040289', 'Trava Pastilha Traseira Para Ford Transit 2.4 2006 a 2014', 'Trava Pastilha Traseira Para Ford Transit 2.4 2006 a 2014 **** PEÇA NOVA ********* GARANTIA E NOTA FISCAL ***** PRODUTO: JOGO TRAVA PASTILHA FREIO TRASEIRA MARCA: MRA IMPORTS CODIGO: 33099 ITENS INCLUSOS: 01 JOGO COM 4 TRAVAS PASTILHA DE FREIO TRASEIRA COMPATIVEL COM: FORD / TRANSIT 2.4 16V / 2006 / 2014 / 16v / 2,4 FORD / TRANSIT 2.4 8V / 2008 / 2011 / 8v / 2,4 Conheça a MRA Auto Peças Fundada em 1998 na cidade de Ribeirão Preto/SP, a MRA Auto Peças consolidou-se ao longo dos anos como uma referência no setor automotivo, oferecendo qualidade, confiança e atendimento especializado. Com mais de duas décadas de experiência no mercado, somos especialistas em peças para VANS, UTILITÁRIOS, veículos importados e SUVs, atendendo com excelência tanto clientes particulares quanto oficinas e frotistas. Nossa matriz está localizada em Ribeirão Preto/SP, e contamos ainda com filiais nas cidades de Araraquara e Franca, ampliando nosso alcance e fortalecendo nosso compromisso com a agilidade na entrega e o suporte técnico qualificado. Na MRA Auto Peças, você encontra as melhores marcas, preços competitivos e um time pronto para oferecer as soluções certas para o seu veículo. MRA Auto Peças – Tradição, confiança e qualidade desde 1998. MRA', 43.12, 43.12, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258n-mg2d7on6sh6xde', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1223398266%2F22999040289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12811084193', 'Cloro Floculante Clarificante para Piscinas 1 Litro MONTREAL', 'Cloro Floculante Clarificante 1 Litro MONTREAL O Floculante Montreal é eficaz na clarificação da água da piscina, promovendo a aglutinação e a decantação de partículas em suspensão e atuando também na eliminação de filmes oleosos. Depositada no fundo da piscina, a sujeira é facilmente removida na aspiração. O uso regular do Floculante Montreal mantém a água da piscina cristalina, auxiliando o processo de filtração. Informações Importantes: Certifique-se de que o pH da piscina esteja ajustado entre 7,2 e 7,8. Se necessário, faça o ajuste dele. Retrolave o filtro e coloque-o em funcionamento na posição “filtrar”. Inicie com uma aplicação de 2 a 4 ml para cada 1.000 l de água. Mantenha uma aplicação semanal de 1,5 ml para cada 1.000 l de água. Deixe o filtro em funcionamento na posição “filtrar”, de 6 a 8 horas. Após a clarificação, aspire a sujeira floculada no fundo da piscina e retrolave o filtro. O FLOCULANTE MONTREAL dispensa o uso de Sulfato de Alumínio e outros decantadores, não altera o pH e não interfere na atividade de outros produtos comumente usados no tratamento da água. Quantidade: 1 Litro Marca: Montreal * Imagens meramente ilustrativas.', 35.9, 29.9, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/a3d75ef42d8586a26e0aadae52ca5ff6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F12811084193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12110560920', 'Soprador Térmico 1600W 550 Graus GHG-180 BOSCH', 'Soprador Térmico 1600W 550 Graus GHG-180 BOSCH Soprador Térmico de Ar Quente GHG 180, com potência de 1600 W, une eficiência, segurança e custo benefício. Com 3 níveis de temperatura (60º, 350º e 550º), ela realiza o trabalho em diversas aplicações, além de permitir sua utilização de maneira estacionária. É muito durável, passando por testes rigorosos, que asseguraram mais de 500 horas de funcionamento contínuo, além de ser 100% segura, pois conta com proteção contra sobreaquecimento, garantindo sua segurança especialmente em caso de obstrução do fluxo de ar. Acompanha: 1 Bico redutor DADOS TÉCNICOS: Potência nominal: 1.600W Dimensões (LxCxA): 86 x 238 x 244 mm Temperatura de trabalho: 50 – 525 °C Fluxo de ar: 350 – 550 l/min Tempo de aquecimento: 1min Regulação do fluxo de ar: de 3 níveis Voltagens Disponíveis: 110V ou 220V Modelo: GHG-180 Código de Fábrica: 060194D0E0000 Garantia: 1 ano Marca: BOSCH * Imagens meramente ilustrativas.', 635.9, 635.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/f6b94fc121578e139d918784ca59a509', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F12110560920', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
