INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58206084816', 'Gel Lubrificante Íntimo K-med 100g', 'Fácil de manusear. Proporciona mais conforto e segurança, sem perder a sensibilidade. Solúvel em água, transparente, não gorduroso, não tem cheiro, é facilmente removível e não mancha. Um produto muito vendido e muito adquirido no mercado de sex shop. ÓTimo para iniciantes no mercado erótico. Produto capaz de facilitar na hora da penetração e na relação sexual em geral. Região de Aplicação: Ânus, vagina, pênis. Função: Lubrificar e ajudar na hora da penetração. Indicado: Para mulheres com pouca lubrificação. Para homens que desejam facilitar na hora da penetração. Contraindicação: Para pessoas com problemas de saúde ou pequenas feridas na região do ânus, vagina ou pênis. Público-alvo: Homens que queiram prolongar a hora h sem machucar sua parceira. Mulheres com problemas de lubrificação. Modo de uso: Tire da caixa e coloque uma quantidade ideal no local indicado e que ajude na hora da penetração. Espalhe o produto no local aplicado e comece a penetração sem medo. Precauções: Caso aja algum tipo de irritação, alergia. Suspenda o uso e procure um médico. Deixe fora do alcance das crianças.', 29.99, 29.99, NULL, 'Health > Sexual Wellness > Lubricants', 'https://cf.shopee.com.br/file/sg-11134201-8260x-mlc8m66p6g3sa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1264096278%2F58206084816', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
