INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18897669587', 'Mangueira Respiro Óleo Gm S10 1994 a 2011 - 1334387 - 8167', 'Mangueira Respiro Óleo Gm S10 1994 a 2011 1334387 8167 Ventilação Tampa Comando 2.2/2.4 4Cil MPFI (Ø:22mm)(Medida.:5cmx9cm) Essa mangueira serve para aliviar a pressão de dentro do cárter pelo vazamento dos gases dos anéis. Isso é normal e chama-se ventilação positiva. Esse gás é reabsorvido junto com o vapor do óleo pelo motor para ser queimado dentro da camara de combustão, por isso ela fica ligada logo na entrada de ar do motor, ou seja, junto do filtro de ar. Isso foi desenvolvido para não poluir o ar com esses gases.', 13.91, 13.91, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd6z-luf9yk6o39ip14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18897669587', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
