INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697667052', 'Tampa Reservatório Expansão Fiat Doblo 2001 a 2010 - 111804 - 23047', 'Tampa Reservatório Expansão Fiat Doblo 2001 a 2010 111804 23047 FIRE 8/16V - 1,4 BAR (TAMPA AZUL) Além de fechar o reservatório de expansão, esta tampa também mantém a pressão do sistema, através de uma válvula que se abre, dando passagem ao excesso de pressão. O controle da pressão faz com que o líquido tenha uma circulação completa, atingindo todos os pontos do motor, tenha um ponto de ebulição mais elevado, impede a formação de vapor no interior do motor, permite a entrada de ar atmosférico quando a temperatura do líquido abaixa.', 25.87, 25.87, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd61-luf6cd017tmvca', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F21697667052', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
