INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259763595', 'Kit Skincare Kokeshi Pele de Porcelana Olhos de Gueixa Sérum Olheiras', 'KIT SKINCARE KOKESHI PELE DE PORCELANA OLHOS DE QUEIXA SÉRUM OLHEIRAS O Kit Skincare Completo Kokeshi reúne os principais cuidados para uma pele mais hidratada, uniforme e iluminada, além de tratar profundamente a área dos olhos. Com ativos poderosos e tecnologia inspirada na rotina oriental de beleza, esse kit proporciona uma rotina completa para quem busca uma pele com efeito “pele de porcelana”, mais saudável e radiante. O sérum facial atua na uniformização e hidratação da pele, enquanto os produtos para a área dos olhos ajudam a reduzir olheiras, bolsas e sinais de cansaço, deixando o olhar mais jovem e descansado. O KIT CONTÉM: -1x Hidratante Pele de Porcelana 30g -1x Sérum Facial Pele de Porcelana 30ml -1x Hidratante Olhos de Gueixa 15g -1x Sérum Roll-On Adeus Olheiras 10ml BENEFÍCIOS: -Hidratação profunda da pele -Auxilia na uniformização do tom -Efeito “pele de porcelana” -Melhora da textura da pele -Aparência mais iluminada e saudável -Auxilia na suavização de linhas finas -Rotina completa de skincare -Redução de olheiras e bolsas MODO DE USO(ROTINA COMPLETA) -Aplique o Sérum Facial Pele de Porcelana na pele limpa. -Em seguida, utilize o Hidratante Pele de Porcelana para selar a hidratação. -Na área dos olhos, aplique o Sérum Roll-On Adeus Olheiras. -Finalize com o Olhos de Gueixa, espalhando suavemente. Utilizar diariamente, de manhã e à noite. INDICAÇÃO DE USO: -Todos os tipos de pele -Ideal para rotina completa de cuidados faciais -Indicado para manchas, textura irregular, olheiras e sinais de cansaço', 149.9, 104.93, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/br-11134207-820m7-mqby8mgbhipt11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F395166866%2F58259763595', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
