INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21598183525', 'Kit Skazi Vegano Ozônio Com Jojoba Shampoo E Condicionador 1 Litro', 'KIT SKAZI VEGANO OZONIO COM JOJOBA SHAMPOO E CONDICIONADOR ANTIQUEDA REVITALIZANTE 1 LITRO Transforme a sua rotina de cuidados capilares com o poder da natureza e da ciência. O Kit Skazi Vegano Ozônio com Jojoba, composto por Shampoo e Condicionador de 1 litro cada, é a combinação ideal para quem busca cabelos mais saudáveis, fortes, hidratados e com brilho intenso desde a primeira aplicação. Benefícios do Kit Skazi Ozônio com Jojoba: - Fórmula 100% vegana - Livre de parabenos, petrolatos, sal e ingredientes de origem animal - Não testado em animais - Revitalização completa com ativos naturais - Indicado para uso diário - Ideal para todos os tipos de cabelo MODO DE USAR: - Shampoo: Aplique na raiz com os cabelos molhados, massageie suavemente e enxágue bem. Repita se necessário para uma limpeza profunda. - Condicionador: Aplique no comprimento e pontas, deixe agir por 2 a 3 minutos e enxágue completamente. 💡 Dica profissional: Para potencializar os resultados, inclua a Máscara Skazi Vegano Ozônio com Jojoba na sua rotina semanal de cuidados. Compromisso com você e com o planeta: A linha Skazi Vegano com Ozônio e Jojoba foi desenvolvida com consciência ecológica e ética. Nossos produtos são livres de crueldade, sem ingredientes de origem animal e formulados com ativos que respeitam tanto o seu cabelo quanto o meio ambiente. Informações Necessárias Compra Segura Com Garantia Shopee Somos Vendedores Indicado Pela Shopee 📦⚡ ENVIO RÁPIDO APÓS CONFIRMAÇÃO DE PAGAMENTO ⚡📦', 65.9, 59.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-820ls-mptyykqgq1vm55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F725026030%2F21598183525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207426248', 'Kit com 4 Shampoos Tonalizantes Color Change Preto - Kiss New York', 'Dê tchau aos grisalhos em apenas 3 minutos usando Color Change Shampoo! Com fórmula de ação rápida, o shampoo tonalizante da Kiss NY garante 100% da cobertura dos grisalhos em um período de apenas 3 a 7 minutos. Além de uma fórmula vegana, não testada em animais e livre de amônia e parabenos, o produto ainda é rico em Ginseng, ativo que fortalece a raiz do cabelo e elimina as toxinas e também conta com Extratos Naturais que promovem o crescimento dos fios e ajudam a reter a cor do cabelo por mais tempo.É indicado para todos os tipos de cabelos, inclusive os quimicamente tratados e sua fórmula garante mínima transferência para toalhas e roupas.', 151.9, 151.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8261h-mm64v8w3wtfp0d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1687531684%2F58207426248', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254998202', 'Pó Compacto Super Fixo - Ruby Kisses', 'A linha Super Fixo que você já ama agora com ativos de skincare! O Pó Compacto Super Fixo da Ruby Kisses é o produto ideal para proporcionar maior cobertura e durabilidade para a sua maquiagem. Sua nova fórmula contém Ácido Hialurônico, Pantenol e Vitamina E, que possuem ação antioxidante e hidratante. Quando o assunto é controlar o brilho e o excesso de oleosidade do rosto, esse pó compacto é o queridinho, pois sua textura ultra leve e fininha não esfarela e ainda garante um efeito matte aveludado. Disponível em 14 cores que contemplam diferentes tons de pele, o produto evita aquele efeito “derretido” no visual já que sua fórmula duradoura adere super bem ao rosto. Além disso, a embalagem já acompanha espelho e uma esponja premium – o combo perfeito para você levar na bolsa e fazer retoques sempre que quiser!', 37.9, 37.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-8260b-mkjz7z9kqc5i36', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1687531684%2F58254998202', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
