INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201423827', 'Roteador Repetidor Wi-fi Gigabit Wifi Rede Ap 6 Antenas', 'ROTEADOR REPETIDOR 2.4GHz MODO AP COM 6 ANTENAS KNUP DESCRIÇÃO: O Roteador Wi-Fi Knup Rede Mesh 300Mbps RW403/M é ideal para quem busca mais conexão, transmitindo internet para diversos equipamentos sem o uso de fios. Compatível com smart TVs, smartphones, tablets, computadores e outros aparelhos que podem ser conectados à rede. Capaz de conectar até 64 dispositivos, o RW403M oferece internet de alta velocidade (Wi-Fi até 300Mb/s) para seu telefone, tablet ou laptop, permitindo que toda a família escolha suas atividades online, desde aprendizado até jogos e streaming de vídeo. Controle dos pais disponível para garantir navegação segura para os filhos, com possibilidade de bloquear o acesso a sites inadequados e limitar o acesso a dispositivos selecionados. ESPECIFICAÇÕES: - Marca: Knup - Modelo: RW403M - Cor: Branco - Controle Parental - Voltagem: Bivolt CARACTERÍSTICAS: - Interface: Porta de energia - Memória: SDRAM DDR2 32MB / Flash: 8MB - Fonte de alimentação: AC/DC 100~240Vac / 50/60Hz, 0.1A Máx, Classe II - Botões: Reset e Seleção CONECTIVIDADE: - Bandas de frequência sem fio: 2.4GHz - Porta de Rede: Quatro portas LAN de 10/100Mbps (Fast Ethernet), adaptação automática - Taxa de transmissão sem fio: 300Mb/s em uma rede Wi-Fi de 2.4GHz SEGURANÇA: - WPA3 - Controle de acesso Wi-Fi - Wi-Fi para convidados - Controle para os pais - SSID oculto - Firewall - DMZ DIMENSÕES E PESO: - Altura: 3.1cm - Largura: 12.8cm - Comprimento: 19.5cm - Peso: 235g', 350.0, 97.89, NULL, 'Computers & Accessories > Network Components > Modems & Wireless Routers', 'https://cf.shopee.com.br/file/br-11134207-820l5-ml9gkrj6he6fab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1655406395%2F58201423827', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
