INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798702566', 'Kit 10 Caixas Congelamento P/ Alimentos Pão De Queijo Massas Bolos E Salgados PEAD Virgem Branca', 'BANDEJA PLÁSTICA VAZADA EM POLIETILENO (PEAD) SEM TAMPA - BANDEJA PARA CONGELAMENTO DE PÃES Nossa qualidade e expertise no mercado, garantem produtos duradouros e resistentes. Essa é uma bandeja rasa pode ser utilizada em câmara fria devido ao seu material fabril (PEAD). Bandeja Plástica especial para congelamento de pães quando fornecido na versão aberta. Carga máxima para uma pilha: 100 kg. Limite de carga quando paletizada: 1300 kg Perfeita para congelamento de pães e massas, mercados na exposição de embutidos. Padarias e Pizzarias - para descanso de massas de pães e pizzas. Buffet,Restaurante, Lanchonete e também uso doméstico. ESPECIFICAÇÕES: *MEDIDAS EXTERNAS: -ALTURA: 6,4CM -LARGURA: 40CM -COMPRIMENTO: 60CM *MEDIDAS INTERNAS: -ALTURA: 4,8CM (ALTURA LIVRE INTERNA) -LARGURA: 36,5CM -COMPRIMENTO: 56,5CM -PESO: 900G 1 COMPRA = 10 PEÇAS *ENVIO MAXIMO DE 2 KITS (20UNIDADES), POR COMPRA* AGUARDAMOS SUA COMPRA!', 575.0, 449.99, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rdvx-mbwsvnhij3xj7f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F601021305%2F23798702566', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19698774159', 'KZ Krila 1DD + 1BA Fones De Ouvido Intra-Auriculares Ajustáveis HiFi Com Fio 4 Níveis De Afinação E 16 Opções De Sintonia Cabo Destacável De 2 Pinos 3,5mm Plug (Microfone)', '1.A configuração da tecnologia híbrida de Krila foi projetada para compensar as deficiências de alta frequência das unidades de driver dinâmico convencionais. A experiência de audição acústica perfeita. 2.Os cabos folheados a prata sempre foram um acessório para fones de ouvido de nível profissional. Nesse caso, temos Krila equipada com cabos banhados a prata. O cabo banhado a prata melhora a qualidade geral do som dos fones de ouvido. 3.Os fones de ouvido com rebote lento* bloqueiam efetivamente os fones de espuma externa e proporcionam um ajuste macio e confortável que abraçam o canal auditivo de forma eficaz e proporcionam um ajuste macio e confortável que abraça o canal auditivo. Eles são projetados em mente com considerações ergonômicas e vêm com três tamanhos de fones de ouvido de silicone (S, M, L) para acomodar diferentes formas de orelha. 4.As conchas de fone de ouvido são feitas de metal polido por espelho e passam por um processo intrincado de várias técnicas de polimento de fone de ouvido. Design de câmara de resina avançada e amigável à pele, então combinado com tecnologia avançada de inlay e design de câmara de resina amigável à pele, apresentando uma aparência de alta qualidade e requintada.', 159.0, 159.0, NULL, 'Audio > Earphones, Headphones & Headsets', 'https://cf.shopee.com.br/file/cn-11134207-7qukw-ljp15d2fedis2d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F514674110%2F19698774159', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
