INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21897985411', 'Kit Novex Ritual Dorama Um toque de Paixão', 'Tsubaki, o seu novo queridinho A nossa linha exclusiva, com o poderoso e inédito ativo Tsubaki, foi especialmente desenvolvida para cuidar dos fios de dentro para fora, da raiz às pontas. Extraído da preciosa flor de camélia japonesa, o Tsubaki é conhecido há séculos por seus incríveis benefícios para a saúde dos cabelos. Além de nutrir os fios, sua fórmula de alta tecnologia ajuda a selar as cutículas capilares, proporcionando mais força e brilho. Esse kit contém: 1- Shampoo Novex Ritual Dorama 300mL 1- Condicionador Novex Ritual Dorama 300mL 1- Óleo Capilar Novex Ritual Dorama 100mL 1- Creme de Tratamento Novex Ritual Dorama 1kg', 110.0, 110.0, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7reqc-m2qqc5psmkyvc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F719923009%2F21897985411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21498272486', 'Brinco Argola Com Detalhes Lua E Estrela Rommanel Original Folheado a Ouro 523350', 'Brinco Argola Com Detalhes Lua E Estrela Folheado a Ouro. INFORMAÇÕES Rommanel Original com Certificado e Etiqueta GARANTIA DE 01 ANO .................................................................... REVENDEDORA AUTORIZADA ROMMANEL. GANDRA SHOPPING - Loja Virtual Rommanel. .................................................................... Código: 523350.BRINCO ARGOLA COM BORDAS TRABALHADAS COM LUA E ESTRELA EM VOLTA DA PEÇA. MED 1,1 CM DIÂMETRO INFORMAÇÕES PRINCIPAIS: - 01 Par de Brincos. - Gênero: Feminino - Material: Folheada a Ouro 18k, 22k e 24k - Garantia do Fabricante: Contra defeito de fabricação - Origem: Nacional - Postagem em até 24 horas após confirmação da compra - Fotos originais do produto. INFORMAÇÕES COMPLEMENTARES: ****************QUALIDADES: *************** - Joia totalmente antialérgica, NÃO DA ALERGIA!!! - Não causa coceira ou vermelhidão na pele. - Não escurece. - Não perde a cor nem o brilho. - Muita durabilidade!! - Pessoas com excesso de ÁCIDO ÚRICO no organismo também podem usar! - Produtos Rommanel são 100% livres de níquel e chumbo. - Você pode usar com toda a tranquilidade e segurança!!! - Não use bijuteria, use ROMMANEL!!!!_ *************O QUE VEM JUNTO?***************_ Ótima pergunta! Nossos produtos sempre vem com: - Certificado de garantia joia oficial Rommanel. - Etiqueta original do produto. - Embalagem exclusiva original Rommanel de presente. - Sua joia perfeitamente embalada e super protegida ********FOLHEAGEM A OURO:**************** - Joias em ouro amarelo e ouro branco_ - Camada de ouro muito mais espessa - 3 processos de "folheagem" a ouro 18k, 22k e 24k - Aspecto visual semelhante a joias de ouro maciças_ - Muito mais resistente que outras semijoias. ++++ COMO FUNCIONA A GARANTIA ++++ A Rommanel realiza a troca de produtos autênticos (verificar abaixo como reconhecer uma joia Rommanel) que apresentem exclusivamente defeitos de fabricação. Excluem-se da garantia produtos decorrentes de quedas, uso inadequado, acidentes de qualquer natureza, desgastes nas peças como: arranhões, amassados, quebras, perda de pedras, manchas, com ajustes feitos por terceiros ou contato com agentes químicos que possam causar danos aos materiais de sua joia. Por essa razão, pedimos que leia atentamente o certificado de garantia, especialmente a seção referente aos cuidados especiais necessários com a sua joia São excluídas da garantia joias que foram gravadas.', 146.4, 99.99, NULL, 'Fashion Accessories > Earrings', 'https://cf.shopee.com.br/file/sg-11134201-7rdwv-md2js5dquxce80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1593190827%2F21498272486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
