INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44506686379', 'Bolsa p/ Ferramentas 14 Bolsos Alças Reforçadas MTX', 'Bolsa para ferramentas MTX compacta e resistente, projetada para organizar e transportar ferramentas com praticidade. Com 14 bolsos, oferece espaço setorizado para chaves, alicates e acessórios, mantendo tudo acessível durante o trabalho. Seu formato robusto de 305x190x225 mm alia capacidade e portabilidade, ideal para profissionais e hobistas que precisam de uma solução prática para armazenamento. Construção simples e leve facilita o transporte sem ocupar muito espaço. Características: Modelo: 9029255 Referência: 9029255 Bolsos: 14 Dimensões: 305x190x225 mm Quantidade: 1 peça Marca: MTX Benefícios: Organização eficiente com 14 bolsos para separar ferramentas e acessórios. Portabilidade facilitada por tamanho compacto e formato prático. Acesso rápido às ferramentas para maior agilidade no trabalho. Economia de espaço sem comprometer a capacidade de carga. Versátil para uso profissional e doméstico. Conteúdo da embalagem: 1 bolsa para ferramentas MTX, 14 bolsos, 305x190x225 mm.', 109.44, 85.06, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825zw-mlccwqb4m7m024', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F44506686379', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
