INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43175260642', '(Elegante) Lovito Vestido Simples Assimétrico Primavera/verão Vestido Claret para Mulheres L155ED1471', '✅DESTAQUES -❤️Simples -❤️Assimétrico -❤️Botão frontal -❤️Boa textura -❤️Primavera e verão -❤️Zip lateral ✅DESCRIÇÕES Estampa / Padrão:Por favor Estilo:Elegante Tipo de vestido:Alargado Tamanho Plus:Não Material:Poliéster Composição:95% Poliéster + 5% Elastano Tipo de modelagem: ajuste regular Transparência:Não Esticar:Não flexível Feito na China ✅O PACOTE INCLUI 1XVestir ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.😊', 66.5, 49.5, NULL, 'Women Clothes > Dresses', 'https://cf.shopee.com.br/file/sg-11134201-82595-mfulpd4o0e8ce7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F43175260642', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256326110', 'Ar Condicionado Split Cassete 4 Vias Elgin Wi-Fi 48000 BTUs Frio Inverter 220V R32 KXFE48C2CA', 'Ar Condicionado Split Cassete 4 Vias Elgin Wi-Fi Inverter 220V - Climatize grandes ambientes com potência e eficiência O Ar-Condicionado Split Cassete 4 Vias Elgin Inverter foi desenvolvido para climatizar ambientes comerciais de médio e grande porte com eficiência e conforto. A distribuição de ar em 4 vias garante ventilação uniforme e suave, enquanto a instalação no teto mantém o espaço livre e bem integrado ao ambiente. Com tecnologia Inverter, oferece refrigeração estável, menor consumo de energia e operação silenciosa. Possui 46000 BTUs de capacidade, modo frio, além das funções Timer, Auto Restart e Conforto, que tornam o uso prático e contínuo. Conta com painel de LED com indicador de temperatura, controle remoto iluminado, serpentinas de cobre para maior durabilidade e utiliza gás ecológico R32, com menor impacto ambiental. A conectividade Wi-Fi já vem integrada. Climatização eficiente, uniforme e pensada para o uso profissional. **Especificações Técnicas:** Marca: Elgin Modelo: KXFC48C2WACA Modelo da Evaporadora: KXFI48C2WA Modelo da Condensadora: KXFE48C2CA Modelo da Grelha: KXZP00N2DA Tecnologia: Split Inverter Ciclo: Frio Capacidade: 48000 BTUs Voltagem: 220V Classificação Energética: A Consumo de Energia: 1904 kWh/ano Vazão de Ar: 3170 m³/min Nível de Ruído: Evaporadora - 51 dB / Condensadora - 57 dB Gás Refrigerante: R32 Modos de Operação: Refrigerar Funções: Timer, Auto restart, Função conforto Conectividade Wi-Fi: Incluso Selo Anatel: Sim — Nº de homologação: 16470-23-11765 Material da Serpentina: Cobre Desnível Máximo entre Unidades: 15 m Dimensões Evaporadora: 29,5 A x 85 L x 85 P cm Dimensões Condensadora: 86 A x 103,5 L x 43 P cm Dimensões Grelha: 11 A x 95,5 L x 95,5 P cm Peso Evaporadora: 27,7 Kg Peso Condensadora: 69,2 Kg Peso Grelha: 7,65 Kg Garantia: 36 meses OBS: Kit de instalação não incluso. A instalação deve ser realizada por técnico especializado.', 19999.2, 19999.2, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/br-11134275-820m4-mlgfjxqittdz7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F889973435%2F58256326110', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
