INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698318082', 'Enronew 150mg Com 10 Comprimidos - World', 'Descrição ENRONEW 150 mg é um antimicrobiano de amplo espectro de ação à base de Enrofloxacina indicado para cães e gatos de até 30 kg de peso, no tratamento de infestações causadas por bactérias Gram + e Gram -, espiroquetas e micoplasma sensíveis a este princípio ativo. Trata de: infecções dérmicas, infecções de ouvido, tratamento gastrointestinal (diarreia), infecções respiratórias e infecções gênito urinárias. Atualmente vem sendo recomendada em abordagens clínicas de animais com Leishmaniose. COMPRIMIDOS DE 150 mg Animais de 15 kg | Meio comprimido Animais de 30 kg | 1 comprimido Animais de 45 kg | 1 e meio comprimido Animais de 60 kg | 2 comprimidos', 29.98, 21.1, NULL, 'Pets > Pet Healthcare > Medication', 'https://cf.shopee.com.br/file/br-11134207-820m0-mnee0zenbsht10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450664666%2F22698318082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49562892989', '(New Arrival) Lovito Macacão Boho Assimétrico de Flores com Ombro À Mostra para Mulheres Primavera/Verão JRB199P2D426', '✅DESTAQUES -❤️Assimétrico -❤️Flores -❤️Ombro Frio -❤️Macio e confortável -❤️Primavera e verão -❤️Feriado ✅DESCRIÇÕES Estampa / Padrão:Floral Estilo:Boho Tamanho Plus:No Material:Poliéster Composição:100%Polyester Tipo de modelagem:Regular Fit Transparência:No Esticar:Non-stretch Feito na China ✅O PACOTE INCLUI 1XMacacão ✅INTRODUÇÃO LOVITO A Lovito é uma marca em crescimento que acredita no poder das meninas. Estamos comprometidos em oferecer opções de roupas fashion e acessíveis, para todos os estilos, necessidades e identidades. Acreditamos que a moda deve ser divertida, liberadora e fazer você se sentir incrível. Afinal, o melhor acessório para qualquer look é a autoconfiança! ✅NOTAS DE COMPRA Antes de comprar, dê uma olhadinha na tabela de medidas disponível no site. Lembre-se de que, por serem feitas manualmente, as medidas podem variar de 1 a 2 cm. As cores dos produtos também podem ter pequenas diferenças em relação às fotos, dependendo da iluminação e das configurações do seu dispositivo. Siga nossa loja e conheça novos itens e as melhores ofertas para você!! Se você tiver alguma dúvida, converse conosco e responderemos o mais rápido possível.', 87.0, 60.5, NULL, 'Women Clothes > Jumpsuits, Playsuits & Overalls > Jumpsuits', 'https://cf.shopee.com.br/file/sg-11134201-8259p-mqx0994zkiysbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F426378412%2F49562892989', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
