INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58254215601', 'Kit 2x Coenzima Q10 200mg com Vitamina E 60 Caps Nutrilibrium', 'COENZIMA Q10 E VITAMINA E INGREDIENTES: Coenzima Q10, Vitamina E (Acetato de DL-alfa-tocoferol) e Antiumectantes Talco Farmacêutico. INGREDIENTES DA CÁPSULA: HPMC (hidroxipropilmetilcelulose), Água purificada e Corante. NÃO CONTÉM GLÚTEN. SUGESTÃO DE USO: Sugere-se a ingestão de 2 (duas) cápsulas 1 (uma) vez ao dia. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. ADVERTÊNCIAS: “ESTE PRODUTO NÃO É UM MEDICAMENTO.” “NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM.” “MANTENHA FORA DO ALCANCE DE CRIANÇAS.” “ESTE PRODUTO NÃO DEVE SER CONSUMIDO POR GESTANTES, LACTANTES E CRIANÇAS”. CONSERVAÇÃO: Manter em lugar fresco, não úmido e ao abrigo da luz. Não consumir o produto se o lacre de proteção estiver violado. Após aberto, consumir preferencialmente em 60 dias.', 182.49, 145.9, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/br-11134207-820l7-mopvjk8t0wzna9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443076516%2F58254215601', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
