INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397916352', 'Kit Fácil 6 E 6x9 Polegadas Som Automotivo + Rádio Bluetooth', 'Os novos alto-falantes da LeSon JB Flex , com 55W Rms cada, apresenta qualidade, desempenho e simplicidade, razão do melhor custo-benefício, sem abrir mão da qualidade. Ótima qualidade de material, design moderno, indicado pra instalação nas portas do veículo. São fáceis de instalar, possuem qualidade de som e deixa o seu carro com um design mais moderno. Além disso, o JB Flex Polegadas possui uma resposta de frequência ampla e equilibrada, reproduzindo com fidelidade todos os detalhes musicais. Seu ótimo desempenho permite que você desfrute de uma experiência sonora excepcional enquanto está na estrada. Especificação Técnica: - Potência RMS: 55 Wrms (cada alto-falante) - Impedância Nominal: 4 ohms - Woofer de 6 e 6x9 Polegadas - Material: Cone Polipropileno PP - Tipo de falante: Multi-vias (Woofer + Tweeter) - Borda emborrachada - Sensibilidade: 87 Db - Resposta de frequência: 37 Hz a 20 Khz - Tweeter Piezzo - Bobina Simples Radio MP3 para som automotivo UNIVERSAL com APPCONTROL Especificações: • Aplicativo E-Way Link • Potencia 4x25w • Compatível com USB / SD • 4 saídas RCA • Radio FM Estéreo com sintonia eletronica. • Display LED • Função de armazenamento de memoria automática. • Funçoes INTRO / PAUSE / REPEAT / EQ / BASS / TRE / FAD / BA / CLASSIC / ROCK / POP • Bluetooth • Reproduz musicas por pasta • Aceita pen drive ate 64gb. Itens Inclusos: • Radio MP3 1 din • Chicotes • AppContron Carlive • Manual Conteúdo da Embalagem: KIT Fácil 6 Polegadas e 69 Polegadas JB Flex 110W + Rádio FP100 Garantia do vendedor: 3 meses', 269.99, 269.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-7rdwy-m17e6