INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23691091283', 'Jogo de Chaves Combinadas 15 Peças Tramontina PRO', 'Ideal para apertar e afrouxar parafusos ou porcas com perfil quadrado ou sextavado, as chaves da Tramontina PRO são fabricadas com matéria prima que garante alta resistência e durabilidade. Para perfeito funcionamento é importante usar a chave de tamanho compatível à cabeça da porca ou parafuso. Com as chaves da Tramontina PRO, quem passa aperto é o parafuso. As chaves de aperto são produzidas em aço ligado com cromo vanádio (Cr-V), e apos submetidas a testes rigorosos de torque para atender a norma DIN 1711-1.O novo perfil Hyper Drive, em alguns modelos de boca tipo estrela, reduz a fadiga das chaves, prolongando sua vida útil.O teste de dureza é realizado em vários pontos para assegurar a resistência ao desgaste da chave durante o uso ininterrupto.Alguns tipos de chaves de aperto são fornecidos em bitolas métricas e em polegadas, para os diversos fixadores disponíveis.Afrouxar e apertar parafusos e porcas sextavadas e quadradas.As ferramentas são produzidas e testadas conforme normas específicas. - Medidas Chaves Combinadas: 10mm, 11mm, 12mm, 13mm, 14mm, 17mm, 19mm, 22mm, 24mm, 27mm, 30mm, 32mm, 6mm, 7mm, 8mm. Ideal para apertar e afrouxar parafusos ou porcas com perfil quadrado ou sextavado, as chaves da Tramontina PRO são fabricadas com matéria prima que garante alta resistência e durabilidade. Para perfeito funcionamento é importante usar a chave de tamanho compatível à cabeça da porca ou parafuso. Com as chaves da Tramontina PRO, quem passa aperto é o parafuso.', 419.9, 413.29, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvdf-lg5h6gpernpc5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23691091283', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23497503479', 'Óleo Lubrificante Power 1 Racing 10W50 1L (3381099) - Castrol', 'O Óleo Lubrificante Power 1 Racing 10W50 1L (3381099) - Castrol, é um lubrificante 100% sintético para motos modernas e de alta performance com motores 4 tempos, desenvolvido para motociclistas que gostam da adrenalina de pilotar. A condução severa coloca a moto em condições extremas, resultando em maiores perdas devido ao atrito. É comprovado que a nova fórmula de Castrol POWER1 Racing com Race Derived Technology™ se mantém resistente e proporciona uma maior aceleração na pista. - Permanece forte, mesmo em condições de competição - Proporciona melhor aproveitamento da potência e aceleração - Cumpre os requisitos dos motores equipados com catalisador - Especificações Técnicas: • Atende ou excede os seguintes padrões da indústria: API SN; JASO MA-2; SAE 10W-50. • Capacidade: 1 Litro • Viscosidade: 10W50 • Aplicação: Recomendado para motores a gasolina • Peso: 0,900g • Dimensões: 6x9,5x26,5 cm Refêrencia: 3381099 Marca: CastrolO Óleo Lubrificante Power 1 Racing 10W50 1L (3381099) - Castrol, é um lubrificante 100% sintético para motos modernas e de alta performance com motores 4 tempos, desenvolvido para motociclistas que gostam da adrenalina de pilotar. A condução severa coloca a moto em condições extremas, resultando em maiores perdas devido ao atrito.', 144.9, 144.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-7rd6l-lv537jxvivh45b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23497503479', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
