INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094280403', 'Kit Tênis Infantil Goods E Caneta Touch Minipé Mp2549s', 'O KIT TÊNIS INFANTIL GOODS E CANETA TOUCH MINIPÉ MP2549S é perfeito para as crianças que adoram esportes e brincadeiras ao ar livre. Com um design moderno e confortável acompanhado por 5 divertidas caneta touch para estimular a criatividade. Esse kit é ideal para presentear e divertir os pequenos. Seu material de alta qualidade garante durabilidade e resistência, sendo uma opção sustentável para o consumo consciente.. MODELO: 3332549 REFERENCIA: MP2549S MARCA: Minipé MATERIAL DA PALMILHA: EVA MATERIAL DA SOLA: Borracha MATERIAL INTERNO: Têxtil ACABAMENTO: Colado/Costurado GRUPO DE IDADE: Infant MATERIAL DO SAPATO: Sintético DETALHES: ATENÇÃO: O tênis goods poderá ser colorido apenas uma vez! Caso necessite lavar o calçado, para não manchar, lave com sabão neutro e água: não use máquina de lavar ou secar; use pano úmido e escova de cerdas macias: seque na sombra; não pendure no varal; não use alvejante.Acompanha 5 canetas coloridas com variações de cores (aleatória). GÊNERO: Female', 143.99, 143.99, NULL, 'Baby & Kids Fashion > Girl Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-7rdvp-mcwhizbfgmrya7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784810315%2F23094280403', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697034188', 'Coxim Motor Renault Scenic 1999 a 2002 - 139117 - ACX05020', 'Coxim Motor Renault Scenic 1999 a 2002 139117 ACX05020 (Dianteiro) (Superior) (Lado Esquerdo) (Manual) São divididos em 3 grupos: coxins do motor, coxins do câmbio e coxins do amortecedor. A função do coxim de motor/câmbio é ser o ponto de apoio do motor no chassi, fazendo a absorção da vibração do motor e evitando que seja transmitido para o veículo. O uso de coxins danificados diminuirá significativamente a vida útil do motor/câmbio do veículo.', 63.15, 63.15, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rbn7-lmsxpp60ps9lab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22697034188', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
