INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293836858', 'Pré Filtro Combustível Fiat Uno 2004 a 2006 - 1354441 - T040205', 'Pré Filtro Combustível Fiat Uno 2004 a 2006 1354441 T040205 Gasolina - sistema Bosch - filtro externoO pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 33.33, 33.33, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rd5u-m7bmtvn77zsfa8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22293836858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
