INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22397608516', 'Colchão Queen Size Gazin Sleep Confort com Molas Pocket 158x198x32cm', 'Colchão Casal Gazin Sleep Confort Mola Pock 158x198 cm 610158/92806 ATENÇÃO: BASE NÃO INCLUSA. Características: Tecido Antiderrapante Tecido 100% poliéster, com detalhes emborrachados. Evita que o colchão deslize sobre a base, trazendo maior segurança e conforto para o sono. Malha, Esses tecidos são produzidos em máquinas circulares e possuem características próprias. Como é um tecido mais poroso, permite melhor ventilação, proporcionando maior conforto térmico e toque extremamente macio.Molas Ensacadas, não possuem atrito entre si, oferecendo ausência completa de ruídos. Além disso, agem em conjunto com a espuma e garantem maior firmeza e conforto ao colchão. Como são independentes , a pressão é localizada, ou seja, cada mola se comprime individualmente de acordo com a pressão exercida pelo corpo. Essa característica torna o molejo excelente, principalmente para colchões de casal pois o movimento de uma pessoa não interfere no conforto da outra Especificações técnicas: Suporte de Peso: 100 Kg Pillow/Euro: Pillow Top Revestimento Superior: Revestimento Lateral: Suede Revestimento Inferior: Tecido Antiderrapante Molejo: Molas Ensacadas Dimensões: Altura: 32 cm Largura: 198 cm Profundidade: 158 cm Peso: 37,54 Kg Garantia do fornecedor de 12 meses. Imagem ilustrativa, estampa pode variar conforme o estoque.', 1729.9, 1729.9, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/br-11134207-820mf-mphzmh5j7f9d48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F22397608516', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
