INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593584699', 'Burrinho de Freio FUSCA 1967/1976 - 25817 - CCR9221', 'Burrinho de Freio FUSCA 1967/1976 TRASEIRO ESQ/DIR MOTOR 1300/1300L (11/16" OU 17,46mm) O Conjunto de Cilindro de Roda é utilizado em veículos cujo sistema de freios é a tambor. Ele aciona os freios na roda quando recebe pressão hidráulica enviada pelo cilindro mestre, assim, as sapatas são empurradas dando o atrito no tambor de freio, fazendo com que a roda freie e pare o veículo.', 46.65, 46.65, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/sg-11134201-7rbmi-lmxcjagamlvvfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22593584699', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
