INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192604385', 'Capa Protetora Correia Dentada Punto 1.4 8v 2008 Superior - 63039 - 106131', 'CAPA PROTETORA CORREIA DENTADA PUNTO 1.4 8V 2008 SUPERIOR O próprio nome diz: “Proteção” ou Capa da Correia Dentada. A Proteção e ou Tampa da correia dentada é tão importante quanto a correia e o tensionador, pois é um componente de segurança, por este motivo é indicada a sua substituição, em caso de qualquer avaria.', 48.65, 48.65, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rblw-lnkdqm6zsh6tae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22192604385', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
