INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23095629120', 'Canal Úmido Organizador Calha De Cozinha em Aço Inox 304 C/5 Módulos 90x18 - Tubrax', 'Canal Organizador de cozinha Tubrax - UAC0001-N O Canal Organizador Tubrax com 5 módulos é ideal para quem procura soluções para cozinhas/área gourmet funcionais com um toque de inovação e sofisticação. Produzido em aço inox de alta qualidade, com chapa de 0,8 milímetros de espessura e acabamento acetinado escovado linear, este produto transmite elegância e luxo ao seu ambiente. Acompanham os módulos projetados para perfeita mobilidade (posicione conforme preferir) que possuem encaixe perfeito, auxiliando o processo de lavação e enxague de louças, copos, talheres e utensílios de cozinha. São eles: - 02 módulos para pratos (tamanho grande e pequeno, com capacidade de 6 pratos cada); - 01 módulo para copos; - 01 módulo com 4 divisórias para disposição de talheres; - 01 módulo para esponja e detergente. Obs: Leves alterações na coloração e acabamento podem acontecer entre diferentes lotes do produto. ESPECIFICAÇÕES TÉCNICAS: - Marca: Tubrax - Referência do Modelo: UAC0001 - Acabamento: Acetinado escovado linear - Material: Aço Inoxidável 304 - Comprimento: 90 cm - Largura: 18,4 cm - Profundidade: 12 cm - Furo para válvula de 3 1/2" (não incluso) - Peso bruto (com embalagem): 4,9 Kg - Garantia: 3 meses contra qualquer defeito de fabricação.', 545.9, 331.9, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-7qvfl-lffstac71giqd0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F497552438%2F23095629120', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
