INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17122890473', 'FIDGET SPINNER - HOT WHEELS SORTIDO', 'FIDGET SPINNER - HOT WHEELS A febre do momento! O fidget spinner é um brinquedo que auxilia no alívio de estresse. É composto de um rolamento central e um desenho com 3 extremidades feitas em materiais como aço inoxidável, titânio, cobre e/ou plástico. O brinquedo tem sido anunciado como algo que ajuda as pessoas que têm dificuldade para se concentrar ou que são inquietas (tais como TDAH ou ansiedade), agindo como um mecanismo de liberação de energia nervosa ou estresse.', 48.99, 29.99, NULL, 'Hobbies & Collections > Toys & Games > Spinning Tops', 'https://cf.shopee.com.br/file/sg-11134201-7rd5l-lutf3n203khr97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689242394%2F17122890473', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
