INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997975194', 'Kit com 6 Vinagre de Maça Organico - Montes Verdes', 'KIT COM 6 UNIDADES E CADA UNIDADE TEM 530ML - GARRAFA DE PLÁSTICO O Vinagre de Frutas da Montes Verdes é um ingrediente puro e versátil, elaborado com fermentado acético de maçã orgânico. Com certificação de produto orgânico e 5% de acidez acética, ele é uma escolha natural para quem busca praticar o consumo consciente. Livre de corantes, conservantes e aditivos, seu sabor encorpado e nobre se destaca em diversas receitas. Além disso, ele é produzido sem álcool e glúten, mantendo suas propriedades preservadas. INGREDIENTES Fermentado acético de maçã orgânico e água. SUGESTÃO DE USO Diluir 1 colher de sopa (15 ml) de vinagre de maçã em um copo de água e consumir antes das principais refeições ou conforme orientação profissional. INFORMAÇÕES ADICIONAIS Este produto não é um medicamento. Armazenar em local fresco e ao abrigo da luz.', 185.0, 158.9, NULL, 'Food & Beverages > Beverages > Juice & Juice Vinegar', 'https://cf.shopee.com.br/file/sg-11134201-7rdyt-m1fyb18forwkb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1308390046%2F22997975194', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
