INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42520775029', 'Sandália Feminina Salto Bloco Fivela X Confortável 6220', 'Sandália feminina com salto bloco e tiras cruzadas, trazendo um design moderno e elegante. O detalhe em fivela dourada na parte frontal adiciona sofisticação ao visual, enquanto o fechamento no tornozelo garante mais segurança e conforto. Um modelo versátil que pode ser usado tanto em looks casuais quanto em produções mais sofisticadas. Principais características: • Salto bloco médio que proporciona estabilidade e conforto. • Tiras cruzadas com detalhe em fivela dourada, toque sofisticado. • Fechamento no tornozelo com fivela ajustável. • Palmilha macia para maior bem-estar. • Solado com boa aderência. • Versátil, combina com diferentes estilos de looks. • Altura do Salto; 5,5 cm •••• TABELA DE MEDIDAS •••• 34 ------------- 23,5 cm 35 ------------- 24,0 cm 36 ------------- 24,6 cm 37 ------------- 25,1 cm 38 ------------- 25,8 cm 39 ------------- 26,5 cm 40 ------------- 27,1 cm', 119.99, 69.99, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mezqo1j8qc5hdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F367507085%2F42520775029', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201093945', 'Cadeira Mormaii De Praia Alta Em Alumínio Lazy Sannet', 'Cadeira Mormaii Alta Lazy Aluminio Sanney PRODUTO ORIGINAL COM NOTA FISCAL Conforto e Estilo à Beira-Mar ou Onde Você Quiser! Aproveite seus momentos de descanso com a Cadeira de Praia Mormaii Alta Lazy Sannet Preta, perfeita para curtir o sol, relaxar no quintal ou levar em aventuras ao ar livre. Com o selo de qualidade Mormaii, ela une design moderno, conforto elevado e praticidade para transporte. Principais Benefícios: Modelo alto com encosto reclinável, ideal para relaxar com o máximo de apoio; Tecido Sannet: respirável, resistente à maresia e fácil de limpar; Estrutura leve e dobrável, perfeita para carregar para a praia, camping ou piscina; Acabamento em preto elegante, que combina estilo e discrição; Marca Mormaii – referência em esportes, lazer e vida outdoor. Seja na praia, no campo ou no jardim de casa, a Cadeira Lazy Alta Sannet oferece o conforto que você merece com a durabilidade que só a Mormaii proporciona.', 169.0, 117.9, NULL, 'Home & Living > Furniture > Benches, Chairs & Stools', 'https://cf.shopee.com.br/file/sg-11134201-8227f-mhjh3nm9idxd71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F312703265%2F58201093945', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
