INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8918567022', 'Nagaraku Ventilador De Mão Fácil Para Extensão De Cílios / Pressutor Rápido / Bloomação Com Flores / Volume Mega', 'Descrição do produto em inglês após português Informação do produto: Nome: Pregos de volume fáceis Camada: Duas camadas fã fácil cílios Material: Nm PBT Peso: 28,8g Espessura: 0,05 / 0,07 Curl: C e D Comprimento: Comprimento único 8 910 1112 13 1415 16mm comprimento mix: 8-15mm Aplicação: Artista de pestanas / salão de beleza Capacidade: 12 flechas Recursos: 1. Pisca-pisca muito fácil de pinch 2. Aplicação Rápida e economiza tempo 3. Não é necessário derramar para iniciantes 4. Uniforme e cor total, sem odor no pontas respingos 5. Comparado com cílios clássicos básicos, fáceis de quebrar sem quebrar com o picking enquanto estiver prolongado. 6. A base dos cílios é pro-bonita adequada, para que você possa mega o volume facilmente. 7. Material PBT desenvolvido especial tem qualidade premium: Macio, natural e confortável. Como tornar os fãs? 1. Escolha entre 3-5 ou 5-7 cílios individuais e coloque-o na fita dos cílios, use pinças para ajustar grandes ventiladores. 2. Pinch e wiggle o cílio para fãs diretamente, esta maneira é usada para fazer pequenos fãs pequenos e rápidos. **************************************************', 23.66, 16.33, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-m4e1l9zjcflj18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349433484%2F8918567022', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
