INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294330659', 'Tapete Bandeja Cronos 5 Peças Tpe Flexível 2018/2026', 'Tapete Tipo Bandeja para Fiat Cronos (2018 a 2024) – 5 Peças | Fabricado pela GRID Acessórios Este jogo de tapetes tipo bandeja é a escolha ideal para quem busca proteção completa, durabilidade e encaixe perfeito no Fiat Cronos. Produzido pela GRID Acessórios, marca nacional com mais de 20 anos de experiência no setor automotivo, o kit oferece alta qualidade e acabamento impecável. Compatível com: Fiat Cronos (modelos de 2018 a 2024) Marca: GRID Acessórios Material: TPE Flexível – resistente, ecológico e de fácil limpeza Cor: Preto Conteúdo da embalagem: • 2 tapetes dianteiros • 2 tapetes traseiros • 1 tapete para túnel central Diferenciais do produto: • Produzido em TPE flexível, resistente à água, lama e desgaste • Design tipo bandeja com bordas elevadas, que impede vazamentos e protege o carpete original • Encaixe sob medida, sem necessidade de adaptações • Fácil de limpar e com longa vida útil Produto fabricado pela GRID Acessórios, referência nacional em acessórios automotivos, com compromisso com a qualidade e sustentabilidade. Adquira agora e preserve o interior do seu Fiat Cronos com segurança e sofisticação!', 417.99, 339.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Mat', 'https://cf.shopee.com.br/file/br-11134207-820m0-mqi1cpu8fpqbf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1101226660%2F23294330659', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
