INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '56851125859', 'Cumbuca Uno Preta 100ml Coza', 'Cumbuca Uno 100 mL Preta Coza – Elegância em Cada Detalhe da Sua Mesa Com visual minimalista e acabamento brilhoso, a Cumbuca Uno 100 mL da Coza, na cor preta, é ideal para quem valoriza sofisticação até nas menores porções. Seu design compacto e funcional é perfeito para servir molhos, entradas, sobremesas e petiscos com estilo, seja em casa ou em ambientes profissionais. Destaques que fazem a diferença: Design clássico e sofisticado: o acabamento brilhoso e a cor preta oferecem um visual neutro e elegante que combina com qualquer estilo de mesa. Pequena, mas versátil: ideal para molhos, patês, entradas e porções individuais – perfeita para compor serviços completos com equilíbrio e bom gosto. Segura e resistente: fabricada em Polipropileno (PP) livre de BPA, proporciona segurança alimentar e durabilidade no uso diário. Fácil de usar e limpar: pode ser levada ao micro-ondas e à lava-louças, garantindo mais praticidade no dia a dia. Sustentabilidade em foco: feita com material 100% reciclável, reforçando o compromisso da Coza com o meio ambiente. Características técnicas: Capacidade: 100 mL Dimensões: 11,8 cm (comprimento) x 9,2 cm (largura) x 2,6 cm (altura) Cor: Preta Material: Polipropileno (PP) livre de BPA Acabamento: Brilho Indicação de uso: molhos, entradas, petiscos, pastas e pequenas porções Pode ser usada no micro-ondas e na máquina lava-louças Produto fabricado no Brasil A Cumbuca Uno 100 mL Preta Coza é a peça ideal para completar sua mesa com elegância, praticidade e um design que valoriza cada detalhe do servir.', 4.9, 3.68, NULL, 'Home & Living > Dinnerware > Bowls', 'https://cf.shopee.com.br/file/sg-11134201-821g3-mgw89ukusetode', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F56851125859', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
