INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21858135011', 'Banheira para Bebe Galzerano Premium Plastica Sand Bege', 'Banheira Galzerano Plástica Premium A Banheira Galzerano Premium é perfeita para a hora do banho! Com ela, você vai proporcionar ao seu bebê banhos com a qualidade, o conforto, a praticidade e a segurança que ele(a) merece! Compacta quando fechada, a Banheira Premium não vai ocupar todo o espaço da sua casa, sendo muito prática de abrir e fechar! A Banheira Galzerano Premium está disponível nas cores Grafite, Rosa, Panda e Real. Garanta já a sua! - Produto Nacional; - Design Moderno; - Estrutura em Aço; - Banheira desmontável; - Pés dobráveis facilitando o transporte e armazenamento – mais compacto; - Capacidade máxima da banheira (Bebê + Água) = 20 kg; Banheira 2 em 1 – o tanque pode ser utilizado no suporte ou fora; - Banheira com porta shampoo e sabonete; - Mangueira para saída de água do tanque e fixação segura (presilha metálica) ; - Válvula para impedir a saída de água quando o tanque for utilizado fora do suporte; - Banheira com gancho para armazenamento; - Trocador almofadado com maior proteção lateral; - Fácil limpeza; - Porta objetos amplo e com divisória; - Porta objetos com capacidade de 3 kg; - Banheira com trava de fechamento do suporte; Redutor da banheira; Composição têxtil 100% PVC. Medidas Altura 96cm x Largura 82cm x Comprimento 54,5cm Peso: 7,5kg', 699.0, 699.0, NULL, 'Mom & Baby > Bath & Body Care > Bathing Tubs & Seats', 'https://cf.shopee.com.br/file/sg-11134201-23010-as8jrrkpydmv48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F364932311%2F21858135011', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797553936', 'Livro Mulheres que Destravam Destinos | Fabiane Bastos', 'Mulheres que Destravam Destinos | Fabiane Bastos Mulheres que destravam destinos têm como propósito encorajar mulheres a alinharem seus corações aos anseios do coração de Deus, despertando-as para viverem suas verdadeiras identidades e propósitos nesta Terra. Neste envolvente livro, explore histórias bíblicas inspiradoras de diversas mulheres que destravaram destinos, você descobrirá chaves poderosas para acessar o seu destino profético, tornando-se uma agente do Céu para abençoar a sua geração. Prepare-se para viver plenamente o extraordinário enredo da sua vida e trilhar o caminho que o Autor da criação reservou especialmente para você! Altura: 21 cm Largura: 14 cm Profundidade: 1 cm Páginas: 176 páginas', 44.28, 44.28, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd6f-lvyw3j1f5ls371', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F22797553936', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
