INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492036115', 'Kit Máscara Facial de Sérum com Retinol (2 Produtos)', 'Máscara Facial com Retinol para Todos Os Tipos de Pele, Tem Ativos Que Estimulam a Produção de Colágeno e Melhoram a Elasticidade e Firmeza Cutâneas. Além Disso, Ajuda a Suavizar a Aparência de Rugas e Linhas de Expressão. Produto Que Oferece Firmeza para a Sua Pele, a Máscara Facial Firmadora com Retinol Océane Tem Ativos Que Oferecem Diversos Benefícios para a Sua Pele, Confira Quais São: A Máscara Facial com Retinol Ajuda a Hidratar a Sua Pele E, de Quebra, Dá Um Boost Na Firmeza. Sabe Como Funciona Uma Máscara Facial Firmadora? o Sérum Presente em Sua Composição Possui o Retinol, Derivado da Vitamina A, Que Estimula a Produção de Colágeno, Melhorando a Elasticidade e Firmeza da Pele. A Máscara Facial com Retinol Ajuda a Suavizar a Aparência de Rugas e Linhas de Expressão, Deixando a Pele Mais Lisa e Uniforme. Além Destes Benefícios, Está Máscara Firmadora Deixará Seu Rosto Luminoso e com Aparência Saudável. Retinol É Um Grande Aliado Na Redução de Rugas e Linhas de Expressão. Este Ativo Oferece Inúmeros Benefícios para a Sua Pele, Como: Renovação Celular e Melhora da Textura e Firmeza da Pele. O Kit Máscara Facial de Sérum com Retinol Contém: - 2 Máscara Facial com Retinol - Serum Face Mask 20ml', 69.9, 69.9, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134201-824gs-mpo5qme3r2fg10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F22492036115', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19799542860', 'Azeite de Oliva Extra Virgem Vidro 500ml Gallo', 'AZEITE DE OLIVA EXTRA VIRGEM VIDRO 500ML GALLO O Azeite de Oliva Extra Virgem Gallo, em garrafa de 500ml, oferece qualidade e sabor autêntico para enriquecer suas receitas. Com um perfil equilibrado de amargor e picância, apresenta notas frutadas que realçam o frescor dos alimentos. Ideal para saladas, massas, marinadas e finalização de pratos, seu uso agrega uma camada extra de sofisticação e saúde à mesa. Produzido com a tradição e expertise portuguesa, é uma escolha versátil e refinada para o dia a dia. A embalagem em vidro preserva melhor o sabor e a pureza do azeite, garantindo uma experiência única em cada uso. Marca: Gallo Vol: 500ml Tipo: Vidro Ideal para: Cozinhar e dar um toque adicional de sabor nas finalizações e preparos do dia a dia! Não contém Glúten *Imagens meramente ilustrativas Bem vindos a Maxx, tudo em um só lugar.', 79.0, 44.99, NULL, 'Food & Beverages > Cooking Essentials > Oil', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1hg6bev4q2wae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F447875552%2F19799542860', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
