INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20097795018', 'Sonhe Grande, Comece Pequeno e Cresça Rápido', 'Sonhe Grande, Comece Pequeno, Cresça Rápido é uma obra essencial para empreendedores que desejam transformar suas ambições em realidade. Escrito por João Rodrigues da Silva Neto, um empresário e mentor de renome que já treinou mais de 1 milhão de pessoas rumo ao sucesso, o livro oferece um guia prático e inspirador para quem busca alcançar resultados extraordinários no mundo dos negócios. Com base em sua vasta experiência e nos princípios que moldaram sua trajetória, João compartilha estratégias comprovadas que ajudarão você a sonhar grande, iniciar com os recursos disponíveis e crescer rapidamente no mercado competitivo. Através de histórias reais, insights poderosos e orientações práticas, ele mostra como é possível transformar ideias em empreendimentos prósperos, superar desafios e se destacar como líder. Este livro é uma leitura indispensável para quem deseja desenvolver uma mentalidade vencedora, construir uma base sólida para o sucesso e crescer de maneira acelerada, mas sustentável. "Sonhe Grande, Comece Pequeno, Cresça Rápido" é mais do que um livro de negócios; é um mapa para conquistar seus maiores sonhos e transformar sua vida e carreira, assim como a de milhões que já foram impactados por João Rodrigues da Silva Neto.', 59.9, 56.91, NULL, 'Books & Magazines > Books > Careers, Self Help & Personal Development', 'https://cf.shopee.com.br/file/sg-11134201-7rdwi-lz72u3y2h96201', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F482840775%2F20097795018', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253248354', 'Capa de Estepe Crossfox Personalizada com Cadeado', 'Capa de Estepe CrossFox Personalizada com Cadeado *************************ATENÇÃO************************* • Não Serve em pneus “MUD” / Off-Road Adaptados • Não serve em aros adaptados de perfil alto (Ex: Aro 17 ou 18 não originais) SISTEMA DE SEGURANÇA ANTI-FURTO • Cabo de aço Revestido: Abraça o pneu e a estrutura do suporte • Cadeado com chaves: Trava o sistema, impedindo a remoção da capa • Segurança Real: Superior as capas simples de elástico que saem com a mão COMPATIBILIDADE: • CrossFox 2005 a 2018 Medida de Pneu: • Compatível com o aro original 15” (Pneu 205/60 R15) ACABAMENTO: • Material: Courvin sintético (Textura similar ao original) • Detalhes: Costura reforçada e saída de água na parte de baixo • Ajuste: Fica bem esticada no pneu, sem sobras ESCOLHA A ESTAMPA DESEJADA NO MOMENTO DA COMPRA - Estampa com logotipo "CrossFox" na cor branca e fundo preto - Estampa com fundo camuflado cinza e logotipo "CrossFox" - Estampa com acabamento geométrico com logotipo "CrossFox" e a raposa no centro - Estampa com a Raposa CrossFox Vermelha com o fundo camuflado escuro - Edição "Selvagem" com o desenho frontal do carro e logotipo do "CrossFox" CONTEÚDO DA EMBALAGEM: • 01 Capa de estepe personalizada • 01 Cabo de aço reforçado • 01 cadeados + 02 chaves Não nos responsabilizamos pela má instalação ou mau uso do produto. Recomenda-se que a instalação seja feita por um profissional.', 111.92, 111.92, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Covers', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjg1h44naio6a8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1254320229%2F58253248354', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
