INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21697683858', 'Painel Decorativo Ripado PA72', 'Descrição: Desenvolvido com um design minimalista e funcional, o Painel Ripado Decorativo PA72 é ideal para compor ambientes. Opte por versatilidade. O PA72 100% MDF pode ser usado tanto como decoração para paredes, quanto para painel de TV. Esse produto já acompanha os suportes necessários para fixação na parede. Características: - Espessura: 04 - Pode Ser Montado Invertido?: Não - Possui Puxadores?: Não - Possui Prateleiras?: Não - Possui Espelho?: Não - Possui Portas?: Não - Possui Gavetas?: Não - Garantia (dias): 180 - Sistema de Montagem: Parafusos, cavilhas e Minifix. - Grau de Dificuldade da Montagem: Fácil - Como os Móveis Chegarão na Minha Casa: Desmontado em caixas, acompanhado de todas as peças, ferragens e manuais para montagem. - Indicação de Uso: Sala de Estar - Observação: Objetos decorativos que aparecem nas imagens, não acompanham o produto. - Recomendação de Manutenção: Para conservar a cor e os aspectos originais do produto, leve em consideração: Levantar a peça ao deslocá-la, o que ajuda a evitar danos à base e aos pés; Não utilizar água em abundância na peça, somente um pano levemente umedecido para a limpeza ou um espanador seco; Utilizar panos preferencialmente brancos, para evitar manchas e seque bem o móvel após a limpeza; Utilize somente água, nunca produtos químicos, abrasivos, solventes, ceras, sabonetes não neutros ou produtos de limpeza doméstica, visto que podem danificar o acabamento; Não coloque objetos quentes diretamente em cima do móvel para não causar bolhas, manchas ou outros danos, opte por utilizar um apoio; Se possível, não exponha sua peça diretamente ao sol, utilize cortinas ou persianas para bloquear os raios de luz, para que a pintura não desbote. Esses cuidados são muito simples e auxiliarão seu produto a permanecer em perfeito estado por muitos anos. - Revestimento /Acabamento: Pintura UV - Linha: Ripado - Material da Estrutura: MDF - Escala de brilho: Fosco - Tipo: Lojista e E-commerce - Necessita de Montagem: Sim - Espessura da Estrutura: 9 mm, 18 mm, 6 mm, 15 mm - Possui Pés?: Não - Possui Rodízios ?: Não', 356.99, 356.99, NULL, 'Home & Living > Decoration > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd3m-lvkggmobaax3ed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1226105437%2F21697683858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
