INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256415528', 'Oleo motor Mineral SAE Diesel 40 Gerador 1l- MOTORLUB', 'Óleo Motor Mineral SAE 40 Diesel 1L MOTORLUB oferece proteção superior para motores estacionários a diesel, garantindo alta performance e durabilidade. Desenvolvido especialmente para lubrificação mineral, este óleo proporciona resistência ao desgaste e ao calor, mantendo o motor sempre eficiente mesmo nas condições mais exigentes. Ideal para manter o funcionamento estável e prevenir falhas, ele é essencial para quem busca confiabilidade e economia em equipamentos industriais e agrícolas. SKU: 33300030 NUM: MLDIESEL40 Principais benefícios: - Lubrificação mineral específica para motores diesel estacionários - Alta resistência térmica e à oxidação - Proteção contra desgaste e corrosão - Aumenta a vida útil do motor - Embalagem prática de 1 litro para fácil reposição Confie em MOTORLUB para garantir o melhor desempenho do seu motor diesel com um óleo de qualidade comprovada.', 38.44, 38.44, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-82631-mlhw343q9g5d2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1386520276%2F58256415528', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
