INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997459789', 'CALÇA ASW IMAGE META', 'Projetado para atender do piloto iniciante ao mais experiente, o conjunto ASW IMAGE é sinônimo de OFF ROAD em terras brasileiras. Testado por pilotos dos mais diversos níveis técnicos durante quase 2 décadas, o IMAGE oferece recursos essenciais em termos de desempenho, qualidade e estilo, fazendo jus a posição de conjunto mais vendido na história da ASW Racing. Construída em Rip Stop com elastano, traz mais ergonomia e conforto, além dedurabilidade. Essa tecnologia dificulta que um rasgo se abra em caso de queda. A IMAGE tem inserções de fios elásticos emborrachados na parte interna da cintura que evita que a camisa saia da calça. Painéis ventilados com strech na parte traseira ampliam a região de flexibilidade para garantir mais agilidade do piloto. CARACTERÍSTICAS • Modelagem pré curvada relaxada, para você se sentir bem durante todo o dia de trilhas ou pista; • Tecido principal em poliéster 600 D sublimado, maior durabilidade da calça; • Fecho com catraca de 14 posições de regulagem, para ajuste preciso a cintura; • Região do joelho em poliéster resistente a abrasão de joelheiras, permite melhor movimento de pilotagem e isolamento do calor; • Painéis ventilados na parte traseira da perna; • Tecido stretch para melhor flexibilidade do joelho e amplitude de movimento.', 345.96, 224.88, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd54-lu8jkl3arde92f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1003133428%2F23997459789', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
