INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197124323', 'Kit 2 Sabonete Líquido Lux Botanicals Rosas Francesas 500ml', 'Sabonete Líquido Rosas Francesas Lux Botanicals Descubra o novo Sabonete Líquido Lux Botanicals Rosas Francesas, formulado especialmente para proporcionar uma experiência de limpeza luxuosa e eficaz. Com um delicado óleo botânico de beleza, este sabonete não apenas limpa, mas também hidrata suas mãos, mantendo-as macias e sedosas. Sua fórmula avançada elimina 99,9% das bactérias, garantindo proteção e limpeza a cada lavagem. O aroma envolvente das rosas francesas transforma um simples ato de higiene em um momento de bem-estar e prazer. Ideal para uso diário, o Lux Botanicals Rosas Francesas é a escolha perfeita para quem busca combinar a eficácia de um sabonete com a suavidade e o cuidado que a pele merece. Com 500 ml de puro carinho para suas mãos, transforme sua rotina de cuidados e sinta a diferença a cada uso!', 41.78, 41.78, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-8258h-mqmd6ravw83y4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F19197124323', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
