INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699128142', 'Robe Curto Luxo para Noiva em Microfibra Light com Detalhes em Renda', 'O Robe Curto Luxo MV Intimate é a escolha perfeita para noivas e mulheres que amam elegância, conforto e sofisticação. Produzido em microfibra light premium, seu tecido é leve, macio e possui caimento fluido que valoriza o corpo com delicadeza. Com acabamento refinado em renda nas mangas e nos ombros, o modelo traz um toque de romantismo e luxo, ideal para o dia da noiva, ensaios fotográficos, ou para momentos especiais em casa. O cinto ajustável permite modelar a cintura de forma elegante, garantindo conforto e um visual impecável. A peça é versátil, podendo ser usada sozinha como hobby ou combinada com uma camisola da mesma coleção, formando um conjunto sofisticado e inesquecível. Detalhes do Produto: Robe curto com detalhes em renda delicada nas mangas e ombros Tecido: Microfibra Light premium (macia, leve e respirável) Cinto ajustável na cintura Mangas amplas com acabamento rendado Ideal para noivas, madrinhas, gestantes e momentos especiais Modelagem elegante e confortável Produzido pela MV Intimate, sinônimo de qualidade e sofisticação Tamanhos disponíveis: P (36) | M (38/40) | G (42/44) | GG (46) Dica: Perfeito para o dia do casamento, ensaios de noiva ou para presentear com elegância. Combine com uma camisola da mesma linha para um look completo e ainda mais sofisticado. CORES: PRETO, ROSA E AZUL MARINHO', 99.9, 56.9, NULL, 'Women Clothes > Sleepwear & Pajamas > Kimonos & Robes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mgdzev892io555', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303874852%2F23699128142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
