INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20599090828', 'Emblema Vw Traseiro Gol 2000 a 2014 Saveiro 2006 A 2010 Cromado', '🚀 ENVIO IMEDIATO — PRODUTO EM ESTOQUE NO BRASIL! ⚡ Enviamos assim que o pagamento é confirmado. Produto em estoque para envio rápido. ⚙️ Emblema do porta-malas para Volkswagen Gol G3/G4 e Saveiro G4, indicado para reposição do logo traseiro desgastado, riscado ou desbotado. Ajuda a recuperar o acabamento traseiro e manter a identificação visual do veículo. 🚗 Compatível com: Volkswagen - Gol G3 / G4 2000 a 2014 Volkswagen - Saveiro G4 2006 a 2010 Não serve no modelo G5 ℹ️ Mais Informações: Cor: Cromado Material: Plástico ABS Aplicação: Porta-malas Fixação: Fita dupla face Ideal para reposição Produto novo, embalado e protegido 🏷️ Tags: #emblema #emblemaportamalas #emblematraseiro #emblemagol #emblemagolg3 #emblemagolg4 #emblemasaveiro #emblemasaveirog4 #logogol #logogolg3 #logogolg4 #logosaveiro #emblemavolkswagen #logovolkswagen #emblemacromado #acabamentotraseiro #volkswagengol #volkswagensaveiro #golg3 #golg4 #saveirog4 #gol2000 #gol2007 #gol2014 #saveiro2006 #saveiro2010 #pecasvw #reposicaovw', 41.46, 36.08, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-820lr-mr1muesftvk5b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F20599090828', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
