INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593053931', 'Chainsaw man vol. 5 - Panini', 'Aki está prestes a enfrentar o Demônio que era usado por Himeno. O que será que está se passando na mente desse jovem que anseia por vingança?! Enquanto isso, Denji enfrenta novamente o Samurai Sword!! Quem sairá vitorioso desta batalha sanguinolenta entre motosserra e katana?! O confronto pelo coração de Denji toma rumos inesperados!!', 42.48, 42.48, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rd4k-lvuamcvcr67ha9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F23593053931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
