INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21259926341', 'Conector Plug Para Bomba Alta Pressão Mini Cooper 1.6', 'Vantagens de comprar com a Puma Auto Parts: • Compra 100% segura • Compras efetuadas até as 12H são enviadas no mesmo dia. (Considerando dias úteis) • Produto de qualidade e com nota fiscal • Diversas formas de pagamento • Dúvidas no chat Chicote do Sensor de Pressão do Óleo • Terminal: 3.1mm • Número de Vias: 02 • Acompanha Treto Retrátil Aplicações: • Chicote do Sensor de Pressão do Óleo Mercedes Benz Ônibus 1722 • Sensor de Alta Pressão MINI Cooper 1.6 Importante: Garantia de 15 Dias Valor Unitário. Imagens Reais Do Produto.', 24.35, 24.35, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-8261k-mlmqsrbo8o3k4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F401365662%2F21259926341', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
