INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493931374', 'Comedouro Automatico Cachorro Gato Prático 3 litros - Alvorada Rosa', 'Comedouro Prático Alvorada Pet 3 Litros Mais praticidade e higiene para a alimentação do seu pet com o Comedouro Prático Alvorada Pet 3 Litros. Ideal para cães e gatos de todos os portes, ele possui capacidade generosa e estrutura resistente, garantindo refeições sempre organizadas e acessíveis para o seu animal de estimação. Seu sistema de alimentação por gravidade permite que o compartimento inferior esteja sempre abastecido com ração, oferecendo autonomia e conforto mesmo quando você estiver fora por algumas horas. Por que escolher o Comedouro Alvorada 3 Litros: - Capacidade de 3 Litros: Armazena uma boa quantidade de ração seca, reduzindo a frequência de reabastecimento - Sistema por Gravidade: Mantém o recipiente sempre cheio conforme o pet consome a ração - Base Estável e Antiderrapante: Mais segurança na hora da alimentação - Fácil de Higienizar: Peças removíveis que facilitam a limpeza do dia a dia - Transparente e Funcional: Permite visualizar facilmente o nível de ração disponível Especificações Técnicas: - Capacidade: 3 Litros - Cores: Azul, Rosa, Preto, Vermelho Dimensões Aproximadas: - Altura: 22,5 cm - Base: 27 cm Material: - Reservatório em plástico translúcido de alta resistência - Base em polipropileno atóxico e livre de BPA Com o Comedouro Prático Alvorada pet 3L, você garante uma rotina mais prática e saudável para seu pet, com alimentação contínua e organizada.', 29.9, 21.88, NULL, 'Pets > Pet Accessories > Bowls & Feeders', 'https://cf.shopee.com.br/file/br-11134201-820l8-mqxv15c0vz7r47', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F23493931374', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
