INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44212646703', 'Guidão Curvo De Alumínio 780mm Vega Laranja Neon', 'O Guidão Curvo Vega 780 mm foi desenvolvido para entregar controle, resistência e estilo marcante para ciclistas que buscam alta performance. Produzido em alumínio de alta qualidade, combina leveza e durabilidade, suportando as exigências de modalidades como MTB, enduro e trilhas técnicas. Sua largura de 780 mm proporciona excelente estabilidade e precisão nas manobras, enquanto a geometria com elevação de 25 a 30 mm, backsweep de 6° e upsweep de 3° garante postura ergonômica e conforto, reduzindo a fadiga em percursos longos. O acabamento em laranja neon com adesivos pretos oferece um visual vibrante e esportivo, resistente a riscos e à ação do tempo. Especificações técnicas: Material: Alumínio de alta resistência Comprimento: 780 mm Elevação: 25–30 mm (rise) Backsweep: 6° Upsweep: 3° Diâmetro da braçadeira: 31,8 mm Acabamento laranja neon com adesivos pretos Peso aproximado: 300–400 g', 52.99, 44.89, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdyc-mddhq6r1ttz400', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F990966849%2F44212646703', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599370266', 'Kit Pistão Anéis Biz 110i Pop 110i Std 025 050 075 100 Kmp', 'COMPRANDO NA PARANÁ AUTO CICLO VOCÊ TEM O MELHOR PREÇO E ENTREGA RÁPIDA —-SOMOS REVENDEDORES OFICIAIS —- TEXX – HJC – TXK – KMP – RIK – GP7—- >>> Enviamos sua encomenda em até 24h – Totalmente rastreável e 100% seguro <<< [PRODUTOS COM NOTA FISCAL e GARANTIA DE FÁBRICA.] KIT PISTAO C/ ANEIS KMP – BIZ 110I (2016/2024) – POP 110I (2016/2024) O Kit KMP é um produto reconhecido nacionalmente pela alta qualidade, pois possui os melhores itens do mercado duas rodas brasileiro. ATENÇÃO: ESCOLHER O TAMANHO DOS PISTÕES E ANÉIS EM VARIAÇÕES (STD – 0.25 – 0.50 – 0.75 – 1.00) COMPATÍVEL COM: BIZ 110I 2016 BIZ 110I 2017 BIZ 110I 2018 BIZ 110I 2019 BIZ 110I 2020 BIZ 110I 2021 BIZ 110I 2022 BIZ 110I 2023 BIZ 110I 2024 POP 110I 2016 POP 110I 2017 POP 110I 2018 POP 110I 2019 POP 110I 2020 POP 110I 2021 POP 110I 2022 POP 110I 2023 POP 110I 2024 Acompanha: 01 jogo de anéis – Marca KMP 01 unidade pistão, pino, e trava – Marca KMP Pino do tamanho original da moto. >—————< • Não nos responsabilizamos pelo mau uso do produto. • Recomendamos que a troca / instalação seja realizada por um profissional qualificado. • Antes de comprar verifique se seu e-mail, endereço e dados estão atualizados no Cadastro, assim manteremos contato com você durante o processo da compra e, evitando eventuais problemas com a entrega do produto. DUVIDAS CHAMA NO CHAT!!! Qualquer dúvida entrar em contato no campo de perguntas para evitar transtornos, temos uma equipe totalmente qualificada a disposição pronta para ajudar. Obrigado!', 105.9, 105.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mlc22jp3bta928', 'https://shope.ee/an_redir?origin_link=https%3A%2