INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250399427', 'SUS e Saúde Pública - Direto ao Ponto', 'Conheça o Produto DIFERENCIAIS: Conteúdo direto e preciso, sem rodeios ou informações supérfluas; Estrutura que favorece a fixação de conceitos e datas importantes; Permite aprendizado rápido e revisões eficientes; Prioriza conteúdos frequentemente cobrados em concursos e avaliações; A obra apresenta, de forma didática e estruturada, a evolução histórica das políticas de saúde no Brasil, desde o período colonial até os dias atuais, com ênfase na criação e na implementação do SUS. Distribuída em 25 capítulos que englobam as normas e os assuntos mais importantes para a sua preparação em concursos e nos programas de residências, SUS e Saúde Pública – Direto ao Ponto se destaca, especialmente, pelos seguintes aspectos: Abordagem ampla, elencando 25 assuntos essenciais para as provas; Linguagem acessível e didática, facilitando a compreensão de conceitos complexos relacionados à legislação e às políticas de saúde pública; Ideal para concursos, com destaque para datas, eventos e conceitos frequentemente cobrados em provas da área da saúde. O formato Direto ao Ponto torna a obra uma ferramenta ideal para revisões eficientes por trazer: Conteúdo condensado que elimina informações supérfluas, permitindo revisões rápidas dos principais conceitos; Organização cronológica dos eventos, facilitando a memorização de datas e marcos históricos importantes; Ênfase visual nos conceitos mais relevantes e frequentemente cobrados em avaliações; Conteúdo organizado em tópicos e subtópicos que facilitam a localização rápida de informações específicas. Sem dúvidas, você está diante de um material incrível e pensado para o que mais importa: ampliar o seu conhecimento e te deixar mais próximo(a) da aprovação em um concurso ou residência.', 79.9, 79.9, NULL, 'Books & Magazines > Books > Health, Fitness & Dieting', 'https://cf.shopee.com.br/file/sg-11134201-821el-mgqv22s63sax2f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F58250399427', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997683696', 'Livro Infantil Minhas Primeiras Histórias Disney A Pequena Sereia', 'O momento da leitura será o melhor instante do seu dia! Com a Coleção Minhas primeiras histórias, os personagens mais cativantes da literatura farão companhia a você ao longo de narrativas emocionantes e repleta de cores. Em A Pequena Sereia, Ariel e Príncipe Eric vão demonstrar o sentido da coragem. Ah, e tem muito mais na seção “Hora de Aprender”! A diversão é aqui, com a Bicho Esperto.', 13.9, 13.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/br-11134207-820lo-mpbbeeupt2pt91', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F626529639%2F18997683696', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12837113246', 'Óleo anticorrosivo "BICO INTELIGENTE" com 500 ml - FLEXTOP - WD-40', 'Produto: Óleo anticorrosivo com Bico Inteligente 500 ml - FLEXTOP Marca: WD-40 Descrição: O Óleo Anticorrosivo BICO INTELIGENTE com 500 ml FLEXTOP da renomada marca WD-40 é um produto que revoluciona a maneira de proteger e lubrificar equipamentos, combinando alto desempenho e facilidade de uso em uma embalagem inteligente e versátil. Com o exclusivo bico inteligente Flex Top, você adquire controle total sobre a aplicação. Escolha entre duas opções de uso: modo spray para uma cobertura ampla e uniforme ou modo jato com canudo extensor para alcançar os espaços mais apertados e desafiadores. Características: - Flexibilidade: Alterne entre spray ou jato para atender a diferentes necessidades de manutenção. - Alcance Ampliado: Com o canudo extensor, nenhum canto fica inacessível, garantindo proteção completa contra a corrosão. - Eficiência: Os 500 ml de óleo asseguram durabilidade prolongada de uso, seja em casa, no trabalho ou veículos. - Versatilidade: Ideal para uma grande variedade de aplicações, desde ferramentas domésticas até componentes automotivos. Especificações: Lubrifica, penetra, limpa, protege e elimina a umidade. Peso líquido: 500 ml. Peso: 0.37 Kg', 84.07, 75.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/sg-11134201-824j5-mf97zdnuqgi035', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F12837113246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19099311619', 'Flexus Limpador Condicionador Plasticos Painel Sio2 Vonixx Lancamento Vonix Limpador Limpa Plastico e Renova Restaurador Restaura Interno Externo', '1 - FLEXUS 500ML VONIXX 1 - PANO DE MICROFIBRA 40X40 PREMIUM JS --------------------------------------------------------------- - FLEXUS 500ML VONIXX DESCRIÇÃO: FLEXUS é um limpador e condicionador de plásticos internos 2 e 1 que limpa e protege ao mesmo tempo. O produto contém Sio2 em sua composição para melhorar a durabilidade e não deixar a superfície pegajosa. Promove acabamento seco ao toque, deixando a peça limpa, com acabamento original e protegida por até 3 meses; MODO DE USO: 1 - Pulverize uma pequena quantidade do produto nos plásticos. 2 - Espalhe com uma toalha de microfibra limpa e seca para limpar e promover acabamento em uma só etapa. 3 - Se necessário, repita a operação.', 46.9, 46.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lyqsm10ajwyd53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F319801107%2F19099311619', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
