INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44079275246', 'Mini Alicate Corte Diagonal Niquelado 5 Pol. 130mm 1 Peça SPARTA', 'O mini alicate de corte diagonal Sparta é uma ferramenta compacta e resistente, ideal para trabalhos precisos em eletrônica, hobby e manutenção. Com corpo niquelado e cabo em dupla injeção, oferece durabilidade e pegada confortável para cortes controlados em espaços reduzidos. Com 5 polegadas (130 mm), o alicate proporciona bom alcance e manuseio em aplicações que exigem precisão. Vendido em unidade, é indicado para profissionais e entusiastas que buscam um alicate leve e funcional para cortes em fios e componentes pequenos. Características: Modelo: 1782455 Referência: 1782455 Tipo: Alicate de corte diagonal Acabamento: Niquelado Cabo: Dupla injeção Tamanho: 5 pol. / 130 mm Unidade: 1 pc Marca: SPARTA Benefícios: Compacto e leve para melhor controle em trabalhos delicados Corte preciso em fios e componentes pequenos Cabo de dupla injeção oferece conforto e boa pegada Acabamento niquelado aumenta a durabilidade da ferramenta Ideal para eletrônica, hobby e tarefas de manutenção Conteúdo da embalagem: 1 mini alicate de corte diagonal SPARTA (5 pol. / 130 mm)', 35.25, 27.34, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-8261x-mls9mmmnsxky06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F44079275246', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202767617', 'Aparelho Barbear Gillette Mach3 Acqua Carga 2un Regular', 'Aparelho Barbear Gillette Mach3 Acqua Carga 2un Regular O Aparelho de Barbear Gillette Mach3 Acqua Grip é um produto desenvolvido para proporcionar um barbear rente e confortável. Indicado para uso no rosto, ele é ideal para quem busca praticidade e eficiência no cuidado diário. Com design ergonômico e tecnologia avançada, oferece uma experiência de barbear suave e segura. Benefícios Três lâminas afiadas e resistentes que garantem um barbear preciso. Cabeça flexível que se ajusta aos contornos do rosto para maior conforto. Molas independentes que distribuem a pressão, evitando irritações na pele. Fita lubrificante que facilita o deslizar da lâmina, ideal para uso no chuveiro. Cabo antiderrapante para melhor controle durante o uso. Resultados Com o uso do Aparelho Gillette Mach3 Acqua, você terá um barbear rente, confortável e sem irritações. A combinação das lâminas afiadas, cabeça flexível e molas independentes proporciona um acabamento suave, respeitando os contornos do rosto e garantindo uma pele protegida e bem cuidada. Modo de Usar Utilize o aparelho com gel, creme ou espuma de barbear para melhores resultados. Pode ser usado no chuveiro, aproveitando a umidade para um barbear mais confortável. Evite usar sobre pele irritada, ferida ou com cortes para prevenir desconfortos. Especificações Tipo de Produto: Aparelho de barbear Área de Aplicação: Rosto Indicação de Uso: Barbear Modo de Uso: Usar com gel, creme ou espuma de barbear; pode ser utilizado no chuveiro Contraindicações: Não utilizar sobre pele irritada, ferida ou com cortes', 34.9, 34.9, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-820o1-mnlvfccqss9180', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1648150131%2F58202767617', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58205849865', 'Copo Térmico Parede Dupla Buba Ursinho Azul', 'Copo Térmico Parede Dupla Buba Ursinho Azul O Copo Térmico Parede Dupla Ursinho Azul Buba é ideal para manter a temperatura das bebidas por mais tempo, garantindo praticidade e segurança para o dia a dia das crianças. Com design encantador e resistente, é perfeito para passeios, escola ou uso em casa. Características: - Capacidade de 320ml - Parede dupla que conserva a temperatura das bebidas - Tampa com vedação segura e canudo retrátil - Formato anatômico, fácil de segurar por mãos pequenas - Produzido em material livre de BPA e ftalatos - Estampa de ursinho na cor azul, com acabamento durável Indicações: Indicado para crianças em fase de transição, auxiliando no consumo independente de líquidos frios ou mornos. Modo de Uso: Preencha com a bebida desejada, feche bem a tampa e certifique-se de que o canudo esteja firme. Ideal para uso diário e em passeios. Cuidados: Lave com água e sabão neutro antes e após o uso. Não utilize em micro-ondas nem em lava louças. Evite líquidos muito quentes para preservar o material.', 86.9, 86.9, NULL, 'Mom & Baby > Feeding Essentials > Utensils', 'https://cf.shopee.com.br/file/sg-11134201-82608-ml6dffaxo3cwe9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F58205849865', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
