INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892838010', 'Capa para Piscina Retangular 3000 Litros 1405 MOR', 'A capa para piscina da marca Mor, modelo 1405, é um acessório indispensável para a manutenção e conservação da sua piscina. Ela é projetada para evitar que bichinhos indesejáveis, folhas e outras sujeiras entrem na água, mantendo-a limpa e pronta para uso. Além de proteger a piscina, a capa também ajuda a conservar a água por mais tempo, contribuindo para a preservação do meio ambiente ao reduzir a necessidade de trocas frequentes de água. Ela é feita de ráfia, um material conhecido pela sua resistência e durabilidade, garantindo que a capa possa resistir às condições climáticas adversas. Com um tamanho de 3,07m x 2,27m, esta capa é adequada para piscinas de tamanho médio. Apesar de seu tamanho, ela é surpreendentemente leve, pesando apenas 1,28 Kg, o que facilita a colocação e remoção da capa. Em resumo, a capa para piscina Mor é uma solução eficaz e durável para manter a sua piscina limpa e a água conservada, enquanto contribui para a sustentabilidade ambiental. Detalhes do produto Medidas: Largura: 2,27 m Comprimento: 3,07 m Material: Ráfia Peso: 1,28 kg Material Resistente Marca: Mor Referência: 1405 Garantia: 3 Meses * Imagens meramente ilustrativas.', 110.9, 99.9, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjhbnxucrawz96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F357239640%2F22892838010', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293890798', 'Creme de Pentear para Cachos Explosão de Coco 800g bn.Cachos', 'O Pentear Explosão de Coco 1Kg oferece um mix perfeito de hidro-nutrição com seus três ingredientes poderosos: a água de coco, que hidrata e remineraliza os fios; o leite de coco, que repara e protege; e o óleo de coco, que restaura, dá brilho e maciez. Para completar, ele ainda proporciona um efeito condicionante dando máxima emoliência, controle de frizz e brilho intenso._x000D_ _x000D_ -Ingredientes:_x000D_ ÁGUA PURIFICADA, ÁLCOOL CETOESTEARÍLICO, ÓLEO MINERAL, SORBITOL, VASELINA SÓLIDA, GLICEROL, MONOESTEARATO DE GLICERILA, ÓLEO DE COCO, METILSULFATO DE BEHENTRIMÔNIO, CLORETO DE CETRIMÔNIO, FENOXIETANOL, FRAGR NCIA (BUTILFENIL METILPROPIONAL, ALFA-ISOMETIL IONONA, SALICILATO DE BENZILA, CITRONELOL, CUMARINA, LIMONENO, GERANIOL, LINALOL), ÁLCOOL ETÍLICO, ÁLCOOL ISOPROPÍLICO, EDETATO DISSÓDICO DI-HIDRATADO, ETILHEXILGLICERINA, BUTIL-HIDROXITOLUENO, EXTRATO DE COCO, HIETELOSE, EXTRATO DE KAPPAPHYCUS ALVAREZII, ETRATO DE EUCHEUMA SPINOSUM, ACETATO DE SÓDIO, ÁCIDO CÍTRICO, ÓLEO DE RÍCINO HIDROGENADO ETOXILADO, CELULOSE MICROCRISTALINA, ÁLCOOL FENILETÍLICO, CAPRILIL GLICOL, SORBATO DE POTÁSSIO, BENZOATO DE SÓDIO, ÓLEO DE GIRASSOL, EXTRATO DA FOLHA DE ALECRIM.', 42.99, 41.99, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7reps-m80n6v5hyo0l44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F22293890798', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
