INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498891095', 'Kit 4 Desodorante Antitranspirante Aerosol Masculino Rexona Sem Perfume 72 horas 150ml', '• A exclusiva fórmula do Desodorante Aerosol Masculino Rexona Sem Perfume garante 72 horas de proteção contra o suor e o mau odor ativado pelo movimento • O Desodorante Sem Perfume Rexona o mantém seco, refrescado e protegido para que nada o detenha • Antitranspirante masculino fácil de usar: agite e aplique nas axilas a não menos de 15 cm da pele • Esse desodorante antitranspirante contém fórmula hipoalergênica dermatologicamente testada que não compete com o seu perfume • Esse desodorante antitranspirante não contém álcool* e não afeta a camada de ozônio, sua lata é de alumínio 100% reciclável, feito com energia elétrica 100% renovável • O Desodorante Aerosol Masculino Rexona Sem Perfume permite que você fique sempre protegido, não importa o que aconteça. Rexona não te abandona Mais uma vez Rexona se supera e relança sua linha de desodorantes com uma fórmula inovadora, o Desodorante Aerosol Masculino Rexona Sem Perfume possui um novo e exclusivo ativo antitranspirante. Esse desodorante antitranspirante o mantém protegido por até 72 horas, ativado pelo seu movimento e o deixa muito mais confiante para encarar qualquer desafio. Com o registro de 16 patentes e mais de 300 testes técnicos, está comprovado que essa nova tecnologia antitranspirante entrega um nível de proteção contra o suor como nenhuma outra proposta regular já entregou antes. A nova e exclusiva fórmula de Rexona Sem Perfume trabalha com um sistema de partículas menores e mais estáveis que formam uma barreira protetora mais resistente e duradoura contra a transpiração e o mau odor, mantendo você seco, refrescado e protegido a cada novo movimento e por muito mais tempo. Esse desodorante contém fórmula hipoalergênica testada dermatologicamente, que não compete com o seu perfume. A lata usada no desodorante é feita de alumínio 100% reciclável, e o produto é feito com energia elétrica 100% renovável, não contém álcool* e não afeta a camada de ozônio. Experimente também outros produtos da linha de desodorantes aerosol Rexona e se sinta sempre protegido durante qualquer atividade, porque Rexona não te abandona! *Não contém álcool etílico', 69.16, 69.16, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-823qb-mok33pz4m617ac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F893869193%2F23498891095', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
