INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698236500', 'KIT 50 ~ 300 GUARDANAPOS XADREZ VERDE BAND FESTA JUNINA (19,5X22,5 CM) (CHOCO)', 'TRAGA A VITALIDADE E O CLIMA FESTIVO DA ROÇA PARA SUA MESA JUNINA COM ESTE KIT DE GUARDANAPOS DESCARTÁVEIS COM ESTAMPA XADREZ VERDE BAND 💚. IDEAIS PARA LIMPAR AS MÃOS E A BOCA DURANTE A FESTIVIDADE 🔥, ALÉM DE COMPLEMENTAREM A DECORAÇÃO TÍPICA 🚩 COM UM TOQUE ALEGRE E TRADICIONAL. DISPONÍVEIS EM KITS DE 50 A 300 UNIDADES, CADA GUARDANAPO MEDE APROXIMADAMENTE 19,5 CM DE LARGURA POR 22,5 CM DE COMPRIMENTO. ESCOLHA A QUANTIDADE DESEJADA NA VARIAÇÃO DO ANÚNCIO. TAMANHO: APROXIMADAMENTE 19,5 CM DE LARGURA X 22,5 CM DE COMPRIMENTO (CADA GUARDANAPO) 📏. MATERIAL: PRODUZIDOS EM PAPEL DE SEDA DE FOLHA SIMPLES COM ESTAMPA XADREZ VERDE BAND 💚. VARIAÇÃO: ESCOLHA A QUANTIDADE DESEJADA (50, 100, 150, 200, 250 OU 300 UNIDADES) NA VARIAÇÃO DO ANÚNCIO. ATENÇÃO ❗: AS CORES PODEM VARIAR LIGEIRAMENTE DEPENDENDO DO LOTE E DA CALIBRAÇÃO DO SEU MONITOR 🖥️. CONFIRA O PRAZO DE ENVIO ANTES DE FINALIZAR A COMPRA 🚚. DEIXE SUA MESA JUNINA COMPLETA E CHEIA DE VIDA! ESCOLHA A QUANTIDADE DE GUARDANAPOS NA VARIAÇÃO E FAÇA SEU PEDIDO! ✨ Fontes e conteúdo relacionado', 10.85, 10.85, NULL, 'Home & Living > Home Care Supplies > Tissue & Paper Towels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m6wjrllacxtz80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23698236500', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
