INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18397111929', 'Furadeira de Impacto 1/2 Polegadas 800W 220V 60Hz 3000rpm 48000bpm - Deko', 'Loja do Mecânico - O que você precisa, nós temos! Furadeira de Impacto leve, versátil e com ótimo torque para aplicações profissionais ou semiprofissionais. Vem equipada com um Mandril metálico de 1/2" (13mm) de aperto rápido que ajusta facilmente a brocas ou bits. Uma ferramenta sempre pronta para o uso. Conta com controle de velocidade variável, além de seletor de rotação reversível e função Impacto. A máquina ideal para trabalhos em materiais mais duros seja ele alvenaria, metal ou madeira. Especificações Técnicas - Tensão: 220V - Frequência: 60Hz - Potência: 800W - Rotação: 0-3000 rpm - Batidas por Minuto: 0-48000 bpm - Mandril: 1/2" (13mm) - Capacidade de Perfuração: -- Concreto: 1/2" (13mm) -- Aço: 3/8" (10mm) -- Madeira: 25/32" (20mm) - Classe de Proteção: Isolamento Duplo - Peso: 2.3Kg - Dimensões: 24 x 8 x 29cm Conteúdo da Embalagem - 01 Furadeira de Impacto - 01 Empunhadeira Auxiliar - 01 Barra Limitadora de profundidade - 01 Chave de Mandril Importante - Garantia de 12 meses; - Enviamos em até 24 horas úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - A cor do produto pode variar de acordo com a tela do seu smartphone/computador; - Qualquer dúvida, utilize o campo "Perguntas e Respostas" e converse com o nosso SAC.', 265.99, 250.03, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qvec-ljbjonf1boy50e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F18397111929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213889680', 'Camiseta Fitness Feminina De Poliamida Modelo Nadador Básica Dlk', 'Performance, frescor e estilo com a regata nadador DLK Desenvolvida em tecido 100% poliamida, a camiseta básica garante respirabilidade, toque macio e secagem rápida. Seu design nadador nas costas e recortes estratégicos valorizam a silhueta e oferecem total conforto em treinos de força, mobilidade ou dias ativos ao ar livre. Diferenciais - Modelagem nadador com costas que ampliam a mobilidade - Tecido ultraleve com toque suave e alta respirabilidade - Secagem rápida que evita excesso de suor e mantém o frescor - Tecido 100% poliamida com durabilidade e conforto - Ideal para treinos de força, corrida, funcional ou uso casual esportivo Composição: 100% Poliamida Nível de compressão da peça: Não possui', 76.99, 76.99, NULL, 'Women Clothes > Tops > Shirts & Blouses', 'https://cf.shopee.com.br/file/sg-11134201-8259z-mqeslkke5gci0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F58213889680', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094684335', 'SHORT FITNESS FEMININO COM ELÁSTICO NA CINTURA OASIS DLK', 'Short Fitness Feminino Com Elástico na Cintura Oasis O Short Fitness Feminino Com Elástico na Cintura Oasis é a peça ideal para quem busca desempenho, conforto e proteção em seus treinos. Esse short tem um design moderno e é ideal para suas atividades físicas, garantindo conforto e estilo. Tecido de Alta Performance O Short Fitness é feito em tecido super macio. Ele é confortável e proporciona sensação agradável à pele, enquanto o elástico na cintura reforça a segurança, ideal para treinos intensos. A tecnologia de secagem rápida mantém você seca e confortável, permitindo que o suor evapore rapidamente durante suas atividades. Além disso, este short oferece proteção solar UV 50+, protegendo sua pele durante treinos ao ar livre. Design e Funcionalidade Com esse Short Fitness você tem o melhor em tecnologia de tecidos e design funcional. Seja na academia, corrida ou ioga ao ar livre, ele oferece a combinação perfeita entre estilo, proteção e conforto!', 106.99, 106.99, NULL, 'Women Clothes > Shorts > Shorts', 'https://cf.shopee.com.br/file/sg-11134201-821g3-mh0ix3f0i8lm8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1628803380%2F23094684335', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799604375', 'Vedacit Aditivo Para Reboco 3,6L Vedacit', 'VEDACIT VEDACIT é um aditivo impermeabilizante para concretos e argamassas, que age por hidrofugação do sistema capilar e permite a respiração dos materiais, mantendo os ambientes salubres. ÁREAS DE APLICAÇÃO Estruturas • Muro de Arrimo e Paredes de Encosta • Concreto • Alicerce, Baldrame e Sapatas Áreas Frias e de Serviços • Cozinha • Lavanderia • Banheiros Áreas Externas • Paredes Reservatórios • Muro de Arrimo e Paredes de Encosta • Concreto Piscinas • Enterrada Áreas Internas • Paredes MODO DE APLICAÇÃO Uso de poucas ferramentas e pouca dificuldade de aplicação Preparo e aplicação Você pode consultar mais detalhes abaixo de como preparar o produto para uso. Características Densidade: 1,05 g/cm³ Composição básica: Silicatos Rendimento: • Balde de 18 L: até 9 sacos de cimento (50kg) Preparação do Substrato As estruturas que serão impermeabilizadas com argamassa devem estar suficientemente dimensionadas e sem trincas. Já as superfícies a serem revestidas devem estar chapiscadas e limpas. "VEDACIT: Um aditivo indispensável para qualquer projeto de construção."', 99.9, 43.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-820lj-mpv6o21zsfeqc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F705932885%2F18799604375', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
