INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42354158437', 'Caderno Moleskine | Com Pauta | Capa Leão Colorido', 'Caderno Moleskine | Com Pauta | Capa Leão Colorido O Caderno Moleskine é mais do que apenas um caderno - é uma ferramenta essencial para fortalecer sua conexão espiritual. Com sua capa dura resistente e suas páginas de anotações espaçosas, este caderno é perfeito para registrar suas reflexões devocionais com Deus, anotações bíblicas e inspirações espirituais. Seja para fazer anotações durante os estudos bíblicos, registrar orações ou simplesmente para refletir sobre sua jornada espiritual, este caderno é uma companhia valiosa. Páginas:160Dimensões:Altura: 21 cm Largura: 14 cm Profundidade: 1 cm', 21.99, 21.99, NULL, 'Stationery > Notebooks & Papers > Notebooks & Notepads', 'https://cf.shopee.com.br/file/sg-11134201-7rau6-mavbrhrwulb6a5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F42354158437', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
