INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253116665', 'Amplificador De Guitarra Borne F60 15 Watts Cubo', 'O Borne F60 é o amplificador ideal para quem busca potência, praticidade e timbre profissional em um formato compacto. Com 15W RMS, alto-falante de 6” e o exclusivo Turbo Drive (distorção), ele entrega desde sons limpos e definidos até overdrives encorpados, perfeitos para rock, blues e pop. Seu painel com controles de Graves, Agudos e Volume Master permite moldar o som exatamente do jeito que você gosta, enquanto a saída para fones de ouvido possibilita estudar e tocar em silêncio, sem incomodar ninguém — ideal para apartamentos, estúdios e treinos noturnos. Leve, resistente e extremamente portátil, o F60 pesa apenas 3,5 kg e funciona em bivolt automático (100-240V), sendo perfeito para levar para ensaios, aulas e apresentações. Características: Modelo: F60 Linha: Guitarra Marca: Borne Potência: 15W RMS Efeito: Turbo Drive (distorção) Controles: Graves, Agudos e Volume Master Saída para fones de ouvido: Sim Alto-falante: 6 polegadas Peso: 3,5 kg Bivolt automático 100-240V Por que escolher o Borne F60? Timbre potente com 15W RMS Turbo Drive para distorção encorpada Equalização completa (graves, agudos e volume master) Saída para fones para estudar sem ruídos Compacto, leve e fácil de transportar Bivolt automático para uso em qualquer lugar O Borne F60 é a escolha perfeita para guitarristas que querem qualidade sonora, versatilidade e ótimo custo-benefício.', 859.9, 559.9, NULL, 'Audio > Amplifiers & Mixers', 'https://cf.shopee.com.br/file/sg-11134201-8262m-mje7hi70eadiaf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F780674849%2F58253116665', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52658574418', 'Mini Lanterna LED Foxlux Alumínio Portátil Luz Branca Potente Bolsa Carro Emergência', 'Lanterna De Alumínio Led Foxlux FX-ML15 A Lanterna de Alumínio LED Foxlux 44.05 foi desenvolvida para oferecer iluminação eficiente, resistência e praticidade em diversas situações do dia a dia. Fabricada em alumínio resistente, combina leveza e durabilidade, sendo ideal para uso doméstico, atividades noturnas e aplicações táticas. Seu LED de luz branca proporciona iluminação clara e uniforme, garantindo excelente visibilidade em ambientes com pouca ou nenhuma luz. Compacta e fácil de transportar, funciona com 2 pilhas AA (não inclusas), oferecendo praticidade e autonomia para emergências, pescarias, caminhadas e uso geral. Uma lanterna confiável para quem busca eficiência e ótimo custo-benefício. Características: > Corpo em alumínio leve e resistente; > Iluminação LED branca potente; > Alimentação prática com pilhas AA; > Compacta e fácil de transportar; > Ideal para uso doméstico e atividades outdoor; > Baixo consumo de energia. Especificações: > Modelo: 44.05; > Tipo: Lanterna tática portátil; > Tipo de luz: LED; > Material: Alumínio; > Comprimento: 15 cm; > Diâmetro: 2,5 cm; > Peso: 200 g; > Alimentação: 2 pilhas AA; > Pilhas inclusas: Não; > Recarregável: Não; > Entrada USB: Não; > Resistente à poeira: Sim; > À prova d’água: Não; > Zoom: Não. - Marca: Foxlux - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 42.71, 30.76, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/sg-11134201-81zvk-mmw84lwxlog16d', 'https://shope.ee/an_redir?origin_link=https%3