INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22398790779', 'Lona Polietileno Verde 6mx4m Vonder', 'A lona de polietileno verde 6 m x 4 m da Vonder é uma solução prática, versátil e resistente para coberturas temporárias em diferentes segmentos, como agricultura, construção civil, camping e utilidades domésticas. Impermeável e com proteção UV, oferece excelente desempenho na proteção contra chuva, poeira e incidência solar leve, sendo indicada para usos temporários em áreas externas e internas. Fabricada com cantos reforçados e fio sintético na bainha, garante maior durabilidade e resistência no uso diário. Com ilhoses espaçados a cada 1 metro, facilita a amarração com cordas elásticas, proporcionando melhor fixação e flexibilidade. Ideal para proteger materiais, solo ou estruturas de forma prática e eficiente. Características: Modelo: 6132064000 Referência: 6132064000 Massa aproximada (peso): 2,55 kg Cor da lona: Verde Espessura aproximada da lona de polietileno: 150 micra Distância entre ilhoses da lona: A cada 1 metro Medida da lona: 6 m x 4 m Benefícios: Cantos reforçados e bainha com fio sintético para maior resistência Impermeável e com aditivo UV para maior durabilidade Ilhoses a cada 1 metro facilitam a amarração segura Fabricada em polietileno de alta e baixa densidade Versátil para múltiplas aplicações temporárias Conteúdo da embalagem: 1 Lona de polietileno.', 147.94, 111.56, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-md1w0k04zgti5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22398790779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
