INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898670789', 'Teclado para Notebook Lenovo Yoga 520-14IKB 80YM', 'Teclado compatível com Lenovo Yoga 520-14IKB 80YM O teclado compatível com Lenovo Yoga 520-14IKB 80YM foi aprovado em rigorosos testes de qualidade e atende todas as exigências do seu equipamento, apresenta encaixe perfeito com o notebook, possui a mesma fixação da peça original. Além de 12 meses de garantia contra defeitos de fabricação. Atenção! Esse é um teclado bringIT, portanto não é um produto original da fabricante Lenovo. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Marca: bringIT Modelo: 520-14IKB 80YM Moldura: Sem Moldura Idioma/Layout: ABNT2 Backlight: Sem Iluminação Pointing Stick: Sem Pointingstick Cor: Preto Referência: TC955-ML-0001 Atenção: Para que esse teclado seja compatível com seu notebook, deverá ter as mesmas especificações de encaixe, layout e moldura. Esse produto é compatível com os notebooks: 520-14IKB, 330S-14IKB, 330-14AST, SN20M61595, 330S-14AST, 330 81FES00100, 9Z.NDSBN.A1B, 330E-14AST Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 83.7, 38.95, NULL, 'Computers & Accessories > Desktop Computers > Others', 'https://cf.shopee.com.br/file/sg-11134201-825ar-mqthfzpq56v780', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F23898670789', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22724053815', 'Batedor Manual Fouet Brinox Top Pratic 30,5 cm Aço Inox', 'Seu toque especial nas preparações dignas de masterchef com o Batedor manual fio Brinox 30,5 cm em aço inox. Integrante da Linha Top Pratic é perfeito para preparos delicados que precisam de ingredientes aerados. O Batedor Manual Brinox mede 5,5cm x 8,6cm x 33,4 cm e tem o tamanho ideal para os cozinheiros amadores e profissionais. Além de ser perfeito para o dia a dia é indicado para uso em gastronomia profissional. Para manter seus produtos de aço inox sempre brilhando, lave-os com esponja macia e sabão ou detergente neutro. Produtos abrasivos como palha de aço e outros, poderão riscar ou prejudicar o brilho. E sempre seque o seu produto após lavar. Conheça também os demais produtos das marcas Brinox, Coza e Haus Concept para deixar a sua casa ainda mais bonita com soluções completas de organização. O Grupo Brinox é um dos maiores fabricantes de utilidades domésticas do Brasil. Com fábricas nas cidades de Caxias do Sul (RS) e Linhares (ES) e importar produtos exclusivos e diferenciados, o Grupo Brinox atua em mais de vinte países. Através de suas marcas, Brinox, Coza e Haus Concept, oferece um mix de mais de 6 mil itens.', 27.99, 22.4, NULL, 'Home & Living > Kitchenware > Whisks & Beaters', 'https://cf.shopee.com.br/file/sg-11134201-23020-tj6kotrv7hnvee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842996464%2F22724053815', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898925910', 'Jogo De Facas De Precisão Com 29 Peças Vonder', 'O jogo de facas de precisão com 29 peças Vonder é indicado para trabalhos artesanais e de detalhamento, oferecendo praticidade e versatilidade em diferentes aplicações. É ideal para cortes delicados em papel, plástico, couro, madeira e outros materiais que exigem acabamento fino. Com estojo reforçado, o kit acompanha cabo de alumínio com pegador emborrachado que garante maior conforto no uso, além de pedra para afiar, pinça e 6 diferentes tipos de lâminas. As lâminas de reposição permitem maior aproveitamento e atendem a diversas necessidades, tornando o conjunto completo e funcional. Características: Modelo: 3599029000 Referência: 3599029000 Quantidade de peças: 29 peças Massa aproximada: 0,236 kg Benefícios: Versatilidade com 6 tipos de lâminas para diferentes aplicações Cabo de alumínio com pegador emborrachado para mais conforto Estojo reforçado que organiza e protege as peças Pedra para afiar que prolonga a vida útil das lâminas Ideal para cortes precisos em trabalhos artesanais Conteúdo da embalagem: 1 Jogo de facas de precisão, composto por: 1 estojo, 1 cabo, 1 pedra para afiar, 1 pinça e 26 lâminas, sendo: 6 lâminas Nº 1, 4 lâminas Nº 3, 4 lâminas Nº 4, 2 lâminas Nº 10, 6 lâminas Nº 11 e 4 lâminas Nº 12.', 109.74, 85.29, NULL, 'Home & Living > Kitchenware > Knives & Kitchen Scissors', 'https://cf.shopee.com.br/file/sg-11134201-824ii-mezsmf1uxsehba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F22898925910', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
