INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793845389', 'Lona de Polietileno Laranja 3m x 2m 100 Micras Vonder Leve', 'Indicada para agricultura, construção civil, náutica, camping, pesca, recreação, utilidades domésticas, entre outros. Não utilizar a lona diretamente sobre superfícies aquecidas ou expostas ao sol (exemplos: veículos, peças metálicas, máquinas e equipamentos), pois a ação do calor poderá provocar manchas e danos às superfícies. Não utilizar para cobertura de cargas transportadas em caminhões, caminhonetes e automóveis. Não utilizar em contato com produtos químicos e resinas e para cobertura de peças perfurantes/cortantes. O esforço excessivo e a ação de ventos fortes podem provocar o rompimento dos ilhoses, bem como da lona. Realize a amarração da lona com cordas elásticas, dando uma maior flexibilidade ao produto. Conservação: armazenar longe de fontes de calor. Caso necessário, lavar com água e sabão neutro. Não recomendado para utilização como cobertura definitiva em telhados. Possui fio sintético ao redor da bainha para maior resistência. Fabricada em polietileno de alta e baixa densidade, com aditivo que protege contra os raios ultravioleta. Impermeável. Possui amostra do produto fora da embalagem. Distância entre ilhoses da lona: A cada 1 metro Cor da lona: Laranja Espessura: 100 micras Peso Aproximado: 0,3 kg', 39.99, 32.38, NULL, 'Home & Living > Tools & Home Improvement > Shades, Awnings & Tarpaulins', 'https://cf.shopee.com.br/file/sg-11134201-7repy-m8xdpmzrw9tsc3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23793845389', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21399834400', 'Teclado para Notebook Dell Latitude E5510 E6400 E6410', 'Teclado compatível com Dell Latitude E5510 E6400 E6410 O teclado compatível com Dell Latitude E5510 E6400 E6410 foi aprovado em rigorosos testes de qualidade e atende todas as exigências do seu equipamento, apresenta encaixe perfeito com o notebook, possui a mesma fixação da peça original. Além de 12 meses de garantia contra defeitos de fabricação. Atenção! Esse é um teclado bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Marca: bringIT Modelo: E5510 E6400 E6410 Moldura: Não se aplica Idioma/Layout: Inglês Internacional - US Backlight: Sem Iluminação Pointing Stick: Sem Pointingstick Cor: Preto Referência: TC882-DE-0151 Atenção: Para que esse teclado seja compatível com seu notebook, deverá ter as mesmas especificações de encaixe, layout e moldura. Esse produto é compatível com os notebooks: E5510 E6400 E6410, E6410, E5410, E5400, E4300, E6400, E5510, E6500 Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 143.85, 143.85, NULL, 'Computers & Accessories > Desktop Computers > Others', 'https://cf.shopee.com.br/file/sg-11134201-8259t-mqs58cqkibr4c3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F21399834400', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12577434988', 'Ração Premier Ambientes Internos Dermacare para Cães Adultos de Pequeno Porte Sabor Salmão - 2,5Kg', 'PremieR Ambientes Internos Dermacare é um alimento para cães Super Premium, desenvolvido para oferecer um suporte especial para pele e a pelagem. Através da combinação de ácidos graxos essenciais (ômegas 6 e 3) e a vitamina biotina, PremieR Ambientes Internos Dermacare proporciona uma pele saudável e protegida. Além disso, por ser formulado com fontes de proteína selecionadas de altíssima qualidade (salmão e ovos) e por apresentar teores elevados do mineral zinco, promove aos cães uma pelagem mais exuberante e brilhante.', 149.0, 119.2, NULL, 'Pets > Pet Food > Dog Food', 'https://cf.shopee.com.br/file/95933a6970b69534eac8d4aa05f24c9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F438604073%2F12577434988', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20970932366', 'Sensor De Estacionamento Kx3 4 Pontos Display Preto', 'DESCRIÇÃO • Fácil instalação • Capsula com 18mm de diâmetro • Detecta obstaculos auxiliando o condutor nas manobras • O display fornece a distância em metros dos obstáculos detectados em tempo real em 180º graus • O sistema é ativado automaticamente quando a marcha ré é engrenada • Alerta sonoro pode ser desligado facilmente, interruptor liga / desliga • Sensor com PLUG CONECTOR • Adaptação universal em todos os carros importados e nacionais • Cores disponíveis: preto, prata, branco, fosco e emborrachado ESPECIFICAÇÕES • Detecção de distância 0,3m a 1,5m • Capsula com 18mm • Display de LED 7 segmentos', 104.0, 67.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Parking Cameras and Sensors', 'https://cf.shopee.com.br/file/br-11134201-23010-elpcw5q4b6lvf4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F411060907%2F20970932366', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
