INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14211812610', 'Maleta de Futebol Club 2 Seleções Coloridos Brasil X Espanha Gulliver - 1964', 'Futebol Club Seleções Brasil x Espanha (Jogadores Coloridos). Um jogo de clássico que, por muitos anos, vem estimulando o desenvolvimento do raciocínio lógico sem, claro, deixar de garantir muita diversão! Maleta de 2 Seleções Gulliver com 2 times. Possui 4 formatos de chuteiras para diferentes efeitos nos chutes Produto recomendado ou indicado para crianças acima de 3 anos. *Imagens Meramente Ilustrativas* Características: - Marca: Gulliver - Referência: 1964 Especificações técnicas: - Brasil X Espanha - 2 Times de 11 jogadores, cada - 2 Hastes para mover os goleiros - 2 Traves para montar - 2 bolas - Adesivos de numeros das camisas - 1 Campo de TNT (tecido) - Chuteira com ângulo à esquerda: Chutes com curva à esquerda e escanteios - Chuteira com ângulo à direita: Chutes com curva à direita e escanteios - Chuteira Arredondada: Chutes fortes e diretos ao gol - Chuteira Fina: Chutes por Cobertura Conteúdo da embalagem: - 1x Maleta de Futebol Club 2 Seleções Coloridos Brasil X Espanha Gulliver - 1964', 99.9, 94.91, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/3b542d04d954cd3ccfa819b2fdfa552c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F376053737%2F14211812610', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998754406', '30~150 ADESIVO JURASSIC WORLD RECOMEÇO REDONDO FESTCOLOR (CHOCO)', 'Transforme a decoração da sua festa com os Adesivos Redondos Jurassic World Recomeço! Este conjunto contém 30 adesivos vibrantes e detalhados, com personagens e cenas incríveis do universo Jurassic World. Com ilustrações realistas de dinossauros como T-Rex, Velociraptor, Pteranodon e outros gigantes pré-históricos, esses adesivos são perfeitos para personalizar convites, lembrancinhas, sacolinhas, cadernos ou qualquer outro item da sua festa temática. Fabricados em material autocolante de alta qualidade, cada adesivo mede aproximadamente 4 cm de diâmetro e traz o espírito jurássico para o seu evento com muito estilo e diversão. Marca: Festcolor Tema: Jurassic World Recomeço Conteúdo: Cartela com 30 adesivos redondos Dimensões aproximadas de cada adesivo: 4 cm Uso: Decoração, personalização de lembranças, papelaria e muito mais. Ideal para festas infantis, eventos escolares ou para fãs de dinossauros de todas as idades!', 17.85, 17.85, NULL, 'Stationery > Notebooks & Papers > Labels & Stickers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mct548dl8f0h69', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F23998754406', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
