INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894163328', 'Porta Esponja Bucha Bob Esponja Utilidade Pia Cozinha', 'Mantenha sua pia organizada e divertida com este suporte de esponja do Bob Esponja impresso em 3D! é resistente, durável e perfeito para segurar sua esponja de louça de forma prática e higiênica. Com um design criativo e colorido, inspirado no personagem icônico, é ideal para dar um toque especial à sua cozinha. Compatível com diversos tamanhos de esponja e fácil de limpar. Material: ✅ Fotos reais do produto ✅ PLA ✅ Design divertido e funcional ✅ Ideal para cozinhas organizadas ✅ Impressão 3D de alta qualidade 🚨⚠️Atenção! Para garantir que seu pedido chegue intacto, enviaremos os bracinhos soltos, pois durante o transporte eles podem se quebrar. A fixação é simples e pode ser feita facilmente. Caso tenha dúvidas, estamos à disposição para ajudar! 🛠 Cuidados com o Produto: 🔹 Evite exposição prolongada ao sol e altas temperaturas (acima de 60°C), pois o PLA pode deformar. 🔹 Limpeza com pano seco ou levemente úmido; não utilize álcool ou produtos abrasivos. 🔹 Manuseie com cuidado para evitar quedas bruscas. Garanta já o seu e traga mais diversão para sua rotina! 🧽✨', 29.99, 23.99, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/br-11134207-820lf-mqs2mi0k6qkjb0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318894435%2F22894163328', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793569165', 'Filtro de Combustível Citroen Ds4 2011 a 2016 Original Mahle Metal Leve', 'FILTRO DE COMBUSTIVE L MAHLE METAL LEVE KL583 APLICAÇÃO : CITROEN DS4 1.6 TODOS OS MODELOS DE 2011 A 2016 A função do filtro de combustíve l é reter as impurezas existentes no combustíve l acumulado no tanque do veículo, evitando que cheguem à bomba injetora, bicos injetores e unidades injetoras (veículos eletrônicos). A não substiuição no periodo correto pode provocar: - Aumento de consumo; - Perda de potência; - Dano na bomba de combustíve l, bicos, unidades injetoras e até causar parada total do veículo. PRODUTO NOVO ORIGINAL COM NOTA FISCAL , ENVIO RAPIDO !', 34.99, 28.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3kst44iaq7p97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318894435%2F23793569165', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257422991', 'Kit com 3 Shampoos Tonalizantes Color Change Loiro Escuro - Kiss New York', 'Dê tchau aos grisalhos em apenas 3 minutos usando Color Change Shampoo! Com fórmula de ação rápida, o shampoo tonalizante da Kiss NY garante 100% da cobertura dos grisalhos em um período de apenas 3 a 7 minutos. Além de uma fórmula vegana, não testada em animais e livre de amônia e parabenos, o produto ainda é rico em Ginseng, ativo que fortalece a raiz do cabelo e elimina as toxinas e também conta com Extratos Naturais que promovem o crescimento dos fios e ajudam a reter a cor do cabelo por mais tempo.É indicado para todos os tipos de cabelos, inclusive os quimicamente tratados e sua fórmula garante mínima transferência para toalhas e roupas.', 113.9, 113.9, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/sg-11134201-8262j-mm64thrbssucfb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1687531684%2F58257422991', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592941447', 'Kit Reparo Pneu Sem Camara Moto Carro', 'Kit Remendo para Pneu Moto/Carro/Bicicleta Utilizar em pneus sem câmara. - Não repare furos maior que 5 mm. - Não repare furo na lateral. - Armazenar em local fresco. - Manter fora do alcance das crianças. INSTRUÇÕES DE USO: 1° Remova o objeto que ocasionou o furo no pneu. 2° Utilize o escareador para preparar o LOCAL danificado antes de receber o reparo. 3° Coloque o reparo no aplicador e passe a cola. 4° Introduza o aplicador no furo do pneu. 5° Retire o aplicador e recorte a sobra do reparo e mantenha aproximadamente 5mm de sobra do reparo no pneu. CONTEÚDO EMBALAGEM: - 01 escareador 13 cm - 01 aplicador de reparo 13 cm - 01 tubo de cola. - 05 reparos (comprimento 10 cm).', 27.8, 24.15, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7wa6p6pbsvlfa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1188055013%2F22592941447', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42706103998', 'My Hero Academia - Boku no Hero - Vol. 6', 'O Festival de Esportes finalmente teve o seu desfecho e os alunos da U.A. Voltam à sua rotina. Ou, pelo menos, é o que se esperava – porque agora eles terão que encarar uma experimentação profissional, que é acompanhar o trabalho dos heróis profissionais em suas agências! Enquanto Bakugo e Todoroki recebem convites de agências do Japão inteiro, Deku pode acabar em um lugar inesperado…! Os protótipos de heróis não têm descanso! AUTOR: Kohei Horikoshi No. PÁGINAS: 200', 37.32, 37.32, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7ra0m-mbfl9a28uot826', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F42706103998', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
