INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202021859', 'Lápis preto com borracha Fini 2 unidades Leonora', 'Escrever ou desenhar com lápis não será mais a mesma coisa. Com o Lápis HB com Borracha na Ponta Fini - Blister com 2 Unidades Leo&Leo, os personagens mais fofos e doces do mundo serão a companhia perfeita para as tarefas do cotidiano, seja na escola ou mesmo no trabalho. O lápis tem corpo redondo e 4 estampas fofas e únicas. No topo a borracha é removível, possui 4 formatos diferentes e decorada com 4 estampas divertidas e exclusivas. O material é atóxico e resistente, sendo que o lápis é fácil de apontar, tem traço firme e escreve macio, e a borracha apaga superbem. Detalhes: - Lápis com corpo redondo; - Ponta resistente; - Corpo com 4 estampas exclusivas da Fini; - Borracha removível decorada com 4 formatos diferenciados e estampas exclusivas da licença; - São 2 lápis HB com borracha em cada blister, com 2 estampas diferentes em cada blister. *Produto sortido, será enviado de acordo com a disponibilidade do estoque.*', 24.24, 24.24, NULL, 'Stationery > Writing & Correction > Pencils', 'https://cf.shopee.com.br/file/sg-11134201-822wm-mibjldlnfh8md0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F58202021859', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
