INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21197673456', 'Gaveteiro 3 Gavetas para Pasta Suspensa ME4118 Branco', 'Esse armário arquivo é ideal para organizar seus documentos, pois possui três gavetas espaçosas para pasta suspensa, além disso, um nicho para acomodar objetos ao seu estilo. É totalmente fabricada no brasil e além de seu bonito visual é feita com madeira de reflorestamento, sendo 100% ecologicamente correta, o que confere a boa resistência e durabilidade à peça não agredindo o meio ambiente. Peso (kg): 32.4 Garantia: 03 Meses Altura (cm): 132.5 Acabamento: BP Melamínico Largura (cm): 52.2 Possui Gavetas: Sim Possui Rodízio: Não Profundidade (cm): 44.5 Tipo de Gaveteiro: De Chão Ambiente Principal: Escritório Material da Gaveta: MDP Material Principal: MDP Necessita Montagem: Sim Acabamento da Gaveta: BP Material do Gaveteiro: Madeira Complexidade da Montagem: Baixa: pode ser montado por uma pessoa sozinha Tipo de Corrediça da Gaveta: Metálica Simples Material do Puxador da Gaveta: Plástico Possui Gaveta para Pasta Suspensa: Sim Possui Acabamento na Parte de Trás: Sim Marca: Tecno Mobili Cor: Branco Quantidade de Gavetas: 03 Gavetas Quantidade do Produto: 1', 501.07, 501.07, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-82598-mr297lo1mdqa83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F21197673456', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
