INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257231849', 'Arandela Som Ambiente Bluetooth Teto Embutir Gesso 70W Rms Alexa Google Kit Completo', 'DANJASOM | Qualidade, confiança e envio rápido KIT COM 1 ARANDELA REDONDA ATIVA BLUETOOTH + 1 ARANDELA REDONDA BRANCA PASSIVA 70 RMS Compatível ALEXA e GOOGLE ASSISTENTE Lançamento da Le Son, a arandela Bluetooth é feita com materiais de qualidade e resistentes, garantindo completa satisfação a seus compradores. Conta com uma arandela ativa de 70W Rms e uma passiva, podendo ser instalada em forro de drywall, gesso, madeira, pvc, possui garras para fixação ajustáveis. A arandela ativa é ligada a energia por fonte bivolt e é controlada pelo Bluetooth. CARACTERÍSTICAS TÉCNICAS - Alto Falante: 6 polegadas - Tweeter coaxial com piezo duplo - Potência Nominal: 70W Rms - Faixa de Frequência: 100 - 20kHz - Impedância: 8 Ohms - Alto falante mid bass com borda de espuma - Dimensões: 6x19,5x19,5 cm - Cor: Branca CONTEÚDO DA EMBALAGEM - 1 Arandela Redonda Ativa - 1 Arandela Redonda Passiva - 1 Fonte de alimentação Bivolt - Kits de suportes de fixação - 1 Manual DANJASOM ¬ Distribuidor oficial das maiores marcas ¬ Todos os produtos com NOTA FISCAL ¬ Envio rápido e seguro ¬ Garantia direto do fabricante Em caso de dúvidas, utilize o chat e converse conosco — nossa equipe está pronta pra ajudar você a montar seu projeto com segurança e performance.', 351.76, 270.85, NULL, 'Audio > Home Audio & Speakers > Speakers', 'https://cf.shopee.com.br/file/br-11134207-820mb-mm0hx6j6g2ro64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F901722804%2F58257231849', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
