INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998506018', 'Bola Society Futebol Gramado Sintético Artificial Masculino Adulto Profissional Tamanho Oficial 5', 'CARACTERÍSTICAS: Tamanho: 5 Circunferência: 68–70 cm Peso: 410–450 g Gomos: 6 Material: Microcomposite Construção: Termocolada + Glue A Bola de Futebol Society Uhlsport Aerotrack é ideal para jogadores que buscam desempenho superior em partidas de society. Com tecnologia de termocolagem +Glue, oferece resistência e 0% de absorção de água, garantindo durabilidade mesmo em condições adversas. Seu design com 6 gomos e material microcomposite proporciona controle preciso e excelente resposta em campo. A câmara Airtec assegura equilíbrio e retenção de ar, enquanto o forro multiaxial reforça a estrutura da bola. BENEFÍCIOS: Controle e Precisão: Design com 6 gomos e material microcomposite para jogadas mais precisas. Durabilidade: Construção termocolada + Glue que impede a absorção de água. Estabilidade: Câmara Airtec e forro multiaxial que mantêm a forma e o desempenho da bola. DIFERENCIAIS TÉCNICOS: Tecnologia Aerotrack: Revestimento de alta frequência que melhora a trajetória da bola em até 30%, minimizando desvios inesperados. O QUE ESTÁ INCLUSO? 1 Bola de Futebol Society Uhlsport Aerotrack O pedido acompanha nota fiscal? Todo pedido efetuado segue acompanhado de nota fiscal emitida para o CPF/CNPJ informado na compra. Não efetuamos vendas sem emissão de nota fiscal. Precisa de ajuda? Utilize o campo de perguntas e esclareça suas dúvidas diretamente com um de nossos atendentes.', 247.15, 139.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/br-11134207-820l9-mn4op4qsy29u56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045256831%2F23998506018', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
