INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997626489', 'Kit de Microfones Profissional Sem Fio Onistek ON-MC821 Display Indicador', 'Este conjunto de microfones sem fio oferece alta qualidade de som, com captação de áudio nítida e precisa. Além de possuir tecnologia UHF que proporciona maior alcance e menos interferências. Com uma base receptora que garante estabilidade de sinal, conexão estável entre o microfone e o sistema de som e garante uma transmissão de áudio clara e sem interrupções. Características: • Kit com 2 microfones sem fio de alta qualidade • Ideal para shows, palestras, reuniões, karaokê, igreja, entre outras aplicações • Transmissão com duplo canal, sem interferências • Display digital na base receptora e nos microfones • Controle de volume para ambos os canais • Microfone projetado para uso de pilhas alcalinas AA • Longo alcance de funcionamento • Vida útil da bateria: cerca de 8 horas • Distancia máxima de transmissão de 50 metros Especificações: • Frequência de operação: 629,7 - 638,1MHz • Resposta de frequência de áudio: 45Hz - 16KHz(±3dB) • Número de canais: 50 • Intervalo do canal: 300KHz • Estabilidade de frequência: ±0,005% • Potência de saída: <10mW • Supressão de ruído: -50dB • Alimentação: 2 Pilhas AA Especificações do Receptor: • Número de canais: 2 • Estabilidade de frequência • Frequência de operação: 629,7 - 638,1MHz • Sensibilidade: -98dB • Deslocamento máximo: ±75KHz • Relação sinal ruído S/N: 2105dB (1KHz) • T.H.D: <0,5% • Soquete de saída: XLR Ø6,3 • Alimentação: 12Vdc / 500mA Itens Inclusos: -2 Microfones sem fio -1 Base Receptora -1 Cabo de áudio -2 Pares de pilha AA -1 Fonte de alimentação -1 Manual de instruções', 650.0, 497.35, NULL, 'Audio > Microphones', 'https://cf.shopee.com.br/file/sg-11134201-7rblj-m5lm62dkwz2854', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fs