INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253945508', 'Conjunto Curto Menino Marisol', 'O conjunto curto da Marisol é composto por uma camiseta em meia malha, que oferece conforto e maciez, e uma jardineira em moletom leve sem felpa, totalmente em estampa digital. A peça conta com bolso frontal funcional, adicionando um toque prático e estiloso ao look. Perfeito para os dias quentes, o conjunto une leveza, descontração e muito charme em um visual moderno e divertido.', 154.9, 77.45, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-8260c-ml87qjlcy5fk71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F980954412%2F58253945508', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23493901228', 'Wahl Kit Máquina de Corte Magic Clip Cordless Gold com Detailer Li Gold Ions', 'Combo Wahl Magic Clip Gold e Detailer Li Gold: Dê um toque de luxo ao seu arsenal de cuidados capilares com o Combo Wahl Magic Clip Gold e Detailer Li Gold. Este conjunto premium reúne duas das ferramentas mais confiáveis e potentes da Wahl, projetadas para oferecer resultados impecáveis em cada corte e estilo. Benefícios: Desempenho Profissional: Equipado com motores potentes e lâminas de precisão, o Combo Wahl Magic Clip Gold e Detailer Li Gold proporciona desempenho profissional em cada uso. Corte com precisão e eficiência, alcançando resultados de salão no conforto de sua casa. Versatilidade Superior: A Magic Clip Gold é conhecida por sua versatilidade, permitindo cortes de todos os estilos e comprimentos. Enquanto isso, o Detailer Li Gold oferece precisão máxima para acabamentos detalhados e designs complexos, permitindo que você dê vida à sua criatividade. Conveniência sem Fio: Ambos os dispositivos são sem fio, proporcionando total liberdade de movimento durante o uso. Com baterias de longa duração, você pode contar com horas de desempenho consistente sem interrupções. Design Ergonômico: Projetados com conforto em mente, o Combo Wahl Magic Clip Gold e Detailer Li Gold apresentam designs ergonômicos que se encaixam perfeitamente na mão, reduzindo a fadiga durante longas sessões de corte. Durabilidade e Estilo: Com acabamento em ouro, essas ferramentas não apenas entregam em termos de desempenho, mas também se destacam visualmente. Adicione um toque de estilo premium à sua estação de trabalho ou salão com esses elegantes dispositivos. Acessórios Inclusos: Para a Magic Clip Gold: pentes de altura (1/16" - 1"), óleo, escova de limpeza, protetor de lâmina vermelho, carregador. Para o Detailer Li Gold: pente de altura, escova de limpeza, óleo, protetor de lâmina vermelho, carregador. Tempo de Carregamento: O tempo de carregamento para ambas as ferramentas é de aproximadamente 60 minutos para uma carga completa.', 2999.99, 2229.0, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/sg-11134201-7rep1-m8os4kri1ne133', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F23493901228', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
