INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298711797', 'Neuro Treonato - Magnésio 60 Cápsulas - 1 Unidade', 'Neuro Treonato – Magnésio com L-Treonina Neuro Treonato é um suplemento alimentar em cápsulas que combina magnésio com L-treonina, ideal para quem busca manter uma rotina equilibrada com suporte nutricional para as funções neuromusculares e do metabolismo energético. ALEGACÕES PERMITIDAS: ✅ Magnésio “O magnésio auxilia no funcionamento neuromuscular.” “O magnésio contribui para o metabolismo energético.” “O magnésio auxilia no funcionamento do sistema nervoso.” “O magnésio auxilia no processo de divisão celular.” “O magnésio contribui para a formação de ossos e dentes.” “O magnésio auxilia no equilíbrio dos eletrólitos.” DESTAQUES DA FÓRMULA: Magnésio – mineral essencial com múltiplas funções no organismo L-Treonina – aminoácido presente em proteínas, amplamente utilizado por quem busca bem-estar na rotina Fórmula pensada para praticidade e rotina saudável COMO USAR: Uso oral: ingerir 2 cápsulas ao dia com 200 ml de água, preferencialmente após o almoço ou jantar, ou conforme recomendação de profissional de saúde. INGREDIENTES: Bisglicinato de magnésio, óxido de magnésio, L-treonina e antiumectante dióxido de silício. Ingredientes da cápsula: Gelatina. NÃO CONTÉM GLÚTEN. ESTE PRODUTO NÃO É UM MEDICAMENTO. MANTENHA FORA DO ALCANCE DE CRIANÇAS.', 49.9, 48.91, NULL, 'Health > Food Supplement > Weight Management', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbprzv5ja3ixa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1543591764%2F22298711797', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23197447012', 'Jogo Eu Vi! Spidey - Copag', 'Jogo Eu Vi! Spidey - CopagO Jogo Eu Vi! Spidey da Copag é a opção perfeita para entreter e estimular o raciocínio das crianças de forma lúdica e educativa. Com 55 cartas originais da Disney, o jogo promete diversão garantida para 2 a 4 jogadores. Neste divertido jogo você deve ser o primeiro a encontrar os personagens. Seja o mais rápido e junte todas as cartas. Idade recomendada: A partir de 4 anos. Selo Inmetro: CE-BRI/INNAC-00276-01A - NM300/2002 - OCP 0061. Diferenciais:Cartas originais da Disney para uma experiência única e envolvente. Estimula o raciocínio e a interação entre os jogadores. Desenvolvido pela Copag, garantindo qualidade e durabilidade. Mais sobre o Produto:Promove a diversão em família ou entre amigos. Estimula o aprendizado e o desenvolvimento do raciocínio lógico. Perfeito para presentear crianças que adoram os personagens Disney. Dicas de uso:Reúna a família ou os amigos para uma tarde de diversão com o Jogo Eu Vi! Spidey. Explore a criatividade das crianças ao brincarem com os personagens Disney. Utilize o jogo como uma ferramenta educativa para estimular o pensamento estratégico dos pequenos. Ficha Técnica:Nome do produto: Jogo Eu Vi! Spidey; Marca: Copag; Idade recomendada: A partir de 4 anos; Selo Inmetro: CE-BRI/INNAC-00276-01A - NM300/2002 - OCP 0061; Contém: 55 cartas.', 33.99, 33.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7rcee-ltv6eooyv9awa5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F23197447012', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19777225739', 'Jogo Pizzaria Maluca - Grow', 'Jogo Pizzaria Maluca - GrowO Jogo Pizzaria Maluca da Grow proporciona diversão garantida para toda a família. Os participantes se tornam verdadeiros pizzaiolos, cada um encarregado de preparar uma pizza diferente. Em cada pizza, estarão indicados os ingredientes necessários. Durante o jogo, podem ocorrer contratempos, como a chance de ganhar ou perder ingredientes. O objetivo é ser o primeiro a completar a sua pizza para vencer a partida. idade recomendada: A partir de 6 anos. Selo Inmetro: CE-BRI/ICEPEX-N 01024-25 - NM300-2004 - OCP. Diferenciais:Ideal para reunir amigos e familiares. Estimula o pensamento estratégico e a socialização. Mais sobre o Produto:O jogo é indicado para 2 a 6 participantes. Qualidade e segurança da marca com certificação Inmetro. Dicas de Uso:Reúna seus amigos e familiares para uma tarde de jogos animada com o Jogo Pizzaria Maluca - Grow. Divirtam-se preparando pizzas fictícias e desafiando uns aos outros para ver quem será o pizzaiolo mais ágil e estratégico! Ficha Técnica:Marca: Grow; Nome do produto: Jogo Pizzaria Maluca; Idade recomendada: A partir de 6 anos; Selo Inmetro: CE-BRI/ICEPEX-N 01024-25 - NM300-2004 - OCP; Contém: 1 tabuleiro, 30 ingredientes, 6 fatias de pizza, 11 cartas azar, 13 cartas de sorte, 1 peão, 1 dado, e manual de instruções.', 95.99, 95.99, NULL, 'Hobbies & Collections > Toys & Games > Dice, Board & Card Games', 'https://cf.shopee.com.br/file/sg-11134201-7qvep-lezs05fkiysv30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F19777225739', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
