INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693264314', 'Pasta sanfonada A4 com 12 divisórias Brigadeiro 6108.03 Dello', 'A Pasta Sanfonada A4 com 12 Divisórias da linha Aromas Dello é a escolha ideal para quem busca praticidade, organização e um toque de estilo na gestão de documentos, com o diferencial de um aroma agradável que enriquece o uso do produto. Detalhes: - Cor: Marrom - Dimensões: 330 x 230mm - Material: Polipropileno de alta qualidade, oferecendo resistência e durabilidade. - Capacidade: 12 divisórias expansíveis em formato sanfonado, permitindo a separação e organização eficiente de documentos. - Fechamento: Aba com elástico resistente, garantindo que os documentos fiquem seguros e bem organizados. - Aroma: Brigadeiro, com uma fragrância suave e agradável, que adiciona um toque único ao produto. Cuidados: - Evitar exposição prolongada à luz solar direta para preservar a cor e o aroma do produto. - Limpar com um pano seco ou levemente umedecido para manter a pasta em boas condições.', 53.88, 53.88, NULL, 'Stationery > School & Office Equipment > Folders, Paper Organizers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-lzt3azyns6y4e1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F22693264314', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15369454985', 'Reservatorio De Agua Palio Weekend Siena Strada', 'IDEAL AUTO PECAS - Desde 1992 - IDEAL PARA SEU CARRO! Reservatorio De Agua Do Radiador Com Tampa APLICACAO: PALIO FIRE DE 2001 A 2012 PALIO WEEKEND FIRE DE 2001 A 2012 SIENA FIRE DE 2001 A 2012 STRADA FIRE DE 2001 A 2012 IDEA FIRE DE 2001 A 2012 ATENCAO: ANTES DE COMPRAR VERIFICAR MODELO DO RESERVATORIO PELA FOTO ( 1 GUIA, PARA RESERVATORIO BEHR) DESCRICAO DO PRODUTO O reservatorio de agua do radiador armazena uma certa quantidade de agua, que deve ser sempre reposta, no interior do veiculo. E com o auxilio de outras pecas, realiza o resfriamento do motor quando necessario. QUALIDADE: 1a Linha com Padrao Original de Aplicacao e Durabilidade - 100% Novo GARANTIA: 03 Meses de Garantia NOTA FISCAL: SIM SUPORTE POS VENDA: SIM ENVIO: Enviaremos seu pedido no mesmo dia para pagamentos confirmados ate as 14H. POSSUIMOS LOJAS FISICAS TEM ALGUMA DUVIDA? USE O CAMPO DE PERGUNTAS, ESTAREMOS A DISPOSICAO PARA TE ATENDER!', 108.9, 108.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me5tts5w7zlua8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F15369454985', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
