INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54061478307', 'O Jesus Que As Mulheres Viram | Rebeca Mclaughlin', 'Livro O Jesus Que As Mulheres Viram Como as primeiras discípulas nos ajudam a conhecer e amar o Senhor. Os Evangelhos revelam a presença marcante de mulheres na vida de Jesus, o que é surpreendente considerando o contexto cultural e religioso da época. A autora Rebecca McLaughlin nos convida a refletir sobre o que as mulheres que seguiram Jesus diriam sobre Ele, considerando sua diversidade: de diferentes idades, origens e situações. Buscando cura, perdão e respostas, elas se aproximaram de Jesus, e suas histórias continuam a nos inspirar. Através dessa escrita sensível, somos levados a nos perguntar: e se fosse conosco? Quais seriam nossas razões para buscar Jesus hoje? Especificações do livro O Jesus Que As Mulheres Viram Título: O Jesus Que As Mulheres Viram Subtítulo: Como as primeiras discípulas nos ajudam a conhecer e amar o Senhor Autor(es): Rebeca McLaughlin Ano de Edição: 2023 Capa: Brochura Acabamento: Laminação Fosca Páginas: 176 Dimensões: Altura: 20,5 cm Largura: 13,5 cm Profundidade: 1,0 cm Peso: 0,195 kg ISBN: 9786559882083 Editora: Mundo Cristão', 48.58, 48.58, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-823r0-moxz24foetcbc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F54061478307', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398201746', 'Afinador Royal K&L Cromático Clip P/ Violão Cor Preto', 'Afinador Royal K&L Cromático Clip P/ Violão Cor Preto Produto compacto, leve, com afinação precisa e fácil de usar, o afinador Royal K&L Cromático Clip P/ Violão Cor Preto é ideal para afinar diversos instrumentos de cordas, como Guitarra, Violão, Contra Baixo, Cavaquinho, Ukulele, Violino entre outros. Afinação do Afinador em Do (C), podendo ser alterada para Fa (F), Sib (Bb) ou Mib (Eb). 6 Modos de Afinação: C (Cromático), G (Guitarra/Violão), Bass (Baixo), V (Violino), Uc (Ukulele C) e Ud (Ukulele D) e Bj (Banjo), e instrumentos com afinação em Fa (F), afinação Sib (BB), e afinação Mib (Eb). Especificações: Marca: Royal K&L Cor: Preto Conteúdo da Embalagem: 1 Afinador Cromático 1 Bateria 3V CR2032 1 Manual de Instruções', 31.7, 31.7, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Music Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7ratj-man17z5lneqq49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442397041%2F21398201746', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22135644859', 'Sabonete Protex Baby 85g', 'Sabonete Protex Baby 85g O sabonete em barra Protex Baby Proteção Delicada possui fórmula suave que limpa cuidadosamente para manter a barreira de proteção natural da pele do seu bebê, garantindo uma pele saudável e protegida. Sua fórmula livre de conservantes, álcool e parabenos, é hipoalergênica e testada por dermatologistas e pediatras. Proporciona proteção e limpeza para uma pele saudável e protegida Sua fórmula é suave e delicada pois não contém álcool, corantes e parabenos Não arde os olhos, para que a hora do banho seja um momento tranquilo. Protex Baby é testado por dermatologistas e pediatras, garantindo a segurança no uso do produto no seu bebê Hipoalergênica para garantir o conforto do seu bebê - Compre produtos Protex', 8.62, 8.62, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-22110-45x8h52pbgjve4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F22135644859', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
