INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207065074', 'KORRES LAVANDA DO MAR CREME HIDRATANTE CORPORAL 350ML', 'Creme hidratante corporal. Hidratação e proteção antirresecamento para uma pele macia e perfumada. O Creme Hidratante Corporal Korres Lavanda do Mar da Grécia reúne o melhor da hidratação e nutrição que sua pele precisa com a combinação de Óleo de Amêndoas Doce, Vitamina B5 e Aloe Vera, que nutrem e retêm a água necessária para uma pele com a elasticidade em dia. Korres Lavanda do Mar da Grécia traz o frescor do Mar Egeu com as notas revigorantes de Lavanda para completar o ritual de cuidado com um perfume duradouro e acolhedor. Korres Lavanda do Mar da Grécia leva 92,3% de ingredientes naturais em sua fórmula. Benefícios de Creme Corporal Korres: ▸ Creme hidratante corporal.▸ Hidrata e nutre intensamente.▸ Protege contra o ressecamento.▸ Deixa a pele macia e perfumada.▸ Contém Óleo de Amêndoas Doce, Vitamina B5 e Aloe Vera.▸ Mantém a elasticidade e a suavidade da pele.▸ Perfume duradouro de Lavanda do Mar da Grécia.▸ Frescor inspirado no Mar Egeu.▸ 92,3% de ingredientes naturais.▸ Textura leve e de rápida absorção. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 65.9, 65.9, NULL, 'Beauty > Bath & Body Care > Body Cream, Lotion & Butter', 'https://cf.shopee.com.br/file/sg-11134201-825zn-mlxlnxlzqccvfc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58207065074', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
