INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58207214638', 'Torneira Luna 4 Temperaturas Zagonel', 'Torneira Luna 4 Temperaturas Zagonel (127V/220V) A Torneira Luna 4 Temperaturas da Zagonel é ideal para quem busca praticidade e eficiência no dia a dia. Com design moderno, disponível nas cores branco e preto, oferece aquecimento rápido e controle de temperatura em 4 níveis. Perfeita para cozinhas e áreas de serviço. Vantagens: 4 níveis de temperatura Aquecimento rápido e eficiente Design moderno nas cores branco e preto Praticidade no uso diário Fácil instalação Dados técnicos: Marca: Zagonel Modelo: Luna 4 Temperaturas Cores: Branco / Preto Potência: 5500W Tensão: 127V ou 220V Tipo de controle: Multitemperaturas Quantidade de temperaturas: 4 Instalação: Parede', 318.9, 208.5, NULL, 'Home & Living > Tools & Home Improvement > Sinks & Water Taps', 'https://cf.shopee.com.br/file/br-11134207-820ma-mm0h8qcldc7b92', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F58207214638', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53112274130', 'A correspondência de Fradique Mendes | Clássicos Para Todos', 'Prepare-se para mergulhar em uma narrativa épica e repleta de mistérios com A correspondência de Fradique Mendes . Fradique, o poeta culto, excêntrico e viajado, é uma personagem intrigante criada por um grupo de intelectuais liderados pelo brilhante escritor do realismo português, Eça de Queirós. Neste livro cativante, somos transportados para uma era de grandes eventos históricos, onde a ilusão da existência de Fradique Mendes se entrelaça com figuras reais, como o renomado escritor Victor Hugo e os eventos marcantes da unificação da Itália. Parte de suas cartas pessoais é aqui revelada, adicionando ainda mais autenticidade a essa intrigante figura ficcional. Ao acompanhar as aventuras desse misterioso poeta, somos presenteados com uma perspectiva crítica afiada e perspicaz, tão característica de Eça de Queirós. As reflexões sobre a sociedade e os acontecimentos do final do século XIX ganham vida através dessa trama envolvente e repleta de reviravoltas. Você não vai querer perder a oportunidade de se envolver com essa obra-prima literária, que nos leva a questionar a linha tênue entre ficção e realidade, e nos presenteia com uma experiência literária rica e emocionante. Embarque nessa jornada intrigante e conheça o mundo através dos olhos e das palavras de Fradique Mendes, uma personagem única que ganha vida nas mãos geniais de Eça de Queirós. Adquira já sua cópia e desvende os mistérios desta empolgante correspondência ficcional! 18X11 CM 216 Páginas', 14.9, 12.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824h9-mpisu9j6xqte0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F53112274130', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
