INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193595183', 'Kit 6 Latas de Tinta Spray Uso Geral Cinza Primer 400ml Chesy', 'Tinta Spray Uso Geral 400ml Chesy Secagem Rápida Alta Cobertura é a escolha ideal para quem busca versatilidade em suas atividades de pintura. Esta tinta spray, com cor vibrante, proporciona um acabamento atraente e profissional. O produto oferece alta resistência, sendo perfeito para uso interno e externo. A formulação da tinta garante secagem rápida, reduzindo o tempo de espera entre as demãos e aumentando a eficiência do trabalho. Com um excelente poder de cobertura, uma única camada é suficiente para transformar qualquer superfície. Vantagens: Cor: O cinza primer proporciona um efeito visual marcante. Conteúdo ideal: Com 400ml, é perfeito para pequenos e médios projetos. Secagem rápida: Diminui o tempo de aplicação entre demãos. Alta resistência: Resiste a abrasões e condições climáticas adversas. Versatilidade: Adequada para eletrodomésticos, móveis, brinquedos e artesanato. Fácil aplicação: Fórmula que permite um acabamento profissional mesmo para iniciantes. Especificações técnicas: Marca: Chesy Cor: Cinza Primer Conteúdo: 400ml / 210g Tipo de Uso: Uso geral Secagem: Rápida Poder de Cobertura: Excelente Resistência: Alta Conteúdo da embalagem: 6 - Latas de Tinta Spray Uso Geral 400ml Chesy Garantia: Validade de 36 meses garantida pelo fabricante', 106.9, 106.9, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3nhkzpbw5yt75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F22193595183', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
