INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13245582193', 'Bíblia Sagrada NVI Slim | Letra Normal | Tamanho Grande | Luxo - Preta', 'Desde que chegou ao Brasil, no começo dos anos 2000, a Nova Versão Internacional (NVI) da Bíblia conquistou a preferência de milhões de leitores. O texto adotado é a Nova Versão Internacional (NVI), uma tradução contemporânea das Escrituras que preserva a necessária fidedignidade aos originais sem abrir mão da elegância de estilo e da necessária atualização de formas verbais, unidades de medida e pequenos detalhes – assim, o entendimento é facilitado e pequenos detalhes são melhor percebidos. Por isso mesmo, a GEOGRÁFICA EDITORA tem feito diversos lançamentos de bíblias com esse texto. Agora, a novidade é a Bíblia NVI em Duas Cores, uma linda edição da Palavra de Deus para ser usada tanto na leitura individual como em estudos bíblicos, reuniões e celebrações. Ler a Bíblia NVI em Duas Cores é mais que um deleite para a alma e um alimento para o espírito – é compreender o texto sagrado em uma dimensão poucas vezes experimentada. Código do produto: 00116346Peso: 510gAutor: NVINº de páginas: 768Papel: Papel Bíblia 28gFormato: 23x16cmISBN: 978-65-5655-179-1', 74.9, 74.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/59ded583b9b88bf48db974582346770e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F13245582193', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259038674', 'Batavo Pense Zero Morango Iogurte Grego Zero Lactose', 'O iogurte grego Batavo Pense Zero Morango é zero lactose e não tem adição de açúcares, sendo uma opção deliciosa e saudável para o seu dia a dia. Aproveite os benefícios de um iogurte com 67% menos gordura e apenas 60kcal por porção. Ideal para quem busca sabor e bem-estar sem abrir mão de uma alimentação equilibrada. * 0% Lactose * 0% Adição de açúcares * 67% menos gordura', 3.79, 3.79, NULL, 'Food & Beverages > Dairy & Eggs > Yogurt & Cultured Milk', 'https://cf.shopee.com.br/file/sg-11134201-82590-mqnelcnauvb590', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555155%2F58259038674', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
