INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23298287328', 'ATAQUE DOS TITÃS VOL. 25', 'ATAQUE DOS TITÃS VOL. 25 Falco leva Reiner a se encontrar com Eren, que quer falar com o antigo companheiro sobre o que pretende fazer em Marley enquanto é encenada a peça sobre a história do Império de Eldia, os Titãs e a Ilha Paradis.. Informações Adicionais Autor: ISAYAMA, HAJIME Data Publicação: 01/01/1900 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: ATAQUE DOS TITÃS VOL. 25 Idioma: PORTUGUES Páginas: 192 Edição: 25 ISBN-13: 9788542615098 ISBN-10: 8542615093', 48.28, 48.28, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rcdl-lrzfknjd8qwub2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F23298287328', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593100851', 'Beta Alanina 150g - 100% Pura Importada - Bodybuilders', '💥 Descubra a Beta-Alanina - Seu Novo Melhor Amigo nos Treinos! 💥 🌀 O que é Beta-Alanina? Beta-alanina é um aminoácido não essencial que ajuda seu corpo a produzir carnosina. A carnosina é uma substância mágica que combate o ácido lático nos músculos durante aqueles treinos intensos, ajudando você a ir mais longe sem se sentir esgotado. 🏋️‍♂️💦 🌟 Por que você precisa de Beta-Alanina? Mais Energia: 💪 A beta-alanina aumenta os níveis de carnosina nos músculos, o que ajuda a retardar a fadiga muscular. Treinos mais longos: ⏱️ Permite que você treine mais intensamente e por mais tempo, maximizando os resultados. Menos Queimação: 🔥 Reduz o acúmulo de ácido lático, diminuindo a sensação de queimação nos músculos. Anti-envelhecimento: 🌿 Carnosina tem propriedades antioxidantes que ajudam a proteger as células contra o envelhecimento. 📝 Como tomar? Dilua 2g em 100ml de água e consuma 14ml, 7 vezes ao dia, com intervalos de 2 horas entre as doses. ✨ Benefícios em Destaque: ✅ Desempenho Esportivo Top: Aumenta a resistência muscular e reduz a fadiga, permitindo treinos mais intensos e longos. ✅ Ganho de Massa Muscular Magra: Contribui para o ganho de massa muscular ao permitir treinos mais eficazes. ✅ Retardo da Fadiga Muscular: Diminui a sensação de queimação e cansaço ao reduzir o acúmulo de ácido lático. ✅ Potencial Anti-envelhecimento: Protege as células contra o envelhecimento com suas propriedades antioxidantes.', 49.9, 49.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mdg6tfw24bzt89', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F667636637%2F23593100851', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258529330', 'Boné Oakley Tincan Original Icon Collection', 'Boné Oakley Tincan Original Icon Collection O boné Tincan da Oakley é um acessório moderno e funcional, projetado para quem busca estilo e conforto. Com um design esportivo e elegante, o Tincan tem um material leve e respirável, ideal para atividades ao ar livre. Seu logotipo discreto e acabamento de alta qualidade refletem a tradição da Oakley em oferecer produtos que unem performance e design. - 96.8 % Poliéster - 3.2% Elastano - Logo Oakley metálico frontal e bordado traseiroIlhós para ventilação e faixa acolchoada na testa - Circunferência de 56cm para o tamanho S/M - Circunferência de 58cm para o tamanho L/XL - Altura 16.7cm Sobre a marca Oakley A Oakley é uma marca norte-americana de óculos de sol, óculos esportivos e outros produtos voltados para o público que pratica ou aprecia esportes radicais. Fundada em 1975 por Jim Jannard, a Oakley se destaca pela tecnologia de ponta, pelo design inovador e pela qualidade de seus produtos. A marca possui uma linha variada de óculos de sol, que atendem a diferentes estilos e necessidades, desde os clássicos como o Holbrook e o Frogskins, até os mais modernos como o Sutro e o Plazma. Além disso, a Oakley também oferece óculos de grau, com armações confortáveis e resistentes, e óculos personalizados, que permitem ao cliente escolher as cores e as lentes de sua preferência. A Oakley é uma marca que valoriza a performance, a proteção e a personalidade de seus consumidores. Produto Original', 279.99, 279.99, NULL, 'Fashion Accessories > Hats & Caps', 'https://cf.shopee.com.br/file/br-11134207-820lx-mmurb33rlbep96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1490043415%2F58258529330', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
