INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394090094', 'Cômoda Trocador Infantil 4 Gavetas 1 Porta Nicho Móvel Prático para Quarto de Bebê Menino ou Menina', 'Cômoda Sapateira Baby Bela com Trocador – Organização e Praticidade no Quarto do Bebê A Cômoda Sapateira Baby Bela é a escolha perfeita para quem busca praticidade, segurança e charme no quarto do bebê. Com design moderno e funcional, ela organiza roupas, calçados e fraldas em um só lugar, e ainda conta com trocador integrado, trazendo mais conforto para o dia a dia. Benefícios que Vão Facilitar Sua Rotina: Trocador superior: área plana e segura para troca de fraldas 4 gavetas amplas com corrediças metalicas (abertura suave e segura) Sapateira lateral prática para calçados ou acessórios Puxadores discretos e modernos Pés com regulagem de altura: ideal para pisos irregulares Fácil montagem com manual incluso Medidas do Produto: Altura: 91 cm (com os pés) Largura: 83,8 cm Profundidade: 40 cm Informações Extras: Acompanha manual de montagem Produto entregue desmontado Recomendamos montagem por adulto ou montador profissional Fotos ambientadas são ilustrativas. Itens decorativos não acompanham. Dica do vendedor: Este modelo é ideal para quem tem pouco espaço e quer manter tudo à mão, com estilo e praticidade!', 539.0, 512.05, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-7r98o-masq3s2gfpfz40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467752495%2F22394090094', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594419337', 'Toalha fralda 1 camada Patinhos 100% algodão', 'Toalha Capuz Bebê Papi Bordado Fralda Soft Patos A Toalha com Capuz Papi é ideal para tornar a hora do banho mais confortável e acolhedora. Confeccionada em uma camada de tecido soft, oferece toque suave e excelente absorção, cuidando da pele delicada do bebê. O capuz central proporciona proteção térmica para a cabeça e o pescoço. O charme fica por conta do bordado e estampa delicada com temática de patos e natureza, que trazem um visual lúdico e encantador ao produto. Características: Capuz central que ajuda a manter o bebê aquecido após o banho Feita em tecido soft de alta absorção e toque macio Acabamento reforçado com viés em malha Estampa e bordado com tema de patinhos e natureza Ideal para uso diário desde os primeiros dias de vida Design funcional e visual delicado Informações Adicionais: Tamanho:110x90Único Cores:Amarelo Referência:2142308 Marca: Papi', 49.9, 49.9, NULL, 'Mom & Baby > Bath & Body Care > Bath Robes, Towels & Wash Cloths', 'https://cf.shopee.com.br/file/sg-11134201-824il-meq5vjfktbluf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22594419337', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097508521', 'CONSPIRACY 365 MAIO ENTRE QUATRO PAREDES VOL 05', 'CONSPIRACY 365 MAIO ENTRE QUATRO PAREDES VOL 05 A vida de Cal Ormond está ficando cada vez pior. Até então, o garoto tinha conseguido ficar longe de policiais e de bandidos cruéis. Mas sua sorte parece ter acabado ele se viu preso em um local estranho, intensamente vigiado, com pouquíssimas chances de conseguir escapar. Além disso, o jovem não fazia ideia de onde poderiam estar os documentos que permitiriam decifrar o Perigoso Mistério dos Ormond. Sozinho e tratado como um adolescente problemático, Cal se sentiu em um beco sem saída. Desesperado para retomar sua busca pela verdade, Cal precisava de um plano de fuga, por mais impossível que pudesse parecer. Resta saber se ele conseguiria enganar mais uma vez seus perseguidores e seguir em frente.. Informações Adicionais Autor: LORD, GABRIELLE Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: CONSPIRACY 365 MAIO ENTRE QUATRO PAREDES VOL 05 Idioma: PORTUGUES Páginas: 135 Edição: 1 ISBN-13: 9788539505913 ISBN-10: 8539505916', 28.6, 24.74, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rbn8-lpm61vrcjmjf06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F22097508521', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203013474', 'Ar Condicionado Hisense Inverter 9000 Btus Frio R-32 220v Wi-FI', 'Ar Condicionado Hisense Inverter 9000 Btus Frio R-32 220v Wi-FI Modelos: AS-09UW2RLDTT00E / AS-09UW2RLD00C O Ar-Condicionado Hisense Inverter 9000 Btus Frio R-32 220V é a escolha ideal para quem busca eficiência, tecnologia e conforto em um equipamento compacto e moderno. Com Wi-Fi integrado e controle por voz, ele oferece controle total na palma da mão, permitindo ajustar a temperatura e os modos de funcionamento pelo aplicativo HiSmart Air ou via assistentes virtuais compatíveis. Graças à tecnologia Inverter, o compressor opera de forma inteligente, ajustando a velocidade automaticamente para manter a temperatura constante e garantir economia de até 60% de energia, além de funcionamento extremamente silencioso. O gás refrigerante R-32 proporciona melhor desempenho de refrigeração com menor impacto ambiental, tornando o aparelho mais eficiente e sustentável. O modelo também conta com 4 modos de sono, que ajustam a climatização conforme a idade do usuário — garantindo descanso confortável e seguro para crianças, adultos e idosos. O sistema de autodiagnóstico detecta automaticamente possíveis falhas e exibe códigos de erro no painel, facilitando a manutenção e garantindo mais durabilidade ao produto. Principais Características: Capacidade: 9000 Btus – ideal para ambientes de até 12 m² Ciclo Frio: perfeito para dias quentes Tecnologia Inverter: mais economia e menos ruído Wi-Fi integrado e controle por voz via assistentes virtuais 4 modos de sono: conforto para todas as idades Função Autodiagnóstico: manutenção facilitada Gás R-32: ecológico e eficiente Funções inteligentes: Turbo, Sleep, Timer e Autolimpeza Classificação A em eficiência energética (Procel) Design moderno e elegante, que combina com qualquer ambiente Medida Evaporadora (A x L x P) cm 27 x 74,5 x 21,4 Medida Condensadora (A x L x P) cm 48,2 x 66 x 24', 2420.11, 1984.5, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mja5icg3q6ti82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F827327945%2F58203013474', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094255489', 'Médio Grave Eros E908 Trio Evo 8 Polegadas 450w Rms 6 Ohms', 'A linha TRIO EVO se destaca por sua estrutura robusta, trazendo motores hiper dimensionados, formatos e potências elevadas, produtos com sofisticada construção eletroacústica. Atendem a diversas necessidades, incluindo trio automotivos, caixas bob, entre outras aplicações. Especificações Técnicas • Potência Máxima (RMS): 450W • Impedância Nominal: 6 Ohms • Resposta de Frequência: 79 ~ 4.800 Hz • Sensibilidade (@ 1 W, 1 m) - FREE-AIR: 93,15 dB • Diâmetro Nominal: 8 Polegadas • Diâmetro Ferrite: 220 X 20 mm • Material do Ferrite: Bário • Diâmetro da Bobina: 3 Polegadas • Forma da Bobina: Kapton Black • Altura da Bobina: 16 mm • Altura do GAP: 8 mm • Material do Fio da Bobina: CCAW • Secção do Fio da Bobina: Redonda • Material da Carcaça: Alumínio', 950.0, 950.0, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcmkwaru8qwi5c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229977598%2F23094255489', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20999836603', 'Kit Pano De Boca Incomfral 06 Peças Estampa Ursa', 'Kit Pano De Boca Incomfral 06 Peças Estampa Ursa Kit de Pano de Boca Incomfral é a solução perfeita para manter o bebê sempre limpo e confortável. Composto por 6 peças, cada pano de boca possui 34 cm x 40 cm e é confeccionado em tecido 100% algodão, garantindo maciez e suavidade para a pele delicada do bebê. O acabamento em festonê oferece um toque de delicadeza e reforça a durabilidade da peça, impedindo o desgaste nas bordas e conferindo um visual mais elegante.Este kit é ideal para o uso diário, seja para limpar o rosto do bebê, proteger a roupinha durante a alimentação ou até mesmo para ser utilizado como um acessório prático para a bolsa de maternidade. O tecido 100% algodão proporciona alta absorção, mantendo o bebê sempre seco e confortável.Informações Adicionais:Cores: ColoridoDimensão: 40cm x 34 cmComposição: 100% algodãoReferência: 850240G8Marca: IncomfralDica: Item essencial no enxoval!', 24.9, 24.9, NULL, 'Mom & Baby > Diapering & Potty > Cloth Diapers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdwa-mc2g216mys3k48', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F20999836603', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40607147200', 'VT AZ CARE LOCK MASK, 100mL | Azelaic acid', '[Em exclusivo Glória] MÁSCARA DE TRAVA DE CUIDADOS VT AZ, 100mL ❣️ Fechaduras na umidade e ingredientes para a pele durante a noite para evitar a evaporação! Evita que sua pele seque enquanto dorme, Permitindo que os ingredientes dos cuidados com a pele aderem profundamente e trabalhem de forma eficaz. ❣️ A partir da textura áspera da pele todo o caminho para limpar comédios e espinhas! Exosomes Tiny CICA, menores que os poros, combinados com ácido azelaico para controlar o sebo, direcionar as causas raízes dos problemas da pele removendo o excesso de sebo de dentro dos poros. Comédios e cabeças brancas também ajudam a lidar com os comédios e os cravos. O 4-ACID-COMPLEX (AHA, PHA, BHA, LHA) esfolia suavemente e remove as células mortas desnecessárias da pele morta, criando uma textura suave e refinada da pele. ❣️ INGREDIENTES DE SINERGIA DE INGREDIENTES Ingredientes de beleza sustentáveis ingredientes de beleza para a pele propensos a irritações e problemas. 1. 4-ACID-COMPLEX: Regula o sebo dentro dos poros. 2. Pantenol Pantenol: Proporciona umidade à pele. 3. A alantoína da pele: Previne a aspereza da pele. 4. Esqualano: Hidrata e apoia a barreira cutânea. 5. Extrato de CICA (Centella Asiatica): Ajuda a estabilizar a pele sensível. 6. Árvore do chá do sabonete: Ajuda a equilibrar e acalmar a pele. Modo de Usar 1. Após a limpeza, siga sua rotina habitual de cuidados com a pele. 2. Em seguida, evite os olhos e a boca, aplique uma quantidade adequada uniformemente em todo o rosto. Deixe secar completamente por cerca de 15 a 20 minutos, depois vá para a cama. 3. Na manhã seguinte após acordar, descasque suavemente a máscara de bloqueio e lave levemente o rosto.', 103.81, 99.0, NULL, 'Beauty > Skincare > Face Mask & Packs', 'https://cf.shopee.com.br/file/sg-11134207-7rdxt-mbxeh791z06fa2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F40607147200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '25811331269', 'NUMBUZIN No.5 Glutathione Vitamin Concentrated Toner 200ml', 'NUMBUZIN Tônico Essencial Glutationa Vitamin Boosting No.5, 200ml NUMBUZIN No.5 Glutathione Vitamin Boosting Essential Toner, 200ml [🎯 RECOMMENDED FOR] All skin types: oily, dry, combination, aging, or acne-prone. Especially recommended for following skin concerns: DARK SPOTS, HYPERPIGMENTATION, and DULL SKIN COMPLEXION. [🧴 WHAT IT IS] Skin irritation test completed — A gentle, revitalizing vitamin boosting toner that increases your skin''s intake of ESSENTIAL ANTIOXIDANTS. Make sure to boost your skincare routine by using it with No.5+ Vitamin Concentrated Serum for 133% more effective BRIGHTENING SYNERGY! [🗝️ WHAT IT DOES] Provides 3X FUNCTIONAL, IRRITATION-FREE, and FAST-ABSORBING BRIGHTENING. It has been clinically proven to REDUCE DARK SPOTS by 18.12% in 2 weeks. The lightweight, essence-like texture gives you even skin tone and smooth skin texture for a glowy complexion. [🧪 KEY INGREDIENTS] Formulated with functional, skin-friendly ingredients including Niacinamide (50,000ppm), Vitamins C & E, Panthenol, Liposomal Glutathione, Peptide, and MADEWHITE (20,000ppm), composed of Madecassoside (Centella Asiatica Extracts).', 118.8, 113.0, NULL, 'Beauty > Skincare > Toner', 'https://cf.shopee.com.br/file/sg-11134207-81zu5-milc0rvl60aveb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F25811331269', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
