INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993000882', 'Travesseiro 50x90cm Buddemeyer Vision Fill 100% Algodão Branco', 'CARACTERÍSTICA DO PRODUTO: Alta resiliência, super volumoso - VISION FILL da Buddemeyer é um travesseiro que garante conforto e aconchego para o seu momento de descanso. Extra macio e de alta durabilidade; com acabamento requintado Tecido com toque macio e acabamento de excelente qualidade Qualidade e design Buddemeyer CONTEÚDO DA EMBALAGEM: Contém: 1 travesseiro 50x90cm COMPOSIÇÃO: Tecido da frente em 100% algodão cetim 233 fios com acabamento especial. Enchimento em 100% poliéster microfibra extra macia TIPO DE MATERIAL: Tecido da frente em 100% algodão cetim 233 fios; enchimento em 100% poliéster DESCRIÇÃO: Travesseiro VISION FILL. Tem como principais características ser super volumoso e sua alta resiliência - VISION FILL da Buddemeyer é um travesseiro que garante conforto e aconchego para o seu momento de descanso. Extra macio e de alta durabilidade tem acabamento requintado. Produto não alérgico. Produzidos em 100% algodão cetim 233 fios com acabamento especial, tem seu enchimento em 100% poliéster microfibra extra macia. Podem ir à máquina sempre que for necessário, oferecendo a higienização perfeita. A Buddemeyer é referência em qualidade e estilo. INSTRUÇÕES DE CUIDADO: Lavar antes de usar. Cores escuras devem ser lavadas separadas das cores claras. Lavar em água fria ou em temperatura de até 40°C em processo suave. O melhor sabão para manter as características do produto é o de coco ou neutro, não colocar diretamente no produto. Evite alvejantes e quaisquer produtos a base de cloro, eles atacam o corante dos tecidos. Não exagere no uso de sabão em pó e use pouco amaciante. Permite secadora em temperatura baixa. Não passar. Não lavar a seco.', 263.05, 210.42, NULL, 'Home & Living > Bedding > Pillows', 'https://cf.shopee.com.br/file/sg-11134201-7rffz-m9kwwp3rj0h8dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F462263068%2F23993000882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
