INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27876623111', 'Calibrador de Pressão 100 PSI Portátil Manual Para Pneus (0168) - Lupus', 'O Calibrador Portátil Para Pneus 100 PSI (0168) - Lupus, é o acessório ideal para realizar a medição da pressão de seus pneus. A cabeça do calibrador alcança a válvula do pneu em todas as posições; além disso, este calibrador é feito com material de alta qualidade, proporcionando facilidade no manuseio e no momento da medição da pressão de seus pneus. Descrição do Produto: • Modelo: Calibrador Portátil. • Material: Alumínio. • Uso Indicado: Medir a pressão do pneu em bar, kPa, kgf e psi. • Peso (Kg): 0,02. • Dimensões (mm): (A) 155 mm x (L) 10 mm. • Pressão: 100 PSI. Referência: 0168. Cód. de Fábrica: 3620053. Marca: Lupus.', 18.5, 18.5, NULL, 'Home & Living > Tools & Home Improvement > Air Pumps, Parts & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rcdv-m6ei2f9w57is96', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F27876623111', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19997682660', 'Kit Sabonete Liquido Dermacyd Femina 200ml + 100ml Oferta Especial', 'Além de proporcionar sensação de proteção e frescor por 24 horas, Dermacyd® também neutraliza possíveis odores, deixando você mais confiante o dia todo. Isso porque sua exclusiva fórmula Odor Control tem pH similar ao da região íntima que limpa sem agredir e mantém as defesas naturais.', 40.79, 40.79, NULL, 'Health > Personal Care > Feminine Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd63-lvaweom98sh9ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F19997682660', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398723838', 'Cilindro Mestre Freio Sem ABS Ducato Jumper Boxer 2003 Em Diante', 'Cilindro Mestre de Freio para Citroën, Fiat e Peugeot APLICAÇÃO CITROËN Jumper 2003 em diante FIAT Ducato 2003 em diante FIAT Ducato 2.3 16V 2013 em diante PEUGEOT Boxer 2003 em diante CÓDIGO SBC1073 CÓDIGOS REFERÊNCIA C2163 ESPECIFICAÇÕES Cilindro mestre duplo Material Alumínio Diâmetro Ø 25,40mm Conexões 5 furos M10x1 Sistema Sem ABS VANTAGENS Construção em alumínio de alta resistência Precisão no acionamento do sistema de freio Compatibilidade garantida com veículos comerciais Instalação direta e simplificada Garante a eficiência do sistema de freio Durabilidade e confiabilidade INSTALAÇÃO Sangrar todo o sistema de freio antes da instalação Verificar o nível do fluido de freio Substituir o cilindro mestre seguindo procedimento adequado Realizar sangria completa do sistema após instalação Testar o funcionamento dos freios em local seguro Verificar ausência de vazamentos CONTEÚDO 1 cilindro mestre de freio. Produto novo, acompanha nota fiscal e garantia do fabricante.', 352.99, 294.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi1kz5ocpbsz1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1101226660%2F23398723838', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23196800417', 'Soquete Estriado em Aço Cromo Vanádio 23 mm - Encaixe 1/2'''' Tramontina PRO', 'Os soquetes da Tramontina PRO são produzidos com sistema Hyper Drive que melhora o acoplamento do produto ao parafuso ou porca, reduzindo as tensões geradas no aperto e prolongando a sua vida útil. Escolha o tamanho e perfil ideal para a sua necessidade e mãos à obra. Um grande avanço na produção dos soquetes é a introdução do conceito "Hyper Drive". Este novo perfil melhora o acoplamento do soquete na porca ou parafuso, reduzindo as tensões geradas no aperto, prolongando a vida do soquete e do elemento de fixação.Soquete forjado em aço cromo vanádio e temperado. Acabamento cromado. DIN 3124. Os soquetes são submetidos a testes rigorosos de torque e de dureza para atender a norma DIN 1711-1.Afrouxar e apertar parafusos e porcas sextavados.As ferramentas são produzidas e testadas conforme normas específicas. Os soquetes da Tramontina PRO são produzidos com sistema Hyper Drive que melhora o acoplamento do produto ao parafuso ou porca, reduzindo as tensões geradas no aperto e prolongando a sua vida útil. Escolha o tamanho e perfil ideal para a sua necessidade e mãos à obra.', 23.8, 23.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7r99o-ll5d82mh1jqt1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23196800417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22792256596', 'Chave Combinada 9/16'''' (44670/105) - Tramontina Pro', 'Ideal para apertar e afrouxar parafusos ou porcas com perfil quadrado ou sextavado, as chaves da Tramontina PRO são fabricadas com matéria prima que garante alta resistência e durabilidade. Para perfeito funcionamento é importante usar a chave de tamanho compatível à cabeça da porca ou parafuso. Com as chaves da Tramontina PRO, quem passa aperto é o parafuso. Cabeça usinada.Pescoço longo.Acabamento cromado.Abertura da boca calibrada.DIN 3113.ISO 7738.As chaves de aperto são produzidas em aço ligado com cromo vanádio (Cr-V), e após submetidas a testes rigorosos de torque para atender a norma DIN 1711-1.O teste de dureza é realizado em vários pontos para assegurar a resistência ao desgaste da chave durante o uso ininterrupto.Afrouxar e apertar parafusos e porcas sextavadas e quadradas.As ferramentas são produzidas e testadas conforme normas específicas. Ideal para apertar e afrouxar parafusos ou porcas com perfil quadrado ou sextavado, as chaves da Tramontina PRO são fabricadas com matéria prima que garante alta resistência e durabilidade. Para perfeito funcionamento é importante usar a chave de tamanho compatível à cabeça da porca ou parafuso. Com as chaves da Tramontina PRO, quem passa aperto é o parafuso.', 24.5, 24.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbk0-lkmealxzl4m032', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F22792256596', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
