INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '7357446581', 'Papel De Parede Arabesco Adesivo Vinílico Lavável', 'IMPORTANTE!! INFORME A MEDIDA DE SUA PAREDE EM ALTURA E LARGURA PARA QUE POSSAMOS AUXILIAR EM SUA COMPRA. Papel de parede adesivo vinílico, autocolante e lavável. Ideal para decoração de sala, quarto, cozinha, banheiro ou outros ambientes. Rolo com 3,0 metros x 40 centímetros Papel de parede, autocolante, lavável e fosco. Impresso em material 0.10 Material: PVC vinílico, polimérico fosco e não tem cheiro. Antibactericida, Antimofo e não propaga chamas Dica para aplicação: Limpe o local com um pano úmido, certifique-se de retirar todo o pó da parede para melhor fixação do produto. Abra o papel em uma superfície plana, verifique a emenda do produto e alinhamento do mesmo. Vitalidade da aplicação, média esperada: Interna 5 anos. Externa 2 anos.', 54.9, 32.9, NULL, 'Home & Living > Decoration > Wallpapers & Wall Stickers', 'https://cf.shopee.com.br/file/68468011e3d64930650b424b5b92bd0e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322399178%2F7357446581', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18074713382', 'A tempestade: 3º ato - Lesley Livingston', 'Eu não amo Sonny Flannery!”Quando percebeu que era o ponto fraco de Sonny, Kelley não teve outra opção a não ser mentir para proteger a vida de seu grande amor. Na terrível batalha que devastou o teatro de sua companhia, a herdeira do Reino Encantado descobriu que a verdade a respeito da origem de Sonny esconde um perigoso segredo, de que nem mesmo ele tem consciência. E renunciar ao homem que ama é o único modo de mantê-lo a salvo.O plano dá certo! Desorientado e devastado, Sonny foge e acaba descobrindo um refúgio subterrâneo em plena cidade de Nova York, habitado por vários seres mágicos perdidos. Ao fazer amizade com eles, Sonny descobre que desde os eventos desencadeados pelas Nove Noites o lugar vem sofrendo misteriosos ataques, e fica muito intrigado ao perceber que as marcas deixadas nas vítimas lhe são familiares.Uma guerra está começando a se armar. O portal entre os mundos está cada vez mais instável, e seres mágicos revoltosos estão começando um levante junto de traidores que se infiltraram entre os lendários Guardiões Janos. Uma nova fonte de poder incalculável está se manifestando, atraindo a ganância de seres mágicos poderosíssimos que querem se apossar dela para dominar os dois mundos.Mas Kelley não está disposta a permitir que isso aconteça. Agora, mais do que nunca, ela precisa dominar seus poderes para conseguir reunir todos os aliados que puder para desvendar quem está por trás de tudo e derrotar o inimigo, além de descobrir um meio de ter Sonny de volta com vida.A Tempestade é o terceiro volume da série criada por Lesley Livingston. Os dois primeiros volumes são Nove noites e um sonho de outono e À espera de Romeu. Detalhes do produto Capa comum: 304 páginas Editora: Gutenberg; Edição: 1ª (1 de março de 2017) Idioma: Português ISBN-10: 8582353685 ISBN-13: 978-8582353684 Dimensões do produto: 14 x 1,5 x 21 cm Peso de envio: 340 g', 24.9, 24.9, NULL, 'Books & Magazines > Books > Adult''s Books', 'https://cf.shopee.com.br/file/sg-11134201-23030-t001wc2qv4nv5d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F18074713382', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57859010995', 'Bicicleta de Equilíbrio Balance Gug Sem Pedal Verde Com Cestinho - Shiny Toys', 'Bicicleta de Equilíbrio Gug Verde 30cm da Shiny Toys, ideal para desenvolver o equilíbrio e coordenação das crianças de forma divertida. Sem pedais, é perfeita para os pequenos aprenderem a se equilibrar com segurança. Leve, prática e com design moderno para acompanhar cada aventura! FUNÇÕES: - Banco ajustável - Com Cestinho - Sem Pedal CARACTERISTICAS: Marca: Shiny Toys Faixa Etária: +3 Contém: 1 Unidade Banco Ajustável? Sim Peso Max. Suportado: 30 KG Composição: Plástico, Metal, Borracha e Rodas em Eva Dimensão do Produto: 37 x 73 x 54cm (LxAxP) Dimensão da Embalagem: 15 x 54 x 28cm(LxCxA) Garantia: 3 meses INMETRO: 006881/2023', 179.0, 179.0, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134201-820m7-mqyg07h6us5h99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F406894684%2F57859010995', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
