INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27587162879', 'Livro Box - Easy Classics Children''s Collection Series 2 W.Books', 'The Children''s Classics. 10 Book Collection. Volume 2: Treasure island, Just so stories, A little princess, The story of Doctor Dolittle, Heidi, Five children and it, Through the looking-glass, The happy prince, Little women and The adventures of Huckleberry Finn._x000D_ _x000D_ Editora: W. Books_x000D_ Edição: 1, 2025_x000D_ Autor: Ciranda Cultural _x000D_ Idioma: Inglês_x000D_ Páginas: 1200_x000D_ Dimensões: L 13.00 x A 20.00 x E 7.50_x000D_ ISBN: 7908312127640_x000D_ Coleção: Easy Classics #2_x000D_ Linha Editorial: W. Books - Infantil_x000D_ Faixa Etária: + 9 anos_x000D_ Assuntos (tags): Literatura estrangeira, Box, Clássicos_x000D_ BISAC: Literatura Juvenil / Literatura Juvenil / Clássicos_x000D_ Linha de Produto: W. Books_x000D_ Encadernação: Brochura_x000D_ Acabamento: Laminação fosca e verniz localizado_x000D_ Material: Papel', 149.9, 74.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rasi-maisuejmnchf9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F27587162879', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43308752358', 'Esponja Banho Infantil Bob Esponja com 1 unidade', 'Esponja Banho Infantil Bob Esponja – 1 unidade A Esponja Banho Infantil Bob Esponja é perfeita para tornar o momento do banho das crianças mais divertido e agradável, com um personagem que encanta os pequenos. Feita com material macio, proporciona uma limpeza delicada e eficiente. Principais Características: • Design divertido com o personagem Bob Esponja, ideal para estimular as crianças durante o banho • Material macio e suave, adequado para a pele delicada dos pequenos • Tamanho compacto, fácil de segurar e manusear Benefícios: • Proporciona uma limpeza eficaz sem agredir a pele infantil • Torna o banho um momento lúdico e prazeroso para a criança • Facilita a aplicação do sabonete, otimizando o uso do produto • Produto resistente e de fácil enxágue Diferenciais do Produto: • Produto licenciado com a temática do Bob Esponja, personagem muito querido pelas crianças • Material seguro e hipoalergênico, ideal para a pele sensível • Praticidade e conforto para pais e filhos na hora do banho Especificações Técnicas: Peso: aproximadamente 40g Instruções de Uso: Umedeça a esponja e aplique o sabonete. Espalhe suavemente pelo corpo da criança, evitando contato com os olhos. Após o uso, enxágue bem e deixe secar em local arejado. Avisos e Precauções: Uso externo. Manter fora do alcance de crianças sem supervisão. Em caso de irritação, suspenda o uso e consulte um médico. O que está incluso? 01 unidade de Esponja Banho Infantil Bob Esponja ---- DÚVIDAS FREQUENTES ---- Os produtos são originais? Sim. Todos os nossos produtos são originais. Emitem nota fiscal? Sim. Emitimos nota fiscal para todos os pedidos.', 37.49, 28.59, NULL, 'Home & Living > Bathrooms > Bath Brushes & Loofahs', 'https://cf.shopee.com.br/file/sg-111