INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993089894', 'Kit De Acessórios Banheiro Cabide Toalheiros Papeleira 15 Peças Yesop', 'Conjunto de acessórios de banheiro de 15 peças Escovada contendo: - 1 Toalheiro, - 1 Suporte para papel higiênico, - 1 Anel de toalha, - 2 Suporte para barbeador, - 2 Suporte para escova de dentes, - 2 Suportes para esponja, - 3 Gancho de borracha, - 1 Suporte para esfregão - 1 Suporte para esfregão com gancho, -1 Bandeja de sabão. Um conjunto completo de organizadores Todos os seus produtos de higiene pessoal. Características: Adequado para decoração de diferentes estilos. Projetado com linhas elegantes e simples, o conjunto de toalheiros de banheiro trará um toque de design moderno à sua casa. Materiais de alta qualidade: Feitos de aço inoxidável 304 espesso, esses acessórios protegem contra corrosão e ferrugem no ambiente úmido. Com o acabamento metálico Escovado de uma beleza incomparável evitando manchas e arranhões. Adicionados um toque moderno ao seu banheiro e as bordas chanfradas protegem seu corpo contra arranhões. 5. Perfeito para qualquer lugar: Linhas limpas e construção robusta, você pode usar em vários ambientes diferentes tornando a sua casa mais bonita e moderna. Material: aço inoxidável sus304 Cor: acabamento preto fosco Instruções de instalação: Perfuração/Autoadesivo Perfuração: 1. Marque a posição dos furos de instalação com uma caneta. 2. Faça furos na parede com uma broca de 6 mm. 3. Usando um martelo para acertar a âncora nos buracos 4. Fixe a junta dos produtos à parede com parafusos (incluídos) 5. Use a ferramenta para instalar as outras peças dos produtos. A instalação está pronta!', 249.0, 79.99, NULL, 'Home & Living > Bathrooms > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd47-lx0zne85ifgq98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F464586953%2F23993089894', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
