INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10823517108', 'NIVEA Creme Hidratante Lata 56g', 'O que é? NIVEA Creme Hidratante Lata é um poderoso hidratante para todos os tipos de pele, que está há mais de 110 anos cuidando da pele de muitas gerações. Para que serve? Com sua fórmula enriquecida com glicerina e Eucerit®, ele proporciona um toque suave e hidrata especialmente áreas mais ressecadas do corpo, como cotovelo, calcanhar, joelho, mãos e pés. Além disso, NIVEA Creme Hidratante Lata protege do frio, é ideal para ser usado como hidratante pós-barba, pode ser utilizado para fazer massagens e também cuida da pele tatuada. Desfrute de todos esses benefícios com um clássico NIVEA! Benefícios e diferenciais - Protege do frio - Hidratante pós-barba - Pode usar para fazer massagens - Cuida da pele tatuada e muito mais! - Previne rugas Modo de usar Use o NIVEA Creme no corpo, mãos e rosto sempre que sua pele precisar de uma hidratação intensiva.', 30.9, 30.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mea2rye0xybn18', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F502619181%2F10823517108', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19164574464', 'Cozinha Completa de Canto com Rodapé Veneza Multimóveis MP2083 com Armário e Balcão Branca', 'A Cozinha Completa de Canto com Rodapé Veneza Multimóveis MP2083 com Armário e Balcão tem um excelente custo benefício e um amplo espaço interno. Produzida em MDP com acabamento acetinado (cerca de 20% de brilho), que garante maior durabilidade e resistência, possui corrediças metálicas (mais leveza no manuseio), rodapés, que deixam o ambiente mais estiloso, puxadores em ABS e tampo em MDP 15mm com pintura de alta resistência. Os módulos de canto podem ser montados dos dois lados (esquerdo ou direito), conforme a sua preferência. Esta cozinha conta, ainda, com balcão com tampo removível (compatível com pia de 150 cm), com 1 gaveta e 3 portas e balcão para cooktop (o recorte do tampo deve ser realizado na hora da montagem conforme a medida do seu fogão) com 1 gaveta e 1 porta. Os módulos são individuais e você pode montar da maneira que se adaptar melhor ao seu ambiente. Conteúdo da Embalagem: 1 (um) armário para forno e microondas 62cm 1 (um) armário aéreo 70cm 1 (um) armário aéreo de canto 90cm 1 (um) armário aéreo 150cm 1 (um) balcão com tampo 70cm 1 (um) balcão com tampo de canto 90cm 1 (um) balcão com tampo 150cm 1 (um) armário aéreo 70cm 1 (um) kit com rodapés Dimensões do produto montado: Altura: 203cm | Largura: 222 x 272cm | Profundidade: 32cm (aéreos) - 53cm (balcão com tampo e paneleiro) *Você pode consultar as medidas internas na imagem técnica do produto. Disponível nas cores: Branco - Preto Acetinado Texturizado *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração e eletros não acompanham o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem..', 3779.9, 2599.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7qvcz-li0f668mxypa2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F19164574464', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
