INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19057587723', 'Pulseira infantil arco-íris colorido prata 925 com extensor', 'Tamanho: 15cm (13cm + 2cm de extensor) Material: Prata 925 Peso: 1,80 gramas Itens inclusos Certificado de GarantiaNota Fiscal Todas as nossas peças são de prata legítima, compre e tenha certeza de receber uma joia com duração para o resto da vida. A prata 925 é um material que tem garantia e durabilidade permanente, assim como o ouro 18k. Nossas jóias tem certificado de autenticidade reconhecidos no mundo todo, você pode levar em qualquer joalheria para efetuar os testes e comprovar a autenticidade das mesmas. Havendo dúvidas, não hesite em perguntar por favor! Será um prazer atendê-lo. Aqua Jóias', 139.0, 79.99, NULL, 'Fashion Accessories > Bracelets & Bangles', 'https://cf.shopee.com.br/file/br-11134207-820mf-mnencyx1ct8k82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F19057587723', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23597150247', 'Pingente Feminino de Prata 925 Olho Grego Detalhado', 'Pingente Feminino de Prata 925 Olho Grego Detalhado Este encantador pingente de Prata 925 apresenta um detalhado Olho Grego com 20mm de tamanho. O Olho Grego em destaque tem 5mm, adicionando um toque de proteção e estilo à peça. Especificações: Tamanho: 20mm Tamanho do Olho Grego: 5mm Peso: 1.2g Material: Prata 925 Estilo e Proteção O Pingente Feminino de Prata 925 Olho Grego Detalhado é mais do que uma joia; é um símbolo de proteção e elegância. Adicione este pingente à sua coleção para expressar seu estilo único e atrair boas energias. Descubra Mais na Aqua Joias Explore nossa coleção completa de pingentes em Prata 925 e descubra uma variedade de designs significativos. Na Aqua Joias, oferecemos joias de qualidade que contam a sua história.', 99.0, 67.99, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lod2756os4snb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F23597150247', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23194459633', 'Quebra-cabeça 200 Peças Espaço Sideral - Grow', 'Não deixe de brincar e se divertir com este quebra-cabeça! São 200 peças, para você encaixar uma a uma até formar uma linda imagem. Mais que um passatempo divertido, os quebra-cabeças desenvolvem o raciocínio, relaxam e se transformam num autêntico hobby. Fabricante: GROW Ref.: 04565 Código Barras: 7908010145656 Idade recomendada: Acima de 7 Anos Dimensões da Embalagem (AxLxC): 27X16X7cm Garantia do Vendedor: 7 dias Garantia do Fabricante: 3 meses Produto original, novo, lacrado e acompanhado de Nota Fiscal.', 49.99, 49.99, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfdxir9e0d1h14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1162387686%2F23194459633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598008079', 'Faqueiro Polywood 12 Peças Tramontina 21198/776', 'O Faqueiro Polywood 12 Peças Tramontina 21198/776 é uma excelente escolha para quem busca qualidade e praticidade na hora de preparar churrascos. Este conjunto inclui 12 peças feitas de aço inox, garantindo durabilidade e resistência ao desgaste. As lâminas são tratadas termicamente para manter o fio afiado por mais tempo. Os cabos são feitos de madeira Polywood, tratada para resistir ao tempo, à umidade e aos impactos, proporcionando um toque elegante e durável. O conjunto inclui 6 facas para churrasco de 5 polegadas e 6 garfos de mesa, perfeitos para qualquer ocasião, seja ela especial ou informal. Além disso, o faqueiro é compatível com lava-louças, facilitando a limpeza e o armazenamento. A Tramontina é uma marca renomada, conhecida pela sua qualidade e confiabilidade, tornando este conjunto uma excelente adição à sua cozinha.', 281.12, 224.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Camping & Hiking', 'https://cf.shopee.com.br/file/sg-11134201-7renc-m274on2bn03f85', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412527932%2F22598008079', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599359471', 'Kit 3 Fita Crepe 48MM X 50M 3M 101LA', 'A Nova Fita 3M 101 LA é a melhor crepe para o uso geral e mascaramento de pintura imobiliária, garantindo um trabalho profissional e de qualidade, porque oferece características como: - Adesão inicial adequada para não soltar da superfície. - Alto tack. - Facilidade de aplicação. - Boa conformação em superfícies irregulares. - Desenrolamento leve. - Remoção limpa. - Facilidade de remoção. - Linha de pintura com excelente acabamento - Largura: 48mm - Comprimento: 50 metros', 56.5, 56.5, NULL, 'Stationery > School & Office Equipment > Strings & Tapes', 'https://cf.shopee.com.br/file/sg-11134201-7rdwx-lz0hp44lf2ukea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1328711923%2F19599359471', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20299304480', 'Porta Lenço Umedecido com Vedação Bichinhos Petit Plasútil', 'Porta Lenço Umedecido com Vedação Bichinhos Petit Plasútil Dimensao: (Comp x Larg x Alt): 19,6x11,4x4,4 cm - BPA FREE: livre de bisfenol-A e atóxico. Fabricado em plástico polipropileno (PP). - Capacidade sugerida: pacote de 48 lenços umedecidos. - O produto possui tampa emborrachada com vedação, o que impede a troca de ar com o ambiente externo. Dessa forma, garante maior durabilidade ao seu pacote de lenços abertos, fazendo com que eles não percam o aspecto úmido e fiquem secos antes da hora. - Ideal para ser colocado em banheiros, lavabos, trocadores, bolsas de passeio, malas, mochilas escolares... - Produto funcional que facilita o dia-a-dia..', 23.9, 22.9, NULL, 'Mom & Baby > Bath & Body Care > Wipes', 'https://cf.shopee.com.br/file/sg-11134201-8260u-mj71gnb024n4c1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F20299304480', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20499385481', 'Kit Torcedor 3 Peças Botafogo Futebol Plasútil', 'Kit Torcedor 3 Peças Botafogo Futebol Plasútil Dimensao: (Comp x Larg x Alt): 31,5x17,0x16,5 cm *PRODUTO OFICIAL LICENCIADO* - É gooooool da Plasútil! Com nosso kit torcedor, torcer para o seu time do coração ficou ainda mais emocionante: com as cores, brasões e elementos que representam os maiores clubes do Brasil, esses produtos são para os fãs de carteirinha, hein? - Kit composto por 3 peças: *Copo 700 ml: copo ideal para água ou refrigerante. *Garrafa VIP Coqueteleira 660 ml: com tampa rosca e anel de silicone para de vedação, além de alça para facilitar o transporte, essa garrafa é ideal para mochilas ou bolsas de passeio. Para os adultos, é uma ótima pedida também para preparo de drinks ou bebidas refrescantes em dias de partida. *Marmita com divisória e travas 850 ml: possui tampa emborrachada, com isso, os alimentos ficam até 3x mais conservados, pois a borracha impede a troca de ar com o ambiente externo, além de evitar vazamento. *As travas laterais garantem um fechamento seguro. *Com a divisória removível é possível organizar dois tipos de lanche/alimentos em um único recipiente, otimizando espaço bolsas térmicas ou mochilas. - Fabricado em plástico polipropileno (PP). Atóxico e livre de bisfenol-A (BPA FREE). - Não deve ser lavado na lava-louças. - Decoração injetada no plástico (não é um adesivo)..', 79.99, 79.99, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rdw7-m0a7o84kwtny58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F20499385481', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699371490', 'Kit Higiene Urso Caramelo Ursinho Bebê 5 Peças Plasútil', 'Kit Higiene Urso Caramelo Ursinho Bebê 5 Peças Plasútil Dimensao: (Comp x Larg x Alt): 19,0x12,0x25,5 cm - A chegada de um bebê é um momento muito especial e muito esperado pela família. Nesse período de ajustes e aprendizado é importante termos no dia a dia, produtos que irão facilitar a rotina da casa. - Pensando nisso, nosso kit higiene é fabricado em polipropileno, um tipo de plástico atóxico e livre de bisfenol-A (BPA FREE), ou seja, totalmente seguro para o recém-nascido. - Ele é composto por 5 peças (CxLxA ou DxA): Cesta Organizadora (24,7x18,7x6,3 cm): você pode organizar os itens do kit como preferir. Dispenser para Álcool Gel 480 ml (6,5x23,1 cm): higienização das mãos constantemente. Porta Cotonete com Tampa (8,3x10,2 cm): produtos de uso contínuo em seu devido lugar. Porta Algodão com Tampa (8,3x10,2 cm): produtos de uso contínuo em seu devido lugar. Molhadeira 380 ml (12,3x5,3 cm): recipiente exclusivo para água morna. - Decoração coordenada com personagens e ornamentos que trarão charme e fofura ao quarto dos pequenos. - E o mais legal: todos os produtos podem ser utilizados após essa fase de outras formas! Excelente custo/benefício!.', 61.9, 35.9, NULL, 'Mom & Baby > Nursery > Storage & Organization', 'https://cf.shopee.com.br/file/sg-11134201-8261u-mlfbxay4nmyte8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F23699371490', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18399504558', 'Sanduicheira Minnie 3D Lancheira Infantil 1 Peça Plasútil', 'Sanduicheira Minnie 3D Lancheira Infantil 1 Peça Plasútil Dimensao: (Comp x Larg x Alt): 15,6x13,8x4,5 cm Capacidade: 600,0 ml *ATENÇÃO - PRODUTO SORTIDO*: A sanduicheira Minnie é composta por 4 rostinhos/carinhas da personagem (como mostra a foto principal). Não é possível escolher qual será enviada. O envio é feito de forma aleatória. - A sanduicheira possui tampa acoplada e aba para facilitar a abertura. Perfeita para lanchinhos com pão de forma ou bisnaguinhas. - É um produto ideal para lancheiras escolares e bolsas de passeio. - Diferencial lúdico: a personagem fica em 3D/relevo. - Fabricado em plástico polipropileno (PP). Atóxico e livre de bisfenol-A (BPA FREE). - Decoração injetada no plástico, não adesivada: segurança aos pequenos..', 19.9, 19.9, NULL, 'Home & Living > Kitchenware > Food Storage', 'https://cf.shopee.com.br/file/sg-11134201-7rdwf-m0vn7g0msooy70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F648928964%2F18399504558', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898021843', 'Pré Filtro Bomba De Combustivel Ford Fiesta Ka Ecosport', 'Pré-Filtro da Bomba do Módulo de Combustível Sistema: Bosch Aplicação: Ford: Ecosport 1.6 16v Flex 14/... Sigma Ecosport 2.0 16v Flex 14/... Duratec Fiesta 1.5/1.6 16v Flex 13/... Sigma Ka 1.0 3 Cilindros 12v Flex 14/... Ka 1.5 16v Flex 13/... Sigma GM: S10 2.5 16v Flex 14/... VW: UP 1.0 3 Cilindros 12v Flex 16/... Similares: Duparts: ASF0234 DS: DS1330 DSC: DSC3033 Bosch: F000TE171V / 0580454113 / 0580454137 / D3B59C358AA / CN159H307AA / CN159H307BA / CN159H307GA / CN159H307HA / D3B59H307AE INFORMAÇÕES IMPORTANTES: Todos os produtos são novos, originais e contam com garantia. Todos os itens anunciados estão disponíveis em estoque e são enviados com rapidez. Você pode simular o custo do frete antes da compra clicando em “ver custos de envio”. A nota fiscal é emitida automaticamente com os dados cadastrados em sua conta. Certifique-se de que o endereço de entrega esteja atualizado antes de finalizar a compra. Confirme a compatibilidade da peça com o modelo do seu veículo. Para peças automotivas, recomendamos que a instalação seja realizada por um profissional especializado. GARANTIA: 3 MESES. Caso tenha alguma dúvida, entre em contato. Estamos à disposição para ajudar!', 39.9, 39.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7reot-m2k4symzoyty23', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1368233237%2F22898021843', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23897765563', 'BICICLETA BIKE ARO 29 MTB ALUMÍNIO KSX 24V MARCHAS INDEX CABEAMENTO INTERNO UNISSEX', 'DIFERENCIAIS DA BIKE KSX A marca KSX foi criada com o propósito de revolucionar o mercado do ciclismo no Brasil! As Bikes da marca KSX são montadas com altíssimo nível de qualidade, seguindo o mesmo padrão de excelência das outras Bikes que já são vendidas em nossa loja, mas trazem algumas vantagens adicionais que merecem destaque: * Quadro integralmente produzido com alumínio liga 6061 (mais resistente). Poucos sabem, mas boa parte dos quadros de alumínio possui a liga 6061 apenas em alguns tubos e não no quadro inteiro (para reduzir custos). O quadro KSX é 100% liga 6061; * Geometria atualizada com ênfase no trinômio performance-conforto-beleza, oferecendo o que há de mais moderno nesse quesito; * 100% de cabeamento interno (superior, inferior e traseiro), melhorando muito a estética da Bike, sem deixar cabos à mostra; * Manopla emborrachada e personalizada, permitindo maior conforto anatômico para as mãos, uma das principais reivindicações de nossos clientes; * Maior variação de cores, com lançamento de diversas cores novas que são tendências de mercado e que estão caindo no gosto da galera; * Adesivos com grafismo mais sofisticado, inclusive para os aros, com elementos gradientes e efeitos degradê: * Possibilidade de personalização da Bike, já que o nosso adesivo vinil é produzido com material de altíssima qualidade e permite a substituição de cores com combinações diferentes (é possível também a simples remoção dos adesivos, produzindo o efeito de envelopamento); * Brinde Especial: todas as Bikes KSX acompanham uma linda Squeeze, já com o suporte para instalação na Bike. Assim, a hidratação durante o pedal não será mais um problema pra você! * Embalagem personalizada (caixa exclusiva) para que você tenha a melhor experiência de compra conosco; * SAC humanizado: nada pior do que ter um problema com sua bike e não ter com quem falar. Pensando nisso, criamos um Serviço de Atendimento ao Cliente altamente especializado, com foco total na atenção aos nossos clientes. Pode ter certeza, faremos de tudo para que você tenha a melhor experiência possível com a sua Bike KSX!! FICHA TÉCNICA - Garfo Suspensão C/ Curso de 100mm Preto C/ Adesivo combinando; - Rodas Tamanho 29 em Alumínio Montadas para Freio a Disco; - Aro Aéreo Alumínio Parede Dupla C/ Adesivo combinando; - Cubo Preto Especial C/ 36 Furos para Freio a Disco; - Raios Pretos de 288mm C/ Niples; - Pedivela Triplo Index Aço Revestido C/ Protetor Estilo Carbon; - Movimento Central 34.7 de Rolamento Blindado 122.5mm; - Freio a Disco Alumínio C/ Pastilhas Especiais e Discos de 160mm; - Pneu MTB C/ Cravo 29x2.10 Pro Preto; - Roda Livre Dourada Index de 8 Velocidades; - Alavancas Rapid Fire Index P/ 24 Velocidades C/ Maçanetas de Alumínio; - Câmbio Dianteiro Index Preto Top Pull 31.8mm P/ Coroa Tripla; - Câmbio Traseiro Preto Index Cage P/ 8 Velocidades; - Pedal Plataforma Inglês Preto; - Corrente Fina P/ 8 Velocidades Index; - Suporte do Guidão em Alumínio C/ 31.8mm; - Abraçadeira do Selim em Alumínio C/ 31.8mm x 15mm; - Selim MTB Preto C/ Castanha (Carrinho); OBSERVAÇÕES E RECOMENDAÇÕES: Considerando que a Bike é composta de mais de 30 itens (guidão, selim, pneus, pedivela, etc.), e tendo em vista a oscilação e eventual escassez de produtos no mercado de ciclismo, poderão ocorrer pequenas variações nos componentes informados na descrição/fotos do anúncio (marca/modelo/versão), desde que não reduza a qualidade anunciada e não afete o perfeito funcionamento do produto. GARANTIA: * Quadro: 01 ano contra defeito de fabricação. * Componentes: 03 meses contra defeito de fabricação. * A garantia não cobre defeitos causados por mau uso ou montagem inadequada. * Não inclui cobertura para serviços como regulagem final, alinhamento de rodas, discos, manutenções, lubrificações, sangrias, revisões e outros ajustes. PRODUTO NOVO E ORIGINAL COM NOTA FISCAL E GARANTIA', 1499.0, 899.99, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/br-11134211-820lo-mq4vq66wo4cg3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1354263324%2F23897765563', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23697271852', 'Meia Penalty Cotton Performance T 33-38', 'A Meia Infantil Penalty Cotton de alta performance oferece uma combinação perfeita de tecnologia avançada e design futurista para atender às demandas dos atletas mais exigentes. Projetada para elevar seu desempenho, esta meia oferece não apenas funcionalidade, mas também estilo. Benefícios: Conforto aos pés. Meia com sola atoalhada. Faixa tensora no pé Alguns diferenciais técnicos: Faixa tensora nos pés oferece suporte e compressão na região, juntamente com a sola atoalhada proporciona colchoamento e proteção nas áreas dos tornozelos e tendão de Aquiles, aumentando o conforto. Essas características são projetadaspara melhorar o desempenho e o conforto durante o uso da meia, especialmente em atividades esportivas ou situações em que essas áreas específicas do pé precisam de cuidados adicionais. Experimente o conforto supremo, suporte e inovação com a Meia Infantil Penalty Cotton de alta performance.', 28.9, 28.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Soccer, Futsal & Sepak Takraw', 'https://cf.shopee.com.br/file/br-11134201-820lq-mqyaulhvdseef9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F786526144%2F23697271852', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398795384', 'Cafeteira Espresso Oster PrimaLatte Touch Red para Cápsula, Pó e Sachê', 'Cafeteira Espresso Oster PrimaLatte Touch Red para Cápsula, Pó e Sachê Seu café com 2x mais sabor, em apenas 1 toque. Cafeteira Espresso Oster PrimaLatte Touch Oster® te proporciona uma experiência com 2x mais sabor, aroma, cremosidade, cores e texturas de um café latte perfeito. - Design Exclusivo Oster: A evolução do design que todos os amantes do café já conhecem. Agilidade no preparo de um café fresquinho e personalizado em poucos minutos. O design clássico que você já conhece com ainda mais detalhes de acabamentos que vão encantar você. - 2X Mais Creme: Sua experiência gourmet com café agora é duas vezes mais cremosa. Prepare o seu café e deixe a cremosidade tornar o momento de degustação muito mais saboroso e especial. - Compatível com a sua Rotina: A PrimaLatte Touch Oster® permite fazer um café saboroso com o pó, sachê ou cápsulas Nespresso®* - Painel Touch com Funções Automáticas: Fácil de usar, com opções para diversos tipos de café. Você personaliza e adiciona toques para fazer o café do seu jeito. O painel também conta com as funções de limpeza para os tanques de água e leite. - Tecnologia e Agilidade: Bomba profissional fabricada na Itália com 19 bar de pressão que garantem um espresso mais denso e saboroso. Funções fáceis para preparar qualquer tipo de café. Primalatte Touch, seu ambiente merece o melhor em design e sofisticação para o momento do café.', 1399.0, 1049.0, NULL, 'Home Appliances > Kitchen Appliances > Coffee Machines & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-825b8-mr20ph6722h1bc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1573223607%2F23398795384', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
