INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794677429', 'Estojo Azul - Unico', 'O estojo infantil Patrulha Canina ? a escolha perfeita para acompanhar as crian?as na escola com muito estilo e praticidade. Produzido em pel?cia macia e resistente, possui design exclusivo da cole??o oficial e formato box, que garante espa?o interno bem distribu?do para acomodar at? 100 l?pis, canetas e acess?rios escolares. Com dimens?es de 22 x 15 x 6 cm, ? um modelo de tamanho m?dio, ideal para organizar l?pis de cor, canetinhas, borrachas, apontadores e outros itens do dia a dia escolar. Al?m de funcional, ? divertido e traz o universo encantador da Patrulha Canina, que as crian?as adoram. Ideias de uso: perfeito para levar ? escola, cursos de arte, atividades extracurriculares ou at? mesmo para guardar materiais de desenho em casa. Tamb?m pode ser utilizado como estojo de viagem para transportar itens pequenos, como bijuterias, carregadores ou cabos. Limpeza e cuidados: por ser em pel?cia, recomenda-se limpeza apenas com pano macio levemente ?mido e sab?o neutro. Evite alvejantes, m?quinas de lavar ou produtos abrasivos para preservar as cores e a textura do material. C?digo do Inmetro: 005839/2025 ? Produto certificado, garantindo seguran?a e qualidade para o uso infantil.', 99.9, 99.9, NULL, 'Stationery > School & Office Equipment > Pencil Cases', 'https://cf.shopee.com.br/file/sg-11134201-8258o-mqs338qs0oi54c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1251967897%2F22794677429', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
