INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16473157473', 'Kit Transmissão Relação VAZ Haojue Chopper Road 150 CBS 2018- S/ Retentor', 'KIT certificado INMETRO , A coroa Temperada, o pinhão e a corrente que compõem o novo kit VAZ Xtreme BLACK de Transmissão oferecem alta performance, durabilidade e maior resistência. Disponíveis em variedade de opcionais e acabamentos foram desenvolvidos a partir de modernas tecnologias, equipamentos de última geração, submetidos a tratamentos especiais e com as melhores matérias-primas. CODIGO PRODUTO D00357X / CODIGO COROA SA02.142T / CODIGO PINHAO SB07.214 / CODIGO CORRENTE 428H116. Garantia 3 meses defeito fabricação Foto Ilustrativa', 192.22, 192.22, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-7qve3-lj0nd0ghp0y5d0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F784758508%2F16473157473', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
