INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23599298698', 'Conjunto Mini Castelo + Boneca Princesa Bela Disney Mattel', 'Características Principais do Produto: Marca: Mattel Linha: Princess EAN: 194735288588 Informações Adicionais: Castelo que se Abre Revelando Casa de Bonecas com Várias Áreas de Brincadeira Ambientes: Quarto da Bela com Cama Dobrável, Sala de Jantar com Mesa Giratória e Banheiro Escondido com Banho de Espuma Inclui 4 figuras: Madame Samovar, Zip, Lumiere e Guarda-Roupa com Portas que se Abrem Boneca Bela com Roupa Clássica Amarela, Saia Macia Removível e Articulações nos Braços, Pernas e Pescoço Alça para Transporte Possibilidade de Empilhar ou Conectar com Outros Conjuntos Benefícios: Permite Recriar Cenas Memoráveis do Filme A Bela e a Fera Proporciona Múltiplas Áreas de Brincadeira Reconhecíveis Pelas Crianças Facilita o Transporte e o Uso Como Brinquedo de Viagem Possibilita Expandir a Brincadeira ao Conectar ou Empilhar outros Castelos Empilháveis Conteúdo: 1 Conjunto Empilhável 1 Boneca 4 Personagens Amigos 4 Acessórios Idade recomendada: A Partir de 3 Anos Fornecedor: Mattel Do Brasil Ltda', 181.85, 164.9, NULL, 'Hobbies & Collections > Toys & Games > Others', 'https://cf.shopee.com.br/file/sg-11134201-824gp-mpiaf57uhq0y4b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F822103155%2F23599298698', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
