INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20201179139', 'Borracha Vedação Porta Polo Hatch Sedan 2002 Em Diante', 'Os veículos possuem componentes de borracha nas portas, porta malas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Essas borrachas protetoras são conhecidas como guarnição, e, além de serem instaladas no teto e nas portas, também podem ser encontradas nas áreas de contato entre capô, no porta-malas e nos vidros, evitando o contato direto da tampa com a carroceria. Modelos Compativeis: Polo Hatch – 2002 em diante Polo Sedan – 2002 em diante Especificações: O valor é referente a unidade Borrachas na cor preta Produto paralelo de excelente qualidade Borracha Fixada por encaixe Itens Inclusos: 1 Borracha de Vedação da Porta', 62.08, 62.08, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/0acb326a0b58cbdb8d4528fa6820a310', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F691145803%2F20201179139', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58257493518', 'FIO DENTAL JOHNSONS REACH ESSENCIAL 100 METROS', 'REACH® Essencial Menta é um fio dental que remove a placa bacteriana e possui embalagem econômica. Possui agradável sabor de menta. Disponível em embalagem com 100m de fio dental. Como usar fio dental? Retire da embalagem cerca de 50cm de fio. Enrole as pontas nos dedos médios. Prenda o fio entre o dedo indicador e o polegar. Deslize o fio entre os dentes, penetrando um pouco na gengiva, com cuidado. Envolva e limpe todos os dentes. Indicação Uso adulto. A recomendação dos dentistas é substituir a escova a cada três meses de uso ou quando apresenta deformação das cerdas. Para manter a sua saúde bucal em dia, além das visitas periódicas ao dentista, escolha REACH®. As escovas e fios dentais são recomendas por dentistas e feitos para diferentes tipos de necessidade. Para conquistar um sorriso bonito e saudável, e uma boca limpa de verdade, use LISTERINE® na sua rotina diária de higiene bucal.', 19.99, 19.99, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-825zp-mm7iw7i9u2a7e8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1765202114%2F58257493518', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
