INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11823006052', 'Tênis infantil masculinos sapatos de meninos tenis infantil masculino.', 'Tênis infantil masculino club happy. INFORMAÇÕES TÉCNICAS + Fechamento por ELÁSTICO, muito fácil de calçar (não é de cordão) + Cor – Selecionar cor desejada acima do botão comprar. + Material – Sintético. + Peso -- 300g pode variar de acordo com tamanho. + Solado – Emborrachado flexível. + Palmilha – Macia com aplique da Club Happy. + Numeração: Será enviada pelo critério de escolha + Caixa embalagem: cada par vai a sua caixa individual. Como tirar suas medidas: Em um papel, desenhe o contorno dos pés descalços. Meça do dedão até o calcanhar. Adicione 0,5 cm de folga. TABELA DE TAMANHO Em CENTÍMETROS DA PALMILHA 20 ----------------------------- 13,3 cm 21 ----------------------------- 13,8 cm 22 ----------------------------- 14,5 cm 23 ----------------------------- 15,2 cm 24 ----------------------------- 16,0 cm 25 ----------------------------- 16,5 cm 26 ----------------------------- 17,2 cm 27 ----------------------------- 17,8 cm 28 ----------------------------- 19,0 cm 29 ----------------------------- 19,6 cm 30 ----------------------------- 20,3 cm 31 ----------------------------- 21,0 cm 32 ----------------------------- 21,5 cm 33 ----------------------------- 22,3 cm 34 ----------------------------- 22,8 cm A Club Happy Calçados Infantis é uma empresa localizada em Birigui interior de São Paulo, somos uma empresa referência no segmento de calçados infantis, com maquinários de última geração e tecnologia robótica para produção, a Club Happy se torna conhecida por produzir calçados com uma qualidade incomparável e preços acessíveis.', 79.9, 72.2, NULL, 'Baby & Kids Fashion > Boy Shoes > Sneakers', 'https://cf.shopee.com.br/file/br-11134207-81z1k-me4b9oc8lu6a33', 'https://shope.ee/an