INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19255453272', 'CARTILHA CAMINHOS DA ALFABETIZACAO', 'Feito pela professora Christiane Peters, o objetivo deste livro, é ensinar de forma sistematizada e dentro dos melhores padrões e práticas para esta respectiva fase da criança. Os métodos que abordamos ensinam as crianças a manipularem os sons das letras, das sílabas, combiná-las e decodificá-las para que possam formar e escreve palavras e assim desenvolver todas essas habilidades.', 24.9, 24.9, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rasx-mafudjylevdu7c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F19255453272', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8554918335', 'Essencial 9 - Eaa Aminoácidos Essenciais 225g - Bodyaction', 'ESSENCIAL-9 INGREDIENTES: L-Leucina, L-Isoleucina, L-Valina, Maltodextrina, Lisina (Acetato de L-lisina), L-Treonina, Triptofano, L-Histidina, L-Fenilalanina, L-Metionina, Vitamina B6 (Cloridrato de piridoxina), Vitamina C (Ácido ascórbico), Niacina (Nicotinamida), Ácido pantotênico (Pantotenato de cálcio), Vitamina B2 (Riboflavina), Vitamina B1 (Nitrato de tiamina), Ácido fólico (Ácido pteroilmonoglutâmico), Vitamina B12 (Cianocobalamina), Acidulante ácido cítrico, Aroma idêntico ao natural de guaraná com açaí, Antiumectante Dióxido de silício, Edulcorante Sucralose e Corantes Vermelho Bordeaux e Azul brilhante. NÃO CONTÉM GLÚTEN. ALÉRGICOS: PODE CONTER DERIVADOS DO LEITE* *Produzido em equipamento onde se processam estes alimentos, contudo, ações preventivas de limpeza são adotadas para evitar essa ocorrência. MODO DE PREPARO: Dissolva 15 g (aproximadamente 2 dosadores) em 250 ml (1 copo americano) de água ou bebida de sua preferência. SUGESTÃO DE USO: Consumir 1 (uma) porção 1 (uma) vez ao dia antes ou após o treino. PRODUTO INDICADO PARA MAIORES DE 19 ANOS. ADVERTÊNCIAS: "ESTE PRODUTO NÃO É UM MEDICAMENTO. "NÃO EXCEDER A RECOMENDAÇÃO DIÁRIA DE CONSUMO INDICADA NA EMBALAGEM''. "MANTENHA FORA DO ALCANCE DE CRIANÇAS". "ESTE PRODUTO NÃO DEVE SER CONSUMIDO POR GESTANTES, LACTANTES E CRIANÇAS". CONSERVAÇÃO: Manter em lugar fresco, não úmido e ao abrigo da luz. Não consumir o produto se o lacre de proteção estiver violado. Após aberto, consumir preferencialmente em 30 dias.', 124.88, 79.99, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-820ma-mnwwzkh5p98i74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F443076516%2F8554918335', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
