INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209207045', 'Kit 3 Bloco Adesivo Deli 76x51mm com 4 Cores Neon e 100 Folhas', 'O bloco adesivo Deli 76x51mm é ideal para anotações rápidas, lembretes, marcações e organização no dia a dia. Com 4 cores neon e 25 folhas por bloco, oferece melhor classificação visual e destaque das informações importantes. A escrita é suave e o adesivo possui boa fixação, podendo ser aplicado em diversas superfícies de forma prática para uso em escritório, escola e casa. ✔ Tamanho 76x51mm ✔ 4 cores neon vibrantes ✔ 4 blocos com 25 folhas cada ✔ Boa aderência e fácil de destacar ✔ Escrita suave para uso diário ✔ Ideal para recados, marcações e organização ✔ Indicado para escritório, estudo e uso doméstico', 14.9, 14.9, NULL, 'Stationery > Notebooks & Papers > Memo & Sticky Notes', 'https://cf.shopee.com.br/file/sg-11134201-81ztn-mn9g1tnqw550da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1747380222%2F58209207045', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
