INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5593233200', 'Kit 2 Calças Leggings Sublimadas Yoga Cintura Alta', 'KIT 2 LEGGINGS CÓS ALTO MESCLAS SUBLIMADAS NÃO TEM TRANSPARÊNCIA , TECIDO SUPLEX 350 GRAMATURA E 12 % ELASTANO. ### Calça Legging Feminina Fitness Academia Cintura Alta Estampada Mescla **Conforto e Estilo para Seus Treinos** Apresentamos a Calça Legging Feminina Fitness Academia Cintura Alta Estampada Mescla, a escolha perfeita para quem busca aliar conforto e estilo durante os exercícios. Com uma gramatura de 330, essa legging oferece uma sensação de firmeza e suporte, ideal para atividades físicas intensas. **Design Moderno e Funcional** Com um design estampado em mescla, essa calça legging se destaca pela sua estética moderna, permitindo que você se sinta confiante e estilosa na academia ou em qualquer atividade do dia a dia. A cintura alta proporciona um ajuste perfeito, valorizando a silhueta e garantindo liberdade de movimento. **Material de Alta Qualidade** Feita com um tecido de alta qualidade, a Calça Legging Feminina Fitness é respirável e confortável, ideal para manter você fresca durante os treinos. Sua gramatura de 330 garante durabilidade e resistência, tornando-a uma peça essencial no seu guarda-roupa fitness. **Versatilidade para Todas as Ocasiões** Seja para uma sessão de yoga, corrida ou até mesmo para um passeio casual, essa legging se adapta a diversas situações. Combine com suas blusas favoritas e crie looks incríveis, prontos para qualquer desafio. Experimente a Calça Legging Feminina Fitness Academia Cintura Alta Estampada Mescla e descubra como é fácil se sentir bem e bonita enquanto se exercita!', 119.99, 101.99, NULL, 'Women Clothes > Pants & Leggings > Leggings & Treggings', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mddmnc0nicjl43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F336042646%2F5593233200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8459515189', 'Caneta hidrográfica Color 850-L JR com 12 cores Pilot', 'Produto certificado no âmbito brasileiro de qualidade, conforme Portaria Inmetro Nº 333/2012: Segurança, Compulsório, Registro 002832/2013, OCP0046, INMETRO Caneta hidrográfica Color 850-L JR - com 12 cores - Pilot Desenvolvido para crianças, o jogo Pilot Color 850-L Junior é ideal para desenhar, pintar e fazer tracejados. Possui tinta especial atóxica a base de água que apresenta cores muito mais vivas e intensas. Além disso, sua tinta é lavável, não mancha e sai facilmente de tecidos, facilitando a lavagem das roupas. O jogo conta com 12 cores que oferecem um leque de criatividade para as crianças, auxiliando no desenvolvimento da criatividade e da coordenação motora. Descrição - Ponta de poliéster 4.0 mm. - Escrita 1.8 mm. - Tinta à base de água. - Não recarregável. - Estojo com 12 cores sortidas. - Produto não recarregável.', 55.56, 55.56, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-7qvf6-lgd56f34ctxdbf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F8459515189', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
