INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46409728720', 'Scarpin Slingback Vizzano Feminino Salto Bloco Grosso Mary Jane', '- Todos os nossos produtos são originais e acompanham nota fiscal – - Enviamos seu pedido em até 24h úteis – Slingback Feminino Vizzano Salto Bloco Elegante Confortável Moderno 1373112 O slingback Vizzano é a escolha perfeita para quem busca elegância com um toque moderno no dia a dia. Com design sofisticado e detalhes delicados, ele valoriza a produção sem abrir mão do conforto. POR QUE ESSE MODELO SE DESTACA? - Visual moderno e elegante Modelo fechado na frente e aberto atrás, com bico quadrado - Ajuste perfeito no pé Duas tiras com fivelas que permitem regulagem - Conforto prolongado Interior acolchoado com palmilha macia - Altura com estabilidade Salto bloco que proporciona mais segurança ao caminhar - Acabamento sofisticado Detalhes que elevam o visual IDEAL PARA: - Trabalho - Eventos - Passeios - Quem busca elegância com conforto FICHA TÉCNICA: MARCA: Vizzano MODELO: Slingback Feminino MATERIAL EXTERNO: Sintético de alta qualidade MATERIAL INTERNO: Têxtil forrado e acolchoado PALMILHA: Anatômica com espuma de alta densidade SOLADO: Emborrachado com frisos antiderrapantes SALTO: Aproximadamente 7 cm TIPO DE SALTO: Bloco TABELA DE MEDIDAS 34 – 23,4 cm 35 – 24 cm 36 – 24,6 cm 37 – 25,8 cm 38 – 27 cm 39 – 27,7 cm 40 – 28,3 cm Garantia do vendedor: 30 dias', 189.9, 159.99, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/sg-11134201-820nb-mnn61oujs7ib06', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F591297390%2F46409728720', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259245107', 'Cortina de Ar EOS 180cm com Controle Remoto CA1218C 220V', '🔥 Cortina de Ar EOS 180cm com Controle Remoto CA1218C 220V ✨ Transforme o seu espaço comercial em um ambiente mais confortável, higiênico e eficiente. A Cortina de Ar EOS cria uma poderosa barreira de vento que impede a troca de ar entre o ambiente interno e externo, mantendo a climatização estável e reduzindo perdas de energia. ✨ Destaques do Produto: ✅ Cria barreira de ar entre ambiente interno e externo, evitando perda de climatização ✅ Ideal para comércios com portas abertas como lojas, mercados e restaurantes ✅ Instalação horizontal acima da porta (altura recomendada: 2,3m até 3m) ✅ Alta vazão de ar para isolamento térmico eficiente ✅ Reduz a entrada de insetos, poeira, fumaça, poluição e odores ✅ Ajuda na economia de energia de até 35% ✅ Contribui para maior vida útil de ar-condicionado e equipamentos de refrigeração ✅ Sistema de rolamento com maior durabilidade e resistência ✅ Controle remoto para ajustes práticos e rápidos ✅ Mantém o ambiente mais limpo, confortável e profissional 📏 Medidas do Produto (LxAxP/cm): 180 x 14,5 x 18,5 cm 💎 Mais eficiência, proteção e economia para o seu ambiente comercial com tecnologia EOS.', 989.01, 989.01, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-820ny-mnagch9ts0020e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1527564302%2F58259245107', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899572038', 'Boia Infantil Colete Salva Vidas Desenho Etitoy', 'DISTRIBUIDO POR ISMAFER FERRAMENTAS Boia colete stitch 56cm Explore um mundo de diversão com nossa linha de infláveis da Etitoys! Criada para alegrar qualquer brincadeira com segurança, a linha Etitoys traz uma variedade incrível de produtos pensados para proporcionar horas de entretenimento para as crianças. Com designs coloridos e duráveis temos tudo o que você precisa para transformar qualquer ocasião em uma brincadeira inesquecível que vai encantar e cativar a criançada. Dimensões da Peça: 56 x 12 x 16cm Espessura: Capacidade: Tipo de Embalagem: SOLAPA DE PAPELAO COM FURO E GRAMPO Material: Poliéster e Espuma Cor: Sortido • O Mix de cores é variável e na entrega você pode receber 1 ou 2 estampas. Marca: ETITOYS Origem: China Composição do Produto: 1 unidade Caracteristicas Importantes: SPIDERMAN Instruções de Uso: N/A Antes do Uso: • Verificar se o produto está em perfeitas condições de uso; • Verifique se a boia não possui furos ou áreas desgastadas que possam causar vazamentos; • Certifique-se de que todas as válvulas estejam bem fechadas e funcionando corretamente. Perigos: N/A Cuidados: • Sempre supervisione a criança enquanto estiver usando a boia. Nunca deixe a criança sozinha na água, mesmo por um breve momento; • Mantenha a boia longe de objetos pontiagudos ou afiados que possam perfurá-la. Cuidado ao usá-la perto de superfícies ásperas; • Após o uso, limpe a boia com água limpa e deixe-a secar completamente antes de guardá-la; • Armazene em um local fresco e seco, longe da luz solar direta, para evitar danos ao material. Advertencia/ Atenção: • Este produto deve ser montado por um adulto; • Este produto não é um equipamento salva-vidas; • Para evitar o perigo de asfixia, manter a embalagem longe do alcance das crianças. SKU: 24380 DISTRIBUIDO POR ISMAFER FERRAMENTAS', 130.0, 69.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Swimming & Diving', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mimz7g7x01dy4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F360012700%2F21899572038', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
