INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19599832724', 'KIT 2 ESPUMA LIMPA TUDO 400ML COURO SOFÁ TÊNIS TAPETE UNIPEGA', 'Espuma Limpa Tudo Unipega é uma espuma de ação profunda e concentrada, que remove a sujeira mais difícil de forma simples e prática, sem precisar de força nem enxágue. Restaura a cor e a aparência original das superfícies. Pode ser utilizado na limpeza geral de estofados, carpetes, camurça, vinil, almofadas, fórmicas, papéis de parede, pisos, azulejos ou qualquer superfície lavável ou pintada. Ambiente para aplicação: Banheiro, Cozinha, Garagem, Quarto e Sala SPRAY ESPUMA LIMPA TUDO UNIPEGA 400ML KIT 2 ESPUMA LIMPA TUDO 400ML COURO SOFÁ TÊNIS TAPETE UNIPEGA', 48.57, 48.57, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mfiduj8phj479a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343260914%2F19599832724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20998019760', 'TINTA POLIÉSTER PRETO ECLIPSE PEROL 2009 TOYOTA 900ML LAZZUDUR', 'TINTA AUTOMOTIVA POLIÉSTER 900ML LAZZUDUR A tinta automotiva à base Poliéster da Lazzuril é indicado para pintura geral, parcial e retoques de veículos automotivos, nacionais e importados, fácil de usar e aplicar. Disponível em sistema mixing machine ( lisas, metálicas e perolizadas). Possui secagem rápida, excelente resistência às intempéries naturais e agentes químicos. Padrão Original Base Poliéster Pronta para Uso Requer aplicação de verniz automotivo após a aplicação da tinta. Conteúdo: 900ML TINTA POLIÉSTER PRETO ECLIPSE PEROL 2009 TOYOTA 900ML LAZZUDUR', 110.91, 110.91, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-7rbkq-m5khjpuhw1xcd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1343260914%2F20998019760', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993475882', 'KIT 03 Baby Tee Feminina - Blusa Slim Fit Manga Curta - Blusa de Compressao Baby Tee', 'KIT COM TRES BLUSAS - CONTÉM TRES (3) BLUSAS Você está prestes a adquirir um produto lindíssimo da marca Moderna & Slim. Temos mais de 200 mil estrelinhas e avaliações positivas em lojas online, mais de 1000 variações de produtos e uma ampla gama de cores e tamanhos. Na Moderna você vai encontrar, croppeds e tops, vestidos, saias, blusas, bodys, calças e shorts jeans, jaquetas, conjuntos, macacões, moda praia e peças esportivas fitness. Todos os produtos são de pronta entrega para postagem imediata em até 24h. O nosso objetivo é deixar você linda (o) pagando pouco, por isso temos certeza de que estamos no caminho certo. Apresentamos a blusa baby tee, a peça essencial que combina estilo e conforto em perfeita harmonia. Confeccionada em tecido romantic, esta blusa foi ajustada para dar um realce a sua silhueta. Ideal para diversas ocasiões, desde um look casual de dia, atividades ao ar livre ou uma produção mais elaborada à noite. A blusa slim fit oferece o equilíbrio perfeito entre estilo e praticidade e foi desenhada para se moldar suavemente ao seu corpo, proporcionando um visual moderno. - Caso não encontre o tamanho ou cor desejada nesse anúncio, você deverá acessar a nossa loja na Shopee no botão "Ver Loja". Na parte superior da loja você irá encontrar a opção "CATEGORIAS", e posteriormente a opção BLUSA", lá você irá encontrar todas as cores disponíveis. Atenção ao caimento! Essa blusa tem modelagem SLIM e, por ser uma baby tee, a proposta é realmente ficar mais justinha ao corpo. Se você prefere um caimento mais confortável ou certinho (sem ficar tão colada), nossa dica é escolher um tamanho maior que o seu habitual. Guia de tamanhos: P veste 34/36 M veste 38 G veste 40 Ficou com dúvida? Chama a gente! 💬 Tamanhos: (veste 36) - Tamanho P (veste 38) - Tamanho M (veste 40) - Tamanho G Modelo Veste M: Altura: 1,77 | Busto: 90 | Cintura: 65 | Quadril: 100 | Peso: 64 | Tamanho Blusa: M - Sobre o material: - Blusa Slim Justinha - Opções disponíveis no tecido romantic - Composição: 92% Poliéster 8% Elastano - Não tem Bojo - Manga Curta - Justa no Corpo Fotos dos anúncios: - As fotos e vídeos são reais. As modelos são contratadas pela nossa marca, portanto, as peças retratam fielmente os nossos produtos.', 89.99, 42.99, NULL, 'Women Clothes > Tops > T-shirts', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1r73g9iscsx1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F283972864%2F23993475882', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
