INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21961859341', 'FILTRO DE AR FAZER 150 CROSSER 150 2014 FILTRAN', 'Filtro de Ar Fazer 150 / Crosser / Factor 150 - Filtran Filtro de Ar Fazer 150 / Crosser / Factor 150- FiltranFundamental para o bom funcionamento do motor do carro, o filtro de ar é a peça responsável por reter impurezas do ar que podem se instalar no motor. O filtro de ar é de extrema importância, por que ele elimina as impurezas que existem no ar do carro, para a mistura ar/combustível gerar uma combustão perfeita. Se o seu filtro estiver sujo e velho seu carro não passa na inspeção veicular, sem contar que se você rodar com o filtro de ar sujo seu consumo de combustível vai ser bem mais alto.Compatível com:*FAZER 150*XTZ 150 CROSSER*FACTOR 150 (A PARTIR DE 2014)*IMAGEM ILUSTRATIVA*', 26.0, 26.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-22110-e7ujidq4mrjv93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842545535%2F21961859341', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
