INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798644142', 'Conjunto com 6 Xícaras de Chá Neo com Pires Neo Latte 210ml', 'O Stoneware, assim como a faiança feldspática e porcelana, é um material cerâmico. O Stoneware Porto Brasil é um material inovador e sustentável, onde a combinação das melhores matérias primas naturais, unido a um processo único de queima e acabamento manual, entregam um produto com características superiores em termos de qualidade e resistência, estando em conformidade com as principais normas mundiais. Além disso, conseguimos proporcionar peças exclusivas, onde alterações de formas, relevos e variações de cores são efeitos característicos dos produtos, evidenciando assim sua originalidade e autenticidade.', 449.9, 292.44, NULL, 'Home & Living > Dinnerware > Tea Pots & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7ratn-maygtnp5v4nk70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242213783%2F22798644142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899682930', 'Capa Case Capinha Rainbow Magsafe Transparente iPhone 16 Pro Max Gshield – Efeito Arco-Íris', 'A Capa Rainbow Transparente da Gshield traz uma nova perspectiva para a proteção do seu smartphone, combinando resistência, funcionalidade e um design exclusivo. Desenvolvida para realçar a estética do aparelho sem comprometer a segurança, a capa se destaca por sua transparência impecável e pelo efeito Rainbow, que reflete tonalidades sutis conforme a incidência da luz, criando um visual dinâmico e sofisticado. Fabricada com materiais de alta qualidade, ela une policarbonato rígido na parte traseira e TPU flexível nas laterais, garantindo máxima durabilidade e uma absorção eficiente de impactos. Essa composição protege contra quedas, arranhões e desgastes do dia a dia sem comprometer a leveza e a ergonomia do aparelho. O ajuste preciso ao iPhone garante acesso facilitado a todas as conexões, botões e sensores sem interferir na experiência do usuário. As bordas elevadas ao redor da tela e do módulo de câmeras oferecem proteção extra contra superfícies, minimizando o risco de danos. Outro grande diferencial é a compatibilidade com carregamento MagSafe, permitindo que você recarregue seu aparelho sem precisar remover a capa. Mais do que um acessório, a Capa Rainbow Transparente da Gshield é uma escolha inteligente para quem busca proteção eficiente sem abdicar do design original do dispositivo. Com um toque de modernidade e sofisticação, ela transforma a maneira como você protege seu dispositivo, garantindo segurança e estilo em um único produto. Garanta já a sua e experimente a fusão perfeita entre resistência e elegância! ESPECIFICAÇÕES - Marca: Gshield - Material: Policarbonato e TPU - Dimensões: Dimensões exatas do aparelho - Proteção: Contra impactos e riscos - Cor: Transparente/Rainbow COMPATIBILIDADE - iPhone 16 Pro Max ITENS INCLUSOS - 1x Capa protetora', 78.99, 78.99, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rd3k-m7w6iwpoaefrc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F18899682930', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899839064', 'Playground Infantil 4x1 Escorregador Cesta Telescópio Bege Espaço Multifuncional Importway', 'Playground Infantil 4x1 Escorregador, Cesta Basquete, Telescópio, Espaço Multifuncional Importway Playground Importway 4x1 irá trazer a diversão da criançada, e além de tudo ele tem a opção de escorregador, telescópio, espaço multifuncional e uma cesta para jogar basquete e ter um dia de muita diversão. Ele possui um designer lindo e moderno. Especificações: • Marca: Importway • Modelo: BW391BG • Playground infantil 4x1 com escorregador, telescópio, cesta e espaço multifuncional inferior • Indicado para crianças a partir de 3 anos • Dimensões do produto montado: 176 x 66,5 x 86 cm • Peso máximo 36kg • Produto certificado pelo INMETRO Conteúdo da Embalagem: - 01 Playground Infantil 4x1 Importway Bege "Compra Garantida" - Ao Comprar conosco a sua compra é 100% garantida, o seu dinheiro está seguro até a entrega. *Garantia 90 dias. *Imagens meramente ilustrativas Importway Importando Soluções com Qualidade, Inovação e Responsabilidade desde 2007.', 684.86, 609.0, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mj7hm3xhhjwmfe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1229255557%2F19899839064', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
