INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23492821599', 'Carburador Tldz Gol Parati Voyage Saveiro Ap 1.8 Gasolina', 'Carburador 1.8 AP / TLDZ / GASOLINA / WEBER / DUPLO Aplicação: VW GOL 1.8 / AP / 90 A 96 VW VOYAGE 1.8 / 90 A 96 VW PARATI 1.8 / 90 A 96 VW SAVEIRO 1.8 / 90 A 96 Marca: Mecar - Indústria 100% brasileira Especificação Técnica: Código MECAR: CN495018 Conteúdo da Embalagem: 1 UNIDADE - CARBURADOR TLDZ / WEBER / DUPLO / GASOLINA Importante: - Garantia de 6 Meses. - Valor do unitário. - Trabalhamos somente com produtos novos e com garantia. - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. - O Direito a garantia é imediatamente cancelado em caso de alterações, adaptações e ou mau uso do produto.', 1250.61, 1144.64, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rcc3-lr4vzatcls6l71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175807175%2F23492821599', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '3021816468', 'Sintra Pro 1,5L Vonixx Limpeza Interna Automotiva Bactericida', 'SINTRA PRO 1,5L - LIMPEZA INTERNA DE VEÍCULOS DESCRIÇÃO: Sintra Pro é um multilimpador flotador bactericida de pH balanceado e ultra concentrado, indicado para limpeza de painéis, laterais e cantos de portas, bancadas de couro, carpetes e estofados. Promove alto poder de remoção de manchas de gordura e sujeiras diversas, além de eliminar microrganismos causadores de doenças no interior do veículo DILUIÇÃO: Limpeza de laterais de portas, plásticos e couro muito encardido – 1:5 Carpetes, estofados e limpeza de teto – 1:10 (sujeira pesada); 1:20 (sujeira média); 1:30 (sujeira leve) Manutenção de limpeza interna em painéis, laterais de portas e bancos de couro – 1:50 MODO DE USO: Em painéis, laterais e cantos de portas e bancos de couro: 1. Diluir o produto na proporção conforme indicação 2. Com o auxílio de um pulverizador, aplicar a solução na área a ser limpa 3. Utilizar pincel, escova macia ou aplicador de espuma e realizar movimentos circulares até observar o desprendimento total da sujeira 4. Remover o excesso com auxílio de toalha de microfibra úmida Em carpetes, estofados e tecidos: 1. Diluir o produto na proporção conforme indicação 2. Com o auxílio de um pulverizador, aplicar a solução na área a ser limpa 3. Utilizar escova macia ou aplicador de espuma e realizar movimentos circulares até observar o desprendimento total da sujeira 4. Utilizar aspirador específico para remoção de água e aspirar toda a sujeira 5. Aguarde secar completamente', 62.92, 62.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Others', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lnsokkgd8x8n79', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F3021816468', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43159933706', 'IELGY Sapatos De Água Leves Antiderrapantes Borracha Com Sola Macia À Prova D''água Cordão Para Mulheres', 'Marca: IELGY Altura do salto: cerca de 1-3 CM 1cm=0,393pol (Medição Manual, erro de 1-3 cm pertence à faixa normal) O pacote de sapatos inclui: um par de sapatos Nota: O produto não tem caixa de sapatos (O produto está em sacos, e a caixa de sapatos precisa ser comprada separadamente, por favor, pergunte ao atendimento ao cliente, obrigado ~) Obs: Chinelos são geralmente maiores e mais confortáveis, caso não tenha certeza de qual tamanho é semelhante, por favor pegue um tamanho maior Tamanho do sapato: largura do pé ou dedo do pé pequeno ou salto alto, de acordo com sua própria situação e o tamanho do sapato habitual é recomendado para escolher um tamanho maior. Estilo da chuva: botas de chuva Estilo coreano: estilo coreano Padrão: Cor sólida Forma do dedo do pé do sapato: dedo do pé redondo Material superior do sapato: PVC Material interno: Microfibra Material da sola: PVC Altura do salto: salto baixo (1-3cm) Forma do salto: fundo plano Estilo de uso: cordão Cor da Caixa: Preto, Marrom, Verde', 222.71, 149.6, NULL, 'Women Shoes > Boots > Rain Boots', 'https://cf.shopee.com.br/file/sg-11134201-7rdwg-mck99yae7mjqdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217877619%2F43159933706', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16327073511', 'Limpador Multiação Multiuso Limpa Plástico Painel Vintex 1,5', 'LIMPADOR MULTIAÇÃO 1,5L VINTEX DESCRIÇÃO: - Remove sujeiras mais difíceis; - Limpa com segurança; - Limpeza automotiva e doméstica. O LIMPADOR MULTIAÇÃO foi desenvolvido para remover sujeiras mais difíceis e de diversas naturezas. Sua formulação balanceada, limpa com segurança vários tipos de sujeiras como: Gorduras, manchas e encardidos de bancos, tetos, painéis, laterais de porta, etc. No lar, pode ser utilizado em: Azulejos, fogões, computadores, telefones e limpeza em gera MODO DE USAR: - Aplicar o produto na superfície a ser limpa, esfregando com o Aplicador de Espuma; - Em seguida remova o excesso com a toalha ou Pano de microfibra levemente úmido; - Se necessário repita a operação.', 49.92, 49.92, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/261900943b3b591fb5037900cd3b5582', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F16327073511', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19097624931', 'Pneu Pretinho Brilho Alto Proteção Resistente Agua 5L Vonixx Vintex', 'PNEU PRETINHO 5L VINTEX DESCRIÇÃO: O Pneu Pretinho é um produto que foi especialmente desenvolvido para proteger, conservar e dar brilho aos pneus em geral. Promove proteção prolongada, brilho intenso e duradouro que deixa os pneus com aspecto de novos. - Brilho molhado - Super concentrado MODO DE USO: 1. Lave bem os pneus removendo toda a sujeira como lama, barro, etc... 2. Em seguida, aplique o produto puro com o auxílio do Aplicador de Espuma', 71.87, 71.87, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Brighteners', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lrj3sa80tvdw26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F19097624931', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197777574', 'Scarpin Feminino Lumiss Confortável Slingback Fivelas Salto Fino Bico Fino Verniz Preto', 'Nosso scarpin é uma combinação perfeita de elegância e modernidade. O acabamento em verniz proporciona um brilho sofisticado, enquanto as tiras com fivelas adicionam um toque de estilo e personalidade ao calçado. Ideal para ocasiões especiais ou para dar um upgrade em looks casuais, este scarpin é a escolha certa para quem deseja aliar conforto e glamour. ..:::.. ESPECIFICAÇÕES DO PRODUTO ..:::.. *Material Externo - Verniz Sintético *Material Interno - Helanca, Têxtil Confortável *Solado - PVC Expandido, não escorrega, emborrachado, não faz barulho, anti-derrapante. *Altura do Salto - 8,0 cm. *Palmilha - Confortável com aplique da logo. Medida aproximada dos pés para cada numeração: Tamanho 34 --- 25,1 cm Tamanho 35 --- 25,8 cm Tamanho 36 --- 26,5 cm Tamanho 37 --- 27,1 cm Tamanho 38 --- 27,8 cm Tamanho 39 --- 28,5 cm Tamanho 40 --- 29,1 cm SOBRE A LUMISS: Desde 2018, brilha no coração da Lumiss a inovação para calçados femininos. Nascida como Amorelle, a marca é fruto do sonho de um visionário que sempre acreditou na possibilidade de fabricar calçados que surpreendessem o mercado, tanto pela variedade quanto por seus preços acessíveis. Com muito trabalho em família, essa ideia foi levada adiante, fortalecendo uma marca que hoje é referência nacional em calçados femininos, com presença marcante nos marketplaces e mais de dois milhões de pares já entregues em todo o Brasil. Comprometida com cada cliente, a Lumiss oferece as maiores tendências do mundo da moda a partir de materiais que garantem conforto, qualidade, sofisticação e estilo aos pés da mulher brasileira, encantando até mesmo os perfis mais exigentes. Além disso, a empresa se preocupa em oferecer a melhor experiência de compra, com total segurança e praticidade. Lumiss é mais que uma marca. É uma ideia que chegou para mostrar que todas as mulheres podem brilhar e ser ainda mais lindas e confiantes com calçados que as valorizam em todos os aspectos.', 149.9, 89.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0388drb70q174', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F323760756%2F22197777574', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16830147266', 'Cabo curto Slim 3 em 1 - Micro USB / Lightning / Tipo C - Gshield', 'O Cabo Slim 3 em 1, da GShield, possui 3 entradas (Type C, Lightning e Micro USB V8) em um único cabo. Além disso, ele ainda tem um revestimento emborrachado e formato flat, para maior durabilidade; conectores mais largos, para melhor transferência de dados e energia, e uma presilha magnética, que une ambos os conectores. Obs.: Esse produto não possui suporte ao carregamento Quick Charger 2.0 e 3.0, entretanto carrega o aparelho de forma eficaz. ATENÇÃO: Na hora de usar e guardar o cabo deve-se tomar cuidado para NÃO DOBRAR as pontas do acessório. Ainda que ele seja reforçado, o ato de dobrá-lo com frequência danifica o interior do objeto! Se tiver dúvidas utilize o campo de perguntas no final da página ou leia as avaliações de outros consumidores. ESPECIFICAÇÕES Material: revestimento emborrachado Marca: Gshield Tamanho (fechado): 6.5cm Tamanho (aberto): 14.5cm Peso: 10 gramas', 7.7, 7.7, NULL, 'Mobile & Gadgets > Accessories > Cables, Chargers & Converters', 'https://cf.shopee.com.br/file/eebc19acab1c41823570f89467686b4c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F16830147266', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22097317391', 'Capa Case Capinha Clear View para iPad Mini 6 - Gshield - Proteção 360° com Suporte e Porta-Lápis', 'A fusão perfeita entre proteção avançada e funcionalidade prática para o seu iPad! A Capa Clear View para iPad, da Gshield, oferece uma defesa completa de 360° para a parte frontal e traseira do seu dispositivo. Sua estrutura leve e fina foi projetada para garantir a máxima proteção sem comprometer a elegância do seu iPad. Além disso, o mecanismo magnético inteligente assegura que o aparelho desperte ao abrir a capa e entre em repouso quando fechada, preservando a vida útil da bateria. Com sua funcionalidade prática, a parte frontal da capa Clear View pode ser dobrada em diferentes posições, transformando-se em uma base versátil para leitura, digitação, visualização de vídeos ou realização de chamadas FaceTime. Além de sua funcionalidade, a capa Clear View também possui um design sofisticado que inclui um discreto porta-lápis especialmente projetado para sua caneta touch, garantindo um armazenamento seguro e de fácil acesso para o acessório. Sua estrutura robusta e durável foi cuidadosamente projetada para resistir a impactos e arranhões, mantendo seu iPad seguro em todas as ocasiões. Seja em casa, no escritório ou em movimento, a Capa Clear View para iPad, da Gshield, oferece a proteção e a praticidade que você precisa, mantendo-se alinhada ao estilo de vida dinâmico! ESPECIFICAÇÕES Material: PU + TPU Marca: Gshield Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos do dia a dia Certificações: Us Military COMPATIBILIDADE iPad Mini 6 ITENS INCLUSOS 1x Capa protetora GARANTIA 3 meses contra defeitos de fabricação', 106.7, 106.7, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7rbkm-lpjo19762q7g54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22097317391', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693902085', 'Capa Case Capinha Anti-Slip MagSafe Gshield para iPhone Transparente – Premium Anti-Derrapante', 'A Capa Anti-Slip Magsafe para iPhone, da Gshield, eleva a proteção do seu dispositivo para outro nível, combinando confiabilidade e design discreto. Além de seu material de alta qualidade, a capa apresenta uma textura lateral que proporciona uma aderência confortável em suas mãos, garantindo um manuseio seguro e ergonômico do seu celular. Fabricada com precisão, a capa preserva a estética original do seu dispositivo ao mesmo tempo, em que oferece uma camada confiável de defesa contra arranhões, pequenas quedas e desgaste diário. Com recortes precisos, todas as portas, botões e funções do seu iPhone permanecem facilmente acessíveis, sem a necessidade de remover a capa. O acabamento anti-derrapante na superfície da capa proporciona uma aderência segura em suas mãos, reduzindo significativamente o risco de quedas acidentais. Agora, você pode se sentir confiante em usar seu celular em diversas situações, sem preocupações com escorregões inoportunos. O grande destaque da capa está na tecnologia MagSafe integrada, que cria um anel de ímãs na parte traseira do celular, estabelecendo uma conexão magnética perfeita com carregadores sem fio compatíveis. Isso significa que você nunca mais terá que se preocupar com a posição correta na base de carregamento, pois a Anti-Slip Magsafe garante que seu dispositivo se alinhe de maneira precisa a cada uso, proporcionando uma experiência de carregamento sem esforço. A Capa Anti-Slip da Gshield é o equilíbrio perfeito entre segurança e estilo, oferecendo proteção premium com um toque de conforto para o seu iPhone. OBS: O smartphone quando superaquecido durante o uso e/ou carregamento, transmite um calor que provoca uma reação química do material da capa que pode ocasionar uma aparência amarelada na mesma. ESPECIFICAÇÕES - Marca: Gshield - Material: Polipropileno de alta densidade - Dimensões: Dimensões exatas do aparelho - Proteção: Contra impactos e riscos à tela - Certificações: Us Military ITENS INCLUSOS - 1x Capa protetora', 79.9, 79.9, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-7repl-m8dkcaklach357', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22693902085', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12220407993', 'Película para Lente de Câmera para Motorola One Vision - Gorila Shield', 'A Película para Lente da Câmera , da Gorila Shield, é projetada para garantir uma proteção extra para a câmera do seu smartphone. Fabricada em vidro temperado ionizado e 0,27mm de espessura, a película da Gorila Shield garante segurança em curtos impactos e riscos do cotidiano.', 1.64, 1.64, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/002f4425a95615892580dd9c5fd9d40c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F12220407993', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
